(function () {
  var live = document.getElementById('live');
  function anunciar(t) { live.textContent = ''; setTimeout(function () { live.textContent = t; }, 50); }

  /* Modal de exclusão: foco preso, Esc fecha, foco volta ao botão de origem */
  var focaveis = 'a[href],button:not([disabled]),input:not([disabled]),select,textarea';
  var aberto = null, origem = null;
  var conf = document.getElementById('confirma-exclusao');
  var btnConf = document.getElementById('btn-confirmar-exclusao');
  function abrir(id, de) {
    aberto = document.getElementById(id); origem = de; aberto.hidden = false;
    var f = aberto.querySelector('input,button'); if (f) f.focus();
  }
  function fechar() {
    if (!aberto) return;
    aberto.hidden = true;
    conf.value = ''; btnConf.disabled = true;
    aberto = null;
    if (origem) origem.focus();
  }
  conf.addEventListener('input', function () {
    btnConf.disabled = conf.value.trim().toUpperCase() !== 'EXCLUIR';
  });
  document.addEventListener('keydown', function (e) {
    if (!aberto) return;
    if (e.key === 'Escape') { fechar(); return; }
    if (e.key === 'Tab') {
      var l = aberto.querySelectorAll(focaveis); if (!l.length) return;
      var p = l[0], u = l[l.length - 1];
      if (e.shiftKey && document.activeElement === p) { e.preventDefault(); u.focus(); }
      else if (!e.shiftKey && document.activeElement === u) { e.preventDefault(); p.focus(); }
    }
  });

  /* Revogar acesso: sem confirmação, com desfazer na própria linha */
  var tabelas = document.querySelectorAll('#acessos table');
  var tabAcessos = tabelas[0];
  var contagem = document.getElementById('contagem-acessos');
  function nomeLinha(tr) { return tr.querySelector('th').textContent.trim(); }
  tabAcessos.querySelectorAll('tbody tr').forEach(function (tr) {
    tr.querySelector('[data-abrir]').setAttribute('aria-label', 'Revogar acesso de ' + nomeLinha(tr));
  });
  tabelas[1].querySelectorAll('tbody tr').forEach(function (tr) {
    var b = tr.querySelector('button');
    if (b) b.setAttribute('aria-label', b.textContent.trim() + ': ' + nomeLinha(tr));
  });
  function contar() {
    var n = tabAcessos.querySelectorAll('tbody tr').length - tabAcessos.querySelectorAll('tbody tr[data-revogado]').length;
    contagem.textContent = n === 0 ? 'Nenhum aplicativo com acesso à sua conta'
      : n + (n === 1 ? ' aplicativo com acesso' : ' aplicativos com acesso') + ' à sua conta';
  }
  function revogar(btn) {
    var tr = btn.closest('tr'), app = nomeLinha(tr);
    var celAcao = btn.closest('td'), celSit = celAcao.previousElementSibling;
    tr._orig = { acao: celAcao.innerHTML, sit: celSit.innerHTML };
    tr.setAttribute('data-revogado', '');
    celSit.innerHTML = '<span class="estado"><span class="ponto exp" aria-hidden="true"></span>Revogado</span>';
    celAcao.innerHTML = '<span class="estado">Acesso revogado.</span> <button type="button" class="btn pequeno" data-desfazer>Desfazer<span class="sr-only"> revogação de ' + app + '</span></button>';
    celAcao.querySelector('button').focus();
    contar();
    anunciar('Acesso de ' + app + ' revogado. Use Desfazer para restaurar.');
    /* integrar aqui a chamada de revogação ao back-end */
  }
  function desfazer(btn) {
    var tr = btn.closest('tr'), cel = btn.closest('td');
    cel.previousElementSibling.innerHTML = tr._orig.sit;
    cel.innerHTML = tr._orig.acao;
    tr.removeAttribute('data-revogado');
    cel.querySelector('button').focus();
    contar();
    anunciar('Revogação desfeita para ' + nomeLinha(tr) + '.');
  }

  document.addEventListener('click', function (e) {
    if (aberto && e.target === aberto) { fechar(); return; }
    var t = e.target.closest('button,a'); if (!t) return;
    if (t.hasAttribute('data-fechar')) fechar();
    else if (t.getAttribute('data-abrir') === 'fundo-excluir') abrir('fundo-excluir', t);
    else if (t.getAttribute('data-abrir') === 'fundo-revogar') revogar(t);
    else if (t.hasAttribute('data-desfazer')) desfazer(t);
    else if (t.id === 'btn-dispensar') document.getElementById('banner-sucesso').hidden = true;
    else if (t.id === 'btn-confirmar-exclusao') {
      /* ligar ao back-end: escutar o evento "conta:excluir" */
      document.dispatchEvent(new CustomEvent('conta:excluir'));
      btnConf.disabled = true;
    }
  });

  /* Validação do perfil: só ao enviar (não durante a digitação) */
  var form = document.getElementById('form-perfil');
  var resumo = document.getElementById('resumo-erros');
  var regras = [
    { id: 'nome', msg: 'Informe seu nome completo.', ok: function (v) { return v.trim() !== ''; } },
    { id: 'email', msg: 'Informe um e-mail válido, como nome@empresa.com.br.', ok: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()); } },
    { id: 'telefone', msg: 'Informe o telefone com DDD, por exemplo (11) 91234-5678.', ok: function (v) { var d = v.replace(/\D/g, ''); return v.trim() === '' || d.length === 10 || d.length === 11; } }
  ];
  function marcar(r, erro) {
    var el = document.getElementById(r.id), campo = el.closest('.campo'), p = document.getElementById('erro-' + r.id);
    if (el.dataset.desc0 === undefined) el.dataset.desc0 = el.getAttribute('aria-describedby') || '';
    if (erro) {
      if (!p) { p = document.createElement('p'); p.className = 'erro'; p.id = 'erro-' + r.id; campo.appendChild(p); }
      p.textContent = r.msg;
      el.setAttribute('aria-invalid', 'true');
      el.setAttribute('aria-describedby', (el.dataset.desc0 + ' ' + p.id).trim());
      campo.classList.add('campo-erro');
    } else {
      if (p) p.remove();
      el.removeAttribute('aria-invalid');
      if (el.dataset.desc0) el.setAttribute('aria-describedby', el.dataset.desc0); else el.removeAttribute('aria-describedby');
      campo.classList.remove('campo-erro');
    }
  }
  function esconderResumo() {
    resumo.hidden = true;
    document.getElementById('aviso-sessoes').hidden = false;
  }
  form.addEventListener('submit', function (e) {
    var erros = [];
    regras.forEach(function (r) {
      var ok = r.ok(document.getElementById(r.id).value);
      marcar(r, !ok);
      if (!ok) erros.push(r);
    });
    if (!erros.length) return;
    e.preventDefault();
    var ul = resumo.querySelector('ul'); ul.innerHTML = '';
    erros.forEach(function (r) {
      var li = document.createElement('li'), a = document.createElement('a');
      a.href = '#' + r.id; a.textContent = r.msg; li.appendChild(a); ul.appendChild(li);
    });
    document.getElementById('h-resumo').textContent = erros.length === 1 ? 'Corrija 1 campo para salvar' : 'Corrija ' + erros.length + ' campos para salvar';
    resumo.hidden = false;
    document.getElementById('banner-sucesso').hidden = true;
    document.getElementById('aviso-sessoes').hidden = true;
    resumo.focus();
  });
  resumo.addEventListener('click', function (e) {
    var a = e.target.closest('a'); if (!a) return;
    e.preventDefault();
    document.querySelector(a.getAttribute('href')).focus();
  });
  form.addEventListener('input', function (e) {
    var r = regras.filter(function (x) { return x.id === e.target.id; })[0];
    if (!r || e.target.getAttribute('aria-invalid') !== 'true' || !r.ok(e.target.value)) return;
    marcar(r, false);
    var a = resumo.querySelector('a[href="#' + r.id + '"]'); if (a) a.parentNode.remove();
    if (!resumo.querySelector('li')) esconderResumo();
  });
  form.addEventListener('reset', function () {
    regras.forEach(function (r) { marcar(r, false); });
    esconderResumo();
  });
})();
@@ FIM

@@ DECISOES
- Os erros pré-exibidos (e-mail "inválido" e "!" no telefone) foram removidos do carregamento; a validação roda só ao enviar e depois some campo a campo conforme a pessoa corrige | regra: FC19
- Ao enviar com erro, aparece um resumo de erros com links para os campos, o foco vai para ele e cada campo ganha mensagem em texto ligada por aria-describedby | regra: FC19
- O banner verde de "preferências salvas" (com horário fixo falso) começa oculto, e o aviso de sessões é escondido enquanto o resumo de erros estiver visível, para nunca haver banner junto do resumo | regra: NE33
- A exclusão de conta passa a exigir digitar "EXCLUIR" antes de habilitar o botão, e o botão se chama "Excluir minha conta" | regra: NE42
