function $(id){return document.getElementById(id);}
function brl(n){return n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}).replace(/\s/g,' ');}
function num(t){return parseFloat(String(t).replace(/[^\d,]/g,'').replace(',','.'))||0;}
function luhn(s){var t=0,d=false;for(var i=s.length-1;i>=0;i--){var n=+s[i];if(d){n*=2;if(n>9)n-=9;}t+=n;d=!d;}return t%10===0;}
function buscarCep(){
  var cep=$('ent-cep').value.replace(/\D/g,''),s=$('cep-status');
  if(cep.length!==8){s.textContent='Digite um CEP com 8 dígitos.';return;}
  s.textContent='Buscando endereço...';
  fetch('https://viacep.com.br/ws/'+cep+'/json/').then(function(r){if(!r.ok)throw 0;return r.json();}).then(function(d){
    if(d.erro){s.textContent='CEP não encontrado. Preencha o endereço manualmente.';return;}
    var r=$('ent-rua');
    r.value=d.logradouro?d.logradouro+', ':'';
    $('ent-cidade').value=d.localidade||'';
    if(d.uf)$('ent-uf').value=d.uf;
    s.textContent='Endereço localizado. Informe o número.';
    r.focus();r.setSelectionRange(r.value.length,r.value.length);
    recalcular();
  }).catch(function(){s.textContent='Não foi possível buscar o CEP agora. Preencha o endereço manualmente.';});
}
