(function () {
  var live = document.getElementById('live');
  function anunciar(t) { live.textContent = ''; setTimeout(function () { live.textContent = t; }, 50); }

  /* Diálogo de exclusão: foco, Esc, retorno de foco e armadilha de Tab */
  var ultimoFoco = null;
  function abrir(id) {
    var f = document.getElementById(id);
    ultimoFoco = document.activeElement;
    f.hidden = false;
    var alvo = f.querySelector('input') || f.querySelector('.btn:not(.perigo)');
    if (alvo) alvo.focus();
  }
  function fechar(f) {
    f.hidden = true;
    var i = f.querySelector('input');
    if (i) { i.value = ''; i.dispatchEvent(new Event('input')); }
    if (ultimoFoco) ultimoFoco.focus();
  }
  document.querySelectorAll('[data-abrir="fundo-excluir"]').forEach(function (b) {
    b.addEventListener('click', function () { abrir('fundo-excluir'); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });
  document.addEventListener('keydown', function (e) {
    var f = document.querySelector('[data-modal]:not([hidden])');
    if (!f) return;
    if (e.key === 'Escape') { fechar(f); return; }
    if (e.key === 'Tab') {
      var els = f.querySelectorAll('input,button:not([disabled])');
      var p = els[0], u = els[els.length - 1];
      if (e.shiftKey && document.activeElement === p) { e.preventDefault(); u.focus(); }
      else if (!e.shiftKey && document.activeElement === u) { e.preventDefault(); p.focus(); }
    }
  });
  var conf = document.getElementById('confirma-exclusao');
  var btnEx = document.getElementById('btn-confirma-exclusao');
  conf.addEventListener('input', function () { btnEx.disabled = conf.value.trim().toUpperCase() !== 'EXCLUIR'; });

  document.getElementById('btn-dispensar').addEventListener('click', function () { document.getElementById('banner-sucesso').hidden = true; });

  /* Validação só ao enviar */
  var form = document.getElementById('form-perfil');
  var resumo = document.getElementById('resumo-erros');
  var aviso = document.getElementById('aviso-sessoes');
  var campos = [
    { id: 'email', err: 'erro-email', dica: 'dica-email' },
    { id: 'telefone', err: 'erro-telefone', dica: 'dica-telefone' }
  ];
  function limpar() {
    campos.forEach(function (c) {
      var el = document.getElementById(c.id), er = document.getElementById(c.err);
      el.closest('.campo').classList.remove('invalido', 'campo-erro');
      el.removeAttribute('aria-invalid');
      el.setAttribute('aria-describedby', c.dica + ' ' + c.err);
      er.hidden = true; er.textContent = '';
    });
    resumo.hidden = true;
    if (aviso) aviso.hidden = false;
  }
  form.addEventListener('submit', function (e) {
    limpar();
    var erros = [];
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(document.getElementById('email').value.trim())) {
      erros.push({ c: campos[0], msg: 'Informe o e-mail completo, como nome@clinica.com.br.', rot: 'E-mail corporativo' });
    }
    var d = document.getElementById('telefone').value.replace(/\D/g, '');
    if (d.length < 10 || d.length > 11) {
      erros.push({ c: campos[1], msg: 'Informe o telefone com DDD, por exemplo (11) 91234-5678.', rot: 'Telefone celular' });
    }
    if (!erros.length) return;
    e.preventDefault();
    var ul = resumo.querySelector('ul');
    ul.innerHTML = '';
    erros.forEach(function (x) {
      var el = document.getElementById(x.c.id), er = document.getElementById(x.c.err);
      el.closest('.campo').classList.add('invalido');
      el.setAttribute('aria-invalid', 'true');
      er.textContent = x.msg; er.hidden = false;
      var li = document.createElement('li'), a = document.createElement('a');
      a.href = '#' + x.c.id; a.textContent = x.rot + ': ' + x.msg;
      li.appendChild(a); ul.appendChild(li);
    });
    document.getElementById('h-resumo').textContent = erros.length === 1 ? 'Corrija 1 campo para salvar' : 'Corrija ' + erros.length + ' campos para salvar';
    document.getElementById('banner-sucesso').hidden = true;
    if (aviso) aviso.hidden = true;
    resumo.hidden = false;
    resumo.focus();
  });
  form.addEventListener('reset', limpar);

  /* Tabelas rolam na horizontal em telas estreitas */
  document.querySelectorAll('#acessos table').forEach(function (t) {
    var w = document.createElement('div');
    var c = t.querySelector('caption');
    w.className = 'tabela-rolagem'; w.tabIndex = 0; w.setAttribute('role', 'region');
    w.setAttribute('aria-label', c ? c.textContent : 'Tabela');
    t.parentNode.insertBefore(w, t); w.appendChild(t);
  });

  /* Situação: texto visível além da cor */
  document.querySelectorAll('.ponto[aria-label]').forEach(function (p) {
    var s = document.createElement('span');
    s.className = 'ponto-txt'; s.textContent = p.getAttribute('aria-label');
    p.removeAttribute('aria-label'); p.setAttribute('aria-hidden', 'true');
    p.parentNode.appendChild(s);
  });

  /* Revogar acesso: ação imediata com "Desfazer" */
  var contagem = document.getElementById('contagem-acessos');
  function atualizarContagem() {
    var n = document.querySelectorAll('#acessos tbody tr:not(.revogado) [data-abrir="fundo-revogar"]').length;
    contagem.textContent = n === 0 ? 'Nenhum aplicativo com acesso à sua conta' : n === 1 ? '1 aplicativo com acesso à sua conta' : n + ' aplicativos com acesso à sua conta';
  }
  document.querySelectorAll('[data-abrir="fundo-revogar"]').forEach(function (b) {
    var tr = b.closest('tr');
    var app = tr.querySelector('th').textContent.trim();
    b.setAttribute('aria-label', 'Revogar acesso de ' + app);
    b.addEventListener('click', function () {
      var msg = document.createElement('span'); msg.className = 'desfazer';
      msg.appendChild(document.createTextNode('Acesso revogado.'));
      var u = document.createElement('button');
      u.type = 'button'; u.className = 'btn pequeno'; u.textContent = 'Desfazer';
      u.setAttribute('aria-label', 'Desfazer revogação de ' + app);
      var t = setTimeout(function () { u.remove(); }, 10000);
      u.addEventListener('click', function () {
        clearTimeout(t); msg.remove(); tr.classList.remove('revogado');
        b.hidden = false; b.focus(); atualizarContagem();
        anunciar('Revogação desfeita: ' + app);
      });
      b.hidden = true; tr.classList.add('revogado');
      msg.appendChild(u); b.parentNode.appendChild(msg);
      u.focus(); atualizarContagem();
      anunciar('Acesso de ' + app + ' revogado. Desfazer disponível por 10 segundos.');
