(function () {
  var live = document.getElementById('live');
  function anunciar(t) { live.textContent = ''; setTimeout(function () { live.textContent = t; }, 50); }

  document.querySelectorAll('svg:not([aria-hidden])').forEach(function (s) {
    s.setAttribute('aria-hidden', 'true'); s.setAttribute('focusable', 'false');
  });

  document.querySelectorAll('.ponto[aria-label]').forEach(function (p) {
    p.setAttribute('aria-hidden', 'true');
    p.parentNode.appendChild(document.createTextNode(p.getAttribute('aria-label')));
    p.removeAttribute('aria-label');
  });

  document.querySelectorAll('table').forEach(function (t) {
    var w = document.createElement('div');
    w.className = 'tabela-rolavel'; w.tabIndex = 0;
    w.setAttribute('role', 'region');
    w.setAttribute('aria-label', t.querySelector('caption').textContent);
    t.parentNode.insertBefore(w, t); w.appendChild(t);
  });

  document.querySelectorAll('tbody tr').forEach(function (tr) {
    var b = tr.querySelector('button');
    if (!b) return;
    var nome = tr.querySelector('th').textContent.trim();
    if (b.hasAttribute('data-abrir')) {
      b.setAttribute('aria-label', 'Revogar acesso de ' + nome);
      b.setAttribute('data-nome', nome);
    } else {
      b.setAttribute('aria-label', 'Encerrar sessão em ' + nome);
    }
  });

  var ativo = null, origem = null;
  function abrir(id, gatilho) {
    var f = document.getElementById(id);
    var nome = gatilho.getAttribute('data-nome');
    if (nome) f.querySelector('h2').textContent = 'Revogar o acesso de ' + nome + '?';
    origem = gatilho; ativo = f; f.hidden = false;
    document.body.style.overflow = 'hidden';
    f.querySelector('[data-foco]').focus();
  }
  function fechar() {
    if (!ativo) return;
    ativo.hidden = true; ativo = null;
    document.body.style.overflow = '';
    if (origem && document.contains(origem)) origem.focus();
  }
  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir'), b); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) { b.addEventListener('click', fechar); });
  document.querySelectorAll('[data-modal]').forEach(function (f) {
    f.addEventListener('click', function (e) { if (e.target === f) fechar(); });
  });
  document.addEventListener('keydown', function (e) {
    if (!ativo) return;
    if (e.key === 'Escape') { fechar(); return; }
    if (e.key !== 'Tab') return;
    var els = ativo.querySelectorAll('button');
    var primeiro = els[0], ultimo = els[els.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    var h = document.getElementById('h-pref'); h.tabIndex = -1; h.focus();
  });

  var regras = {
    email: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()); },
    telefone: function (v) { var d = v.replace(/\D/g, ''); return d.length === 10 || d.length === 11; }
  };
  function validar(id) {
    var input = document.getElementById(id);
    var ok = regras[id](input.value);
    input.closest('.campo').classList.toggle('campo-erro', !ok);
    input.setAttribute('aria-invalid', ok ? 'false' : 'true');
    document.getElementById('erro-' + id).hidden = ok;
    return ok;
  }
  ['email', 'telefone'].forEach(function (id) {
    var i = document.getElementById(id);
    i.addEventListener('blur', function () { validar(id); });
    i.addEventListener('input', function () { if (i.getAttribute('aria-invalid') === 'true') validar(id); });
  });
  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    var invalidos = ['email', 'telefone'].filter(function (id) { return !validar(id); });
    if (invalidos.length) {
      e.preventDefault();
      document.getElementById(invalidos[0]).focus();
      anunciar('Corrija ' + invalidos.length + ' campo(s) antes de salvar.');
    }
  });
})();
@@ FIM

