    var bs = m.querySelectorAll('button'), a = bs[0], z = bs[bs.length - 1], d = m.querySelector('[role="dialog"]');
    if (e.shiftKey && (document.activeElement === a || document.activeElement === d)) { e.preventDefault(); z.focus(); }
