var regrasPerfil = [
  { id: 'email', ok: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()); }, msg: 'Informe um e-mail válido, como nome@escola.com.br.' },
  { id: 'telefone', ok: function (v) { var d = v.replace(/\D/g, ''); return d.length === 10 || d.length === 11; }, msg: 'Informe o telefone com DDD, por exemplo (11) 91234-5678.' }
