document.getElementById('form-perfil').addEventListener('submit', function (e) {
  var erros = [];
  regrasPerfil.forEach(function (r) {
    var campo = document.getElementById(r.id), msg = document.getElementById('erro-' + r.id), invalido = !r.ok(campo.value);
    campo.parentNode.classList.toggle('campo-erro', invalido);
    if (invalido) { campo.setAttribute('aria-invalid', 'true'); erros.push(r); } else { campo.removeAttribute('aria-invalid'); }
    msg.textContent = invalido ? r.msg : '';
