  });
  if (!erros.length) { resumoErros.hidden = true; return; }
  e.preventDefault();
  resumoErros.innerHTML = '<h2>Corrija ' + (erros.length === 1 ? '1 campo' : erros.length + ' campos') + ' para salvar</h2><ul>' +
    erros.map(function (r) { return '<li><a href="#' + r.id + '">' + r.msg + '</a></li>'; }).join('') + '</ul>';
