var linhaPendente = null, timerToast = null;
function atualizarContagem() {
  var n = 0;
  document.querySelectorAll('[data-abrir="fundo-revogar"]').forEach(function (b) { if (!b.closest('tr').hidden) n++; });
  contagemAcessos.textContent = n === 0 ? 'Nenhum aplicativo com acesso à sua conta' : n + (n === 1 ? ' aplicativo com acesso' : ' aplicativos com acesso') + ' à sua conta';
}
function encerrarToast() {
  if (toast.contains(document.activeElement)) contagemAcessos.focus();
  toast.hidden = true;
  linhaPendente = null; // aqui a revogação é confirmada no servidor
}
document.querySelectorAll('[data-abrir="fundo-revogar"]').forEach(function (b) {
