(function () {
  var live = document.getElementById('live');
  function anunciar(t) { live.textContent = ''; setTimeout(function () { live.textContent = t; }, 60); }

  document.querySelectorAll('svg:not([aria-hidden])').forEach(function (s) {
    s.setAttribute('aria-hidden', 'true'); s.setAttribute('focusable', 'false');
  });

  var contagem = document.getElementById('contagem-acessos');
  contagem.setAttribute('tabindex', '-1');
  var avisoSess = document.querySelector('#aviso-sessoes p');
  var tabApps = document.querySelector('#acessos table');
  function atualizarContagem() {
    var n = tabApps.querySelectorAll('tbody tr').length;
    contagem.textContent = n === 0 ? 'Nenhum aplicativo com acesso à sua conta'
      : n + (n === 1 ? ' aplicativo com acesso' : ' aplicativos com acesso') + ' à sua conta';
  }

  document.querySelectorAll('#acessos table').forEach(function (t) {
    var cab = [].map.call(t.querySelectorAll('thead th'), function (h) { return h.textContent; });
    t.querySelectorAll('tbody tr').forEach(function (tr) {
      [].forEach.call(tr.children, function (c, i) { c.setAttribute('data-label', cab[i]); });
      var nome = tr.querySelector('th').textContent;
      var ponto = tr.querySelector('.ponto');
      if (ponto) {
        ponto.parentNode.appendChild(document.createTextNode(ponto.getAttribute('aria-label')));
        ponto.removeAttribute('aria-label');
        ponto.setAttribute('aria-hidden', 'true');
      }
      var b = tr.querySelector('button');
      if (!b) return;
      if (b.hasAttribute('data-abrir')) {
        b.setAttribute('aria-label', 'Revogar acesso de ' + nome);
        b.setAttribute('data-app', nome);
      } else {
        b.setAttribute('aria-label', 'Encerrar sessão em ' + nome);
        b.addEventListener('click', function () {
          // TODO: chamar a API para encerrar a sessão
          var cap = t.querySelector('caption');
          tr.remove();
          var n = t.querySelectorAll('tbody tr').length;
          avisoSess.textContent = 'Sua conta está conectada em ' + n + (n === 1 ? ' dispositivo.' : ' dispositivos. Encerre as sessões que você não reconhece.');
          anunciar('Sessão em ' + nome + ' encerrada.');
          cap.setAttribute('tabindex', '-1'); cap.focus();
        });
      }
    });
  });

  var gatilho = null, aberto = null;
  function abrir(id, g) {
    aberto = document.getElementById(id); gatilho = g;
    if (g.getAttribute('data-app')) {
      document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + g.getAttribute('data-app') + '?';
    }
    aberto.hidden = false; document.body.style.overflow = 'hidden';
    (aberto.querySelector('[data-foco]') || aberto.querySelector('button')).focus();
  }
  function fechar(foco) {
    if (!aberto) return;
    aberto.hidden = true; aberto = null; document.body.style.overflow = '';
    var alvo = (gatilho && document.body.contains(gatilho)) ? gatilho : foco;
    if (alvo) alvo.focus();
  }
  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir'), b); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () {
      var acao = b.getAttribute('data-confirmar');
      if (acao === 'revogar') {
        var tr = gatilho.closest('tr'), nome = gatilho.getAttribute('data-app');
        // TODO: chamar a API para revogar o acesso
        tr.remove(); atualizarContagem();
        anunciar('Acesso de ' + nome + ' revogado.');
        fechar(contagem);
        return;
      }
      // TODO: acao === 'excluir' deve chamar a API de exclusão de conta
      fechar();
    });
  });
  document.querySelectorAll('[data-modal]').forEach(function (f) {
    f.addEventListener('click', function (e) { if (e.target === f) fechar(); });
  });
  document.addEventListener('keydown', function (e) {
    if (!aberto) return;
    if (e.key === 'Escape') { e.preventDefault(); fechar(); return; }
    if (e.key === 'Tab') {
      var f = aberto.querySelectorAll('button,[href],input,select,textarea');
      var p = f[0], u = f[f.length - 1];
      if (e.shiftKey && document.activeElement === p) { e.preventDefault(); u.focus(); }
      else if (!e.shiftKey && document.activeElement === u) { e.preventDefault(); p.focus(); }
    }
  });

  var testes = {
    email: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()); },
    telefone: function (v) { var d = v.replace(/\D/g, ''); return d.length === 10 || d.length === 11; }
  };
  function validar(id) {
    var i = document.getElementById(id), ok = testes[id](i.value);
    i.closest('.campo').classList.toggle('campo-erro', !ok);
    document.getElementById('erro-' + id).hidden = ok;
    if (ok) i.removeAttribute('aria-invalid'); else i.setAttribute('aria-invalid', 'true');
    return ok;
  }
  Object.keys(testes).forEach(function (id) {
    var i = document.getElementById(id);
    i.addEventListener('blur', function () { validar(id); });
    i.addEventListener('input', function () { if (i.getAttribute('aria-invalid')) validar(id); });
  });
  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    var invalidos = Object.keys(testes).filter(function (id) { return !validar(id); });
    if (invalidos.length) {
      e.preventDefault();
      document.getElementById(invalidos[0]).focus();
      anunciar('Corrija ' + invalidos.length + (invalidos.length === 1 ? ' campo' : ' campos') + ' para salvar.');
    }
  });

  var banner = document.getElementById('banner-sucesso');
  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault(); // TODO: enviar preferências à API
    var h = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
    var msg = 'Suas preferências de notificação foram salvas às ' + h + '.';
    document.getElementById('banner-msg').textContent = msg;
    banner.hidden = false;
    anunciar(msg);
  });
  document.getElementById('btn-dispensar').addEventListener('click', function () { banner.hidden = true; });
})();
