var baseTitulo = 'Configurações da conta - Colégio Novo Saber';
var gatilho = null;

function abrir(id, g) {
  gatilho = g;
  var m = document.getElementById(id);
  m.hidden = false;
  (m.querySelector('[data-foco]') || m.querySelector('button')).focus();
}
function fechar(m) {
  m.hidden = true;
  if (gatilho) { gatilho.focus(); gatilho = null; }
}

// Nomes acessíveis distintos para ações repetidas nas tabelas
document.querySelectorAll('[data-abrir="fundo-revogar"]').forEach(function (b) {
  var app = b.closest('tr').querySelector('th').textContent.trim();
  b.dataset.app = app;
  b.setAttribute('aria-label', 'Revogar acesso de ' + app);
});
document.querySelectorAll('td .btn.pequeno').forEach(function (b) {
  if (b.textContent.trim() === 'Encerrar sessão') {
    b.setAttribute('aria-label', 'Encerrar sessão em ' + b.closest('tr').querySelector('th').textContent.trim());
  }
});
// Situação em texto, não só por cor
document.querySelectorAll('.ponto[aria-label]').forEach(function (p) {
  var t = p.getAttribute('aria-label');
  p.removeAttribute('aria-label');
  p.setAttribute('aria-hidden', 'true');
  p.parentNode.appendChild(document.createTextNode(t));
});

document.querySelectorAll('[data-abrir]').forEach(function (b) {
  b.addEventListener('click', function () {
    if (b.dataset.app) {
      document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + b.dataset.app + '?';
    }
    abrir(b.getAttribute('data-abrir'), b);
  });
});
document.querySelectorAll('[data-fechar]').forEach(function (b) {
  b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
});
document.querySelectorAll('[data-modal]').forEach(function (m) {
  m.addEventListener('click', function (ev) { if (ev.target === m) { fechar(m); } });
});
document.addEventListener('keydown', function (ev) {
  var m = document.querySelector('[data-modal]:not([hidden])');
  if (!m) { return; }
  if (ev.key === 'Escape') { fechar(m); return; }
  if (ev.key === 'Tab') {
    var fs = m.querySelectorAll('button,input,[href]');
    var a = fs[0], z = fs[fs.length - 1];
    if (ev.shiftKey && document.activeElement === a) { ev.preventDefault(); z.focus(); }
    else if (!ev.shiftKey && document.activeElement === z) { ev.preventDefault(); a.focus(); }
  }
});

document.getElementById('btn-confirma-excluir').addEventListener('click', function () {
  var i = document.getElementById('confirma-excluir');
  var e = document.getElementById('erro-confirma');
  if (i.value.trim().toUpperCase() !== 'EXCLUIR') {
    e.hidden = false;
    i.setAttribute('aria-invalid', 'true');
    i.focus();
    return;
  }
  e.hidden = true;
  i.removeAttribute('aria-invalid');
  i.value = '';
  fechar(document.getElementById('fundo-excluir'));
  /* integrar aqui a chamada ao servidor que agenda a exclusão */
});

document.getElementById('btn-dispensar').addEventListener('click', function () { document.getElementById('banner-sucesso').hidden = true; });

// Validação ao enviar o perfil, com resumo de erros no topo
var campos = [
  { id: 'email', rot: 'E-mail corporativo', msg: 'informe o e-mail completo, com domínio. Exemplo: nome@dominio.com.br',
    ok: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()); } },
  { id: 'telefone', rot: 'Telefone celular', msg: 'informe o telefone com DDD e todos os dígitos. Exemplo: (11) 91234-5678',
    ok: function (v) { var d = v.replace(/\D/g, ''); return d.length === 10 || d.length === 11; } }
];
function validar() {
  var lista = document.getElementById('lista-erros');
  lista.textContent = '';
  var n = 0;
  campos.forEach(function (c) {
    var i = document.getElementById(c.id);
    var e = document.getElementById('erro-' + c.id);
    var ruim = !c.ok(i.value);
    var campo = i.closest('.campo');
    campo.classList.toggle('campo-erro', ruim);
    e.hidden = !ruim;
    var marca = campo.querySelector('.marca-erro');
    if (marca) { marca.hidden = !ruim; }
    if (ruim) {
      n++;
      i.setAttribute('aria-invalid', 'true');
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + c.id;
      a.textContent = c.rot + ': ' + c.msg;
      li.appendChild(a);
      lista.appendChild(li);
    } else {
      i.removeAttribute('aria-invalid');
    }
  });
  document.getElementById('resumo-erros').hidden = n === 0;
  document.getElementById('h-resumo').textContent = n === 1 ? 'Corrija 1 campo para salvar o perfil' : 'Corrija ' + n + ' campos para salvar o perfil';
  document.title = (n ? 'Erro: ' : '') + baseTitulo;
  return n;
}
document.getElementById('form-perfil').addEventListener('submit', function (ev) {
  if (validar()) {
    ev.preventDefault();
    document.getElementById('resumo-erros').focus();
  }
});
@@ FIM

