<script>
(function(){
  var f=document.querySelector('form');
  var res=document.getElementById('resumo-erros');
  var lista=document.getElementById('lista-erros');
  var tit=document.getElementById('titulo-erros');
  var mesmo=document.getElementById('mesmo');
  var cor=document.getElementById('bloco-cor');
  function v(id){return document.getElementById(id).value.trim();}
  function dig(id){return v(id).replace(/\D/g,'');}
  function cpfOk(s){
    if(s.length!==11||/^(\d)\1+$/.test(s))return false;
    for(var t=9;t<11;t++){
      var n=0;
      for(var i=0;i<t;i++)n+=s[i]*(t+1-i);
      n=(n*10)%11%10;
      if(n!=s[t])return false;
    }
    return true;
  }

  ['nome','cpf','dia','mes','ano','email','tel','cep-res','rua-res','num-res','cidade-res','uf-res','aceite'].forEach(function(id){
    document.getElementById(id).setAttribute('aria-required','true');
  });

  function alterna(){
    var m=mesmo.checked;
    cor.hidden=m;
    [].forEach.call(cor.querySelectorAll('input,select'),function(e){e.disabled=m;});
  }
  mesmo.addEventListener('change',alterna);
  alterna();

  var tabs=[].slice.call(document.querySelectorAll('[role=tab]'));
  function seleciona(t,foco){
    tabs.forEach(function(x){
      var on=x===t;
      x.setAttribute('aria-selected',on?'true':'false');
      x.tabIndex=on?0:-1;
      x.classList.toggle('aba-ativa',on);
      document.getElementById(x.getAttribute('aria-controls')).hidden=!on;
    });
    if(foco)t.focus();
  }
  tabs.forEach(function(t,i){
    t.addEventListener('click',function(){seleciona(t);});
    t.addEventListener('keydown',function(e){
      var n=null;
      if(e.key==='ArrowRight')n=tabs[(i+1)%tabs.length];
      else if(e.key==='ArrowLeft')n=tabs[(i+tabs.length-1)%tabs.length];
      else if(e.key==='Home')n=tabs[0];
      else if(e.key==='End')n=tabs[tabs.length-1];
      if(n){e.preventDefault();seleciona(n,true);}
    });
  });

  function checks(){
    var a=[],hoje=new Date().getFullYear();
    function e(id,rot,msg){a.push([id,rot,msg]);}
    if(v('nome').split(/\s+/).length<2)e('nome','Nome completo','informe nome e sobrenome.');
    if(!cpfOk(dig('cpf')))e('cpf','CPF','informe um CPF válido com 11 dígitos.');
    var dia=+v('dia'),mes=+v('mes'),ano=+v('ano'),n=a.length;
    if(!/^\d{1,2}$/.test(v('dia'))||dia<1||dia>31)e('dia','Dia de nascimento','informe um dia entre 1 e 31.');
    if(!/^\d{1,2}$/.test(v('mes'))||mes<1||mes>12)e('mes','Mês de nascimento','informe um mês entre 1 e 12.');
    if(!/^\d{4}$/.test(v('ano'))||ano<1900||ano>hoje)e('ano','Ano de nascimento','informe o ano com 4 dígitos.');
    if(a.length===n){
      var dt=new Date(ano,mes-1,dia);
      if(dt.getDate()!==dia||dt.getMonth()!==mes-1)e('dia','Data de nascimento','essa data não existe.');
    }
    if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v('email')))e('email','E-mail','informe um e-mail válido, como nome@exemplo.com.br.');
    if(!/^\d{10,11}$/.test(dig('tel')))e('tel','Telefone','informe o DDD e o número, com 10 ou 11 dígitos.');
    if(dig('cep-res').length!==8)e('cep-res','CEP residencial','informe o CEP com 8 dígitos.');
    if(!v('rua-res'))e('rua-res','Rua residencial','informe a rua.');
    if(!v('num-res'))e('num-res','Número residencial','informe o número.');
    if(!v('cidade-res'))e('cidade-res','Cidade residencial','informe a cidade.');
    if(!v('uf-res'))e('uf-res','UF residencial','selecione a UF.');
    if(!mesmo.checked){
      if(dig('cep-cor').length!==8)e('cep-cor','CEP de correspondência','informe o CEP com 8 dígitos.');
      if(!v('rua-cor'))e('rua-cor','Rua de correspondência','informe a rua.');
      if(!v('num-cor'))e('num-cor','Número de correspondência','informe o número.');
      if(!v('cidade-cor'))e('cidade-cor','Cidade de correspondência','informe a cidade.');
      if(!v('uf-cor'))e('uf-cor','UF de correspondência','selecione a UF.');
    }
    if(!document.getElementById('aceite').checked)e('aceite','Termos de uso','aceite os termos para continuar.');
    return a;
  }

  function limpa(){
    [].forEach.call(f.querySelectorAll('.erro'),function(p){p.remove();});
    [].forEach.call(f.querySelectorAll('.tem-erro'),function(c){c.classList.remove('tem-erro');});
    [].forEach.call(f.querySelectorAll('[aria-invalid]'),function(i){i.removeAttribute('aria-invalid');});
    [].forEach.call(f.querySelectorAll('[aria-describedby]'),function(i){
      var b=i.getAttribute('aria-describedby').split(' ').filter(function(x){return x&&x.indexOf('e-')!==0;}).join(' ');
      if(b)i.setAttribute('aria-describedby',b);else i.removeAttribute('aria-describedby');
    });
  }

  function mostra(id,msg){
    var i=document.getElementById(id),c=i.closest('.campo'),p=document.createElement('p');
    p.className='erro';
    p.id='e-'+id;
    p.textContent='Erro: '+msg.charAt(0).toUpperCase()+msg.slice(1);
    if(c)c.classList.add('tem-erro');else c=i.closest('section');
    c.appendChild(p);
    i.setAttribute('aria-invalid','true');
    var b=(i.getAttribute('aria-describedby')||'').split(' ').filter(Boolean);
    b.push(p.id);
    i.setAttribute('aria-describedby',b.join(' '));
  }

  f.addEventListener('submit',function(ev){
    limpa();
    var a=checks();
    if(!a.length){res.hidden=true;return;}
    ev.preventDefault();
    lista.innerHTML='';
    a.forEach(function(x){
      mostra(x[0],x[2]);
      var li=document.createElement('li'),l=document.createElement('a');
      l.href='#'+x[0];
      l.textContent=x[1]+': '+x[2];
      li.appendChild(l);
      lista.appendChild(li);
    });
    tit.textContent=a.length===1?'Há 1 problema nesta etapa':'Há '+a.length+' problemas nesta etapa';
    res.hidden=false;
    res.focus();
  });

  lista.addEventListener('click',function(e){
    var l=e.target.closest('a');
    if(!l)return;
    e.preventDefault();
    var t=document.getElementById(l.getAttribute('href').slice(1));
    t.focus();
    t.scrollIntoView({block:'center'});
  });
})();
</script>
