(function () {
  var live = document.getElementById('live');
  var resumo = document.getElementById('resumo-erros');
  var lista = document.getElementById('resumo-lista');
  var banner = document.getElementById('banner-sucesso');
  var statusPerfil = document.getElementById('status-perfil');
  var gatilho = null, aberto = null;

  function hora() { return new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }); }

  // ícones decorativos fora da árvore de acessibilidade
  document.querySelectorAll('svg.ico:not([aria-hidden])').forEach(function (s) {
    s.setAttribute('aria-hidden', 'true'); s.setAttribute('focusable', 'false');
  });
  // botões repetidos nas tabelas ganham nome único (ação + item)
  document.querySelectorAll('tbody .btn').forEach(function (b) {
    var th = b.closest('tr').querySelector('th');
    if (th) b.setAttribute('aria-label', b.textContent.trim() + ': ' + th.textContent.trim());
  });

  // ---- Modais ----
  function abrir(id, b) {
    var f = document.getElementById(id);
    if (id === 'fundo-revogar') {
      document.getElementById('rev-app').textContent = b.closest('tr').querySelector('th').textContent.trim();
    }
    gatilho = b; aberto = f; f.hidden = false;
    (f.querySelector('[data-foco-inicial]') || f.querySelector('button')).focus();
  }
  function fechar() {
    if (!aberto) return;
    aberto.hidden = true; aberto = null;
    if (gatilho) gatilho.focus();
  }
  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir'), b); });
  });
  // TODO: ligar a confirmação (Excluir conta / Revogar acesso) ao backend antes de fechar
  document.querySelectorAll('[data-fechar]').forEach(function (b) { b.addEventListener('click', fechar); });
  document.querySelectorAll('[data-modal]').forEach(function (m) {
    m.addEventListener('click', function (e) { if (e.target === m) fechar(); });
  });
  document.addEventListener('keydown', function (e) {
    if (!aberto) return;
    if (e.key === 'Escape') { fechar(); return; }
    if (e.key === 'Tab') {
      var bs = aberto.querySelectorAll('button');
      var p = bs[0], u = bs[bs.length - 1];
      if (e.shiftKey && document.activeElement === p) { e.preventDefault(); u.focus(); }
      else if (!e.shiftKey && document.activeElement === u) { e.preventDefault(); p.focus(); }
    }
  });

  // ---- Validação do perfil: só ao salvar ----
  var form = document.getElementById('form-perfil');
  var regras = [
    { id: 'nome', msg: 'Informe seu nome.', ok: function (v) { return v.trim() !== ''; } },
    { id: 'email', msg: 'Informe um e-mail válido, como nome@empresa.com.br.', ok: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()); } },
    { id: 'telefone', msg: 'Informe o telefone com DDD, por exemplo (11) 91234-5678.', ok: function (v) { var d = v.replace(/\D/g, ''); return v.trim() === '' || d.length === 10 || d.length === 11; } }
  ];
  function marcar(input, texto) {
    var campo = input.closest('.campo');
    var p = document.getElementById('erro-' + input.id);
    if (!p) { p = document.createElement('p'); p.className = 'erro'; p.id = 'erro-' + input.id; campo.appendChild(p); }
    var ids = (input.getAttribute('aria-describedby') || '').split(' ').filter(Boolean);
    if (texto) {
      p.textContent = texto; p.hidden = false;
      campo.classList.add('campo-erro'); input.setAttribute('aria-invalid', 'true');
      if (ids.indexOf(p.id) < 0) { ids.push(p.id); input.setAttribute('aria-describedby', ids.join(' ')); }
    } else {
      p.textContent = ''; p.hidden = true;
      campo.classList.remove('campo-erro'); input.removeAttribute('aria-invalid');
    }
  }
  form.addEventListener('submit', function (e) {
    e.preventDefault();
    statusPerfil.textContent = '';
    lista.innerHTML = '';
    var erros = [];
    regras.forEach(function (r) {
      var i = document.getElementById(r.id);
      var ok = r.ok(i.value);
      marcar(i, ok ? '' : r.msg);
      if (!ok) erros.push(r);
    });
    if (erros.length) {
      erros.forEach(function (r) {
        var li = document.createElement('li'), a = document.createElement('a');
        a.href = '#' + r.id; a.textContent = r.msg;
        a.addEventListener('click', function (ev) { ev.preventDefault(); document.getElementById(r.id).focus(); });
        li.appendChild(a); lista.appendChild(li);
      });
      banner.hidden = true;
      resumo.hidden = false; resumo.focus();
      return;
    }
    resumo.hidden = true;
    // TODO: enviar ao backend e só então confirmar
    statusPerfil.textContent = 'Alterações salvas às ' + hora() + '.';
  });
  form.addEventListener('reset', function () {
    setTimeout(function () {
      regras.forEach(function (r) { marcar(document.getElementById(r.id), ''); });
      resumo.hidden = true; statusPerfil.textContent = '';
    }, 0);
  });

  // ---- Preferências ----
  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    // TODO: enviar ao backend e só então confirmar
    var t = 'Suas preferências de notificação foram salvas às ' + hora() + '.';
    if (resumo.hidden) { document.getElementById('txt-sucesso').textContent = t; banner.hidden = false; }
    live.textContent = '';
    setTimeout(function () { live.textContent = t; }, 50);
  });
  document.getElementById('btn-dispensar').addEventListener('click', function () { banner.hidden = true; });
})();
@@ FIM

