<script>
(function(){
  var gaveta=document.getElementById('gaveta');
  var btnAjuda=document.querySelector('[aria-controls="gaveta"]');
  var origem=null;
  function setGaveta(abrir){
    gaveta.classList.toggle('aberta',abrir);
    btnAjuda.setAttribute('aria-expanded',abrir?'true':'false');
  }
  function abrirModal(m,el){
    origem=el;
    m.hidden=false;
    (m.querySelector('input,button:not(.modal-x)')||m).focus();
  }
  function fecharModal(m){
    m.hidden=true;
    if(origem){origem.focus();}
  }
  btnAjuda.addEventListener('click',function(){
    setGaveta(!gaveta.classList.contains('aberta'));
  });
  document.querySelectorAll('[data-abre]').forEach(function(el){
    el.addEventListener('click',function(e){
      e.preventDefault();
      abrirModal(document.getElementById(el.getAttribute('data-abre')),el);
    });
  });
  document.querySelectorAll('[data-fecha]').forEach(function(el){
    el.addEventListener('click',function(){fecharModal(el.closest('.modal'));});
  });
  document.querySelectorAll('[data-dispensar]').forEach(function(el){
    el.addEventListener('click',function(){
      el.closest('.banner').remove();
      document.getElementById('conteudo').focus();
    });
  });
  document.addEventListener('keydown',function(e){
    var m=document.querySelector('.modal:not([hidden])');
    if(e.key==='Escape'){
      if(m){fecharModal(m);}
      else if(gaveta.classList.contains('aberta')){setGaveta(false);btnAjuda.focus();}
      return;
    }
    if(e.key==='Tab'&&m){
      var f=m.querySelectorAll('a[href],button,input,select,textarea');
      if(!f.length){return;}
      var a=f[0],z=f[f.length-1];
      if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus();}
      else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus();}
    }
  });
})();
</script>
</body>
