<script>
(function(){
  var resumo=document.getElementById('resumo-erros');
  if(resumo){resumo.focus();}

  var abas=Array.prototype.slice.call(document.querySelectorAll('[role=tab]'));
  function ativar(aba,foco){
    abas.forEach(function(a){
      var sel=a===aba;
      a.setAttribute('aria-selected',sel);
      a.tabIndex=sel?0:-1;
      a.classList.toggle('aba-ativa',sel);
      document.getElementById(a.getAttribute('aria-controls')).hidden=!sel;
    });
    if(foco){aba.focus();}
  }
  abas.forEach(function(aba,i){
    aba.addEventListener('click',function(){ativar(aba,false);});
    aba.addEventListener('keydown',function(e){
      var n=null;
      if(e.key==='ArrowRight'){n=abas[(i+1)%abas.length];}
      else if(e.key==='ArrowLeft'){n=abas[(i-1+abas.length)%abas.length];}
      else if(e.key==='Home'){n=abas[0];}
      else if(e.key==='End'){n=abas[abas.length-1];}
      if(n){e.preventDefault();ativar(n,true);}
    });
  });

  var mesmo=document.getElementById('mesmo');
  var endCor=document.getElementById('end-cor');
  if(mesmo&&endCor){
    mesmo.addEventListener('change',function(){endCor.disabled=mesmo.checked;});
  }
})();
</script>
