function alternarCobranca(c){
  var b=document.getElementById('bloco-cobranca');
  if(b){
    b.hidden=c.checked;
    b.querySelectorAll('input,select').forEach(function(el){el.disabled=c.checked;});
  }
}
(function(){
  var ufs=['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'];
  ['ent-uf','cob-uf'].forEach(function(id){
    var s=document.getElementById(id);if(!s){return;}
    var atual=s.value;s.innerHTML='';
    ufs.forEach(function(u){var o=document.createElement('option');o.value=u;o.textContent=u;s.appendChild(o);});
    s.value=atual;
  });
  var c=document.querySelector('[name=cobranca_igual]');
