@@ DEPOIS
function buscarCep(){
  var campo=document.getElementById('ent-cep'),s=document.getElementById('cep-status');
  var cep=campo.value.replace(/\D/g,'');
  if(cep.length!==8){
    s.className='erro-campo';s.textContent='CEP inválido. Digite os 8 números.';
    campo.setAttribute('aria-invalid','true');campo.focus();return;
  }
  campo.removeAttribute('aria-invalid');s.className='';s.textContent='Buscando endereço...';
  fetch('https://viacep.com.br/ws/'+cep+'/json/').then(function(r){
    if(!r.ok){throw new Error();}return r.json();
  }).then(function(d){
    if(d.erro){throw new Error();}
    document.getElementById('ent-cidade').value=d.localidade||'';
    document.getElementById('ent-uf').value=d.uf||'';
    if(d.logradouro){
      var rua=document.getElementById('ent-rua');
      rua.value=d.logradouro+', ';
      s.textContent='Endereço localizado. Informe o número.';
      rua.focus();
    }else{s.textContent='Endereço localizado. Complete o logradouro.';}
  }).catch(function(){
    s.className='erro-campo';s.textContent='Não foi possível localizar o CEP. Preencha o endereço manualmente.';
  });
}
@@ FIM

