function abrirDialogo(n){var v=document.getElementById('veu');var p=document.getElementById('dlg-p');if(p){p.textContent=n+' será removido do pedido.';}if(v){v.hidden=false;}}
@@ DEPOIS
var gatilho=null,linhaAlvo=null;
function travarFundo(t){['header','main','footer'].forEach(function(s){document.querySelector(s).inert=t;});}
function abrirDialogo(n){
  gatilho=document.activeElement;
  linhaAlvo=gatilho.closest('tr');
  document.getElementById('dlg-p').textContent=n+' será removido do pedido.';
  document.getElementById('veu').hidden=false;
  travarFundo(true);
  document.querySelector('#veu .btn-sec').focus();
}
function confirmarRemocao(){
  if(linhaAlvo){
    var prox=linhaAlvo.nextElementSibling||linhaAlvo.previousElementSibling;
    gatilho=prox?prox.querySelector('button'):null;
    linhaAlvo.remove();linhaAlvo=null;
    recalcular();
  }
  fecharDialogo();
}
var BRL=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});
function cents(t){return Math.round(parseFloat(t.replace(/[^\d,]/g,'').replace(',','.'))*100);}
function fmt(c){return BRL.format(c/100);}
function recalcular(){
  var linhas=document.querySelectorAll('#itens tbody tr'),sub=0,un=0;
  linhas.forEach(function(r){
    var c=r.querySelectorAll('.col-num');
    un+=parseInt(c[0].textContent,10);sub+=cents(c[2].textContent);
  });
  var dd=document.querySelectorAll('dl.resumo dd'),dt=document.querySelectorAll('dl.resumo dt');
  var frete=cents(dd[1].textContent),desc=Math.round(sub*0.05),total=sub+frete-desc;
  dt[0].textContent='Subtotal ('+un+' un.)';
  dd[0].textContent=fmt(sub);dd[2].textContent='- '+fmt(desc);dd[3].textContent=fmt(total);
  document.querySelector('#itens caption').textContent=linhas.length+' produtos, '+un+' unidades';
  document.querySelector('#itens tfoot td.col-num').textContent=fmt(sub);
  var pagar=document.querySelector('.btn-pagar');
  pagar.textContent='Pagar '+fmt(total);
  pagar.disabled=!linhas.length;
  document.querySelectorAll('dl.revisao div')[3].children[1].textContent=un+' unidades em '+linhas.length+' produtos';
  var p=document.getElementById('parcelas'),sel=p.value;
  p.innerHTML='';
  for(var n=1;n<=10;n++){
    var o=document.createElement('option');
    o.value=n;o.textContent=n+'x de '+fmt(Math.round(total/n))+(n===1?' sem juros':'');
    p.appendChild(o);
  }
  p.value=sel;
}
@@ FIM

