function fecharDialogo(){var v=document.getElementById('veu');if(v){v.hidden=true;}}
@@ DEPOIS
function fecharDialogo(){
  document.getElementById('veu').hidden=true;
  travarFundo(false);
  if(gatilho&&document.contains(gatilho)){gatilho.focus();}
  else{var h=document.getElementById('t-itens');h.tabIndex=-1;h.focus();}
}
@@ FIM

@@ ANTES
function alternarCobranca(c){var b=document.getElementById('bloco-cobrança');if(b){b.hidden=c.checked;}}
@@ DEPOIS
function alternarCobranca(c){
  var b=document.getElementById('bloco-cobranca');
  b.hidden=c.checked;
  b.querySelectorAll('input,select').forEach(function(el){el.disabled=c.checked;});
}
function alternarMetodo(){
  var cartao=document.querySelector('[name=metodo]:checked').value==='cartao';
  [document.getElementById('cartao'),document.getElementById('otp').closest('.bloco')].forEach(function(b){
    b.hidden=!cartao;
    b.querySelectorAll('input,select').forEach(function(el){el.disabled=!cartao;});
  });
}
(function(){
  var UFS='AC AL AP AM BA CE DF ES GO MA MT MS MG PA PB PR PE PI RJ RN RS RO RR SC SP SE TO'.split(' ');
  ['ent-uf','cob-uf'].forEach(function(id){
    var s=document.getElementById(id),v=s.value;
    s.innerHTML=UFS.map(function(u){return '<option value="'+u+'">'+u+'</option>';}).join('');
    s.value=v;
  });
  document.querySelectorAll('.col-acao button').forEach(function(b){
    b.setAttribute('aria-label','Remover '+b.closest('tr').querySelector('.col-nome').textContent);
  });
  document.querySelectorAll('#ent-cep,#cob-cep').forEach(function(i){
    i.addEventListener('input',function(){
      var d=i.value.replace(/\D/g,'').slice(0,8);
      i.value=d.length>5?d.slice(0,5)+'-'+d.slice(5):d;
    });
  });
  document.querySelectorAll('[name=metodo]').forEach(function(r){r.addEventListener('change',alternarMetodo);});
  var veu=document.getElementById('veu');
  veu.addEventListener('click',function(e){if(e.target===veu){fecharDialogo();}});
  document.addEventListener('keydown',function(e){if(e.key==='Escape'&&!veu.hidden){fecharDialogo();}});
  var form=document.getElementById('form-checkout');
  form.addEventListener('input',function(e){
    var m=document.getElementById(e.target.id+'-erro');
    if(m){m.remove();e.target.removeAttribute('aria-invalid');}
  });
  form.addEventListener('submit',function(e){
    var primeiro=null;
    Array.prototype.forEach.call(form.elements,function(el){
      if(!el.willValidate||!el.id||el.type==='submit'||el.type==='button'){return;}
      var id=el.id+'-erro',m=document.getElementById(id);
      if(el.checkValidity()){el.removeAttribute('aria-invalid');if(m){m.remove();}return;}
      if(!m){
        m=document.createElement('p');m.id=id;m.className='erro-campo';
        el.closest('.campo').appendChild(m);
      }
      m.textContent=el.validity.valueMissing?'Preencha este campo.':
        (el.validity.typeMismatch?'Informe um e-mail válido.':(el.title||'Verifique o valor informado.'));
      el.setAttribute('aria-invalid','true');
      var d=(el.getAttribute('aria-describedby')||'').split(' ').filter(Boolean);
      if(d.indexOf(id)<0){d.push(id);}
      el.setAttribute('aria-describedby',d.join(' '));
      if(!primeiro){primeiro=el;}
    });
    if(primeiro){e.preventDefault();primeiro.focus();}
  });
  alternarCobranca(document.querySelector('[name=cobranca_igual]'));
  alternarMetodo();
  contagemReenvio('Código enviado.');
})();
@@ FIM

