(function () {
  var fundoAtual = null, gatilho = null;
  var fora = ['.topo', '.layout', '.rodape'].map(function (s) { return document.querySelector(s); });

  function focaveis(el) {
    return Array.prototype.filter.call(
      el.querySelectorAll('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])'),
      function (e) { return !e.disabled; }
    );
  }
  function abrir(id, btn) {
    fundoAtual = document.getElementById(id);
    gatilho = btn;
    fundoAtual.hidden = false;
    fora.forEach(function (e) { e.inert = true; });
    document.body.style.overflow = 'hidden';
    (fundoAtual.querySelector('[data-foco]') || fundoAtual.querySelector('.modal')).focus();
  }
  function fechar() {
    if (!fundoAtual) return;
    fundoAtual.hidden = true;
    fundoAtual = null;
    fora.forEach(function (e) { e.inert = false; });
    document.body.style.overflow = '';
    if (gatilho && document.contains(gatilho)) gatilho.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var id = b.getAttribute('data-abrir');
      if (id === 'fundo-revogar') {
        var app = b.closest('tr').querySelector('th').textContent.trim();
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + app + '?';
      }
      abrir(id, b);
    });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) { b.addEventListener('click', fechar); });
  document.querySelectorAll('[data-modal]').forEach(function (f) {
    f.addEventListener('click', function (e) { if (e.target === f) fechar(); });
  });
  document.addEventListener('keydown', function (e) {
    if (!fundoAtual) return;
    if (e.key === 'Escape') { e.preventDefault(); fechar(); return; }
    if (e.key === 'Tab') {
      var itens = focaveis(fundoAtual);
      if (!itens.length) return;
      var primeiro = itens[0], ultimo = itens[itens.length - 1];
      if (e.shiftKey && (document.activeElement === primeiro || document.activeElement === fundoAtual.querySelector('.modal'))) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    var h = document.getElementById('h-pref');
    h.setAttribute('tabindex', '-1');
    h.focus();
  });
})();
@@ FIM

