<script>
(function(){
  var fundo=document.querySelectorAll('.pular,.topo,.layout,.rodape,.gaveta');
  var aberto=null,retorno=null;
  var gaveta=document.getElementById('gaveta');
  var bAjuda=document.querySelector('[aria-controls="gaveta"]');

  function abrir(m,origem){
    retorno=origem;aberto=m;m.hidden=false;
    fundo.forEach(function(e){e.inert=true;});
    var f=m.querySelector('input,.modal-acoes button');
    if(f)f.focus();
  }
  function fechar(){
    if(!aberto)return;
    aberto.hidden=true;aberto=null;
    fundo.forEach(function(e){e.inert=false;});
    if(retorno)retorno.focus();
  }
  function alternarGaveta(mostrar){
    gaveta.hidden=!mostrar;
    bAjuda.setAttribute('aria-expanded',String(mostrar));
    if(mostrar){gaveta.querySelector('a').focus();}else{bAjuda.focus();}
  }

  document.querySelectorAll('[aria-haspopup="dialog"]').forEach(function(b){
    b.addEventListener('click',function(){abrir(document.getElementById(b.getAttribute('aria-controls')),b);});
  });
  document.querySelectorAll('.modal').forEach(function(m){
    m.addEventListener('click',function(e){
      if(e.target===m||e.target.closest('.modal-x,[data-fechar],.modal-acoes .btn:not(.btn-prim):not(.btn-perigo)'))fechar();
    });
  });
  bAjuda.addEventListener('click',function(){alternarGaveta(gaveta.hidden);});
  gaveta.querySelector('[data-fechar-gaveta]').addEventListener('click',function(){alternarGaveta(false);});
  document.addEventListener('keydown',function(e){
    if(e.key!=='Escape')return;
    if(aberto)fechar();
    else if(!gaveta.hidden)alternarGaveta(false);
  });
  var banner=document.querySelector('.banner');
  if(banner){
    banner.querySelector('.btn-txt').addEventListener('click',function(){
      banner.remove();
      document.getElementById('conteudo').focus();
    });
  }
})();
</script>
</body>
