<script>
(() => {
  const gb = document.querySelector('[aria-controls="gaveta"]');
  const g = document.getElementById('gaveta');
  const setGaveta = (a) => { g.classList.toggle('aberta', a); gb.setAttribute('aria-expanded', String(a)); };
  gb.addEventListener('click', () => setGaveta(!g.classList.contains('aberta')));

  document.querySelectorAll('.banner .btn-txt').forEach((b) =>
    b.addEventListener('click', () => b.closest('.banner').remove()));

  const foco = 'a[href],button:not([disabled]),input:not([disabled]),select,textarea,[tabindex]:not([tabindex="-1"])';
  let abertoPor = null;
  const fechar = (m) => {
    m.hidden = true;
    if (abertoPor) { abertoPor.focus(); abertoPor = null; }
  };
  const abrir = (m, origem) => {
    abertoPor = origem;
    m.hidden = false;
    (m.querySelector('input,.btn-prim,.btn-perigo') || m.querySelector(foco)).focus();
  };
  document.querySelectorAll('[aria-controls^="m"]').forEach((b) =>
    b.addEventListener('click', () => abrir(document.getElementById(b.getAttribute('aria-controls')), b)));

  document.querySelectorAll('.modal').forEach((m) => {
    m.querySelectorAll('.modal-x,.modal-acoes .btn:not(.btn-prim):not(.btn-perigo)')
      .forEach((b) => b.addEventListener('click', () => fechar(m)));
    m.addEventListener('click', (e) => { if (e.target === m) fechar(m); });
    m.addEventListener('keydown', (e) => {
      if (e.key !== 'Tab') return;
      const f = [...m.querySelectorAll(foco)].filter((x) => x.offsetParent !== null);
      const p = f[0], u = f[f.length - 1];
      if (e.shiftKey && document.activeElement === p) { e.preventDefault(); u.focus(); }
      else if (!e.shiftKey && document.activeElement === u) { e.preventDefault(); p.focus(); }
    });
  });

  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    const m = document.querySelector('.modal:not([hidden])');
    if (m) fechar(m);
    else if (g.classList.contains('aberta')) { setGaveta(false); gb.focus(); }
  });

  const email = document.getElementById('conv-email');
  const erro = document.getElementById('conv-erro');
  email.addEventListener('invalid', () => { erro.hidden = false; email.setAttribute('aria-invalid', 'true'); });
  email.addEventListener('input', () => {
