<script>
(function () {
  var ultimo = null;
  var gaveta = document.getElementById('gaveta');
  var bAjuda = document.querySelector('[aria-controls="gaveta"]');
  var email = document.getElementById('conv-email');
  var erro = document.getElementById('conv-erro');

  function focaveis(c) {
    return c.querySelectorAll('a[href],button:not([disabled]),input:not([disabled])');
  }
  function abrir(m, gatilho) {
    ultimo = gatilho || document.activeElement;
    m.hidden = false;
    document.body.style.overflow = 'hidden';
    var alvo = m.querySelector('input,.modal-acoes .btn');
    if (alvo) alvo.focus();
  }
  function fechar(m) {
    m.hidden = true;
    document.body.style.overflow = '';
    if (ultimo && document.contains(ultimo)) ultimo.focus();
  }
  function alternarGaveta(abrirIt) {
    gaveta.hidden = !abrirIt;
    bAjuda.setAttribute('aria-expanded', String(abrirIt));
    if (abrirIt) gaveta.querySelector('a').focus(); else bAjuda.focus();
  }

  bAjuda.addEventListener('click', function () { alternarGaveta(gaveta.hidden); });
  gaveta.querySelector('.gaveta-fechar').addEventListener('click', function () { alternarGaveta(false); });

  document.addEventListener('click', function (e) {
    var g = e.target.closest('[data-abrir]');
    if (g) {
      var m = document.getElementById(g.getAttribute('data-abrir'));
      if (m) { e.preventDefault(); abrir(m, g); }
      return;
    }
    var f = e.target.closest('.modal-x,.modal-acoes button[type="button"]');
    if (f) { fechar(f.closest('.modal')); return; }
    var d = e.target.closest('.banner .btn-txt');
    if (d) d.closest('.banner').hidden = true;
  });

  document.addEventListener('keydown', function (e) {
    var m = document.querySelector('.modal:not([hidden])');
    if (e.key === 'Escape') {
      if (m) fechar(m);
      else if (!gaveta.hidden) alternarGaveta(false);
      return;
    }
    if (e.key === 'Tab' && m) {
      var f = focaveis(m);
      if (!f.length) return;
      var a = f[0], z = f[f.length - 1];
      if (e.shiftKey && document.activeElement === a) { e.preventDefault(); z.focus(); }
      else if (!e.shiftKey && document.activeElement === z) { e.preventDefault(); a.focus(); }
    }
  });

  email.addEventListener('invalid', function (e) {
    e.preventDefault();
    email.setAttribute('aria-invalid', 'true');
    email.setAttribute('aria-describedby', 'conv-erro');
    erro.hidden = false;
    email.focus();
  });
  email.addEventListener('input', function () {
    if (email.validity.valid) {
      email.removeAttribute('aria-invalid');
      email.removeAttribute('aria-describedby');
      erro.hidden = true;
    }
  });
})();
</script>
</body>
