(function () {
  var fundo = null, gatilho = null;
  var fora = document.querySelectorAll('.pular,.topo,.layout,.rodape');

  function focaveis(m) {
    return m.querySelectorAll('a[href],button:not([disabled]),input,select,textarea');
  }
  function abrir(id, origem) {
    fundo = document.getElementById(id);
    gatilho = origem;
    if (id === 'fundo-revogar') {
      var app = origem.closest('tr').querySelector('th').textContent.trim();
      document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + app + '?';
      document.getElementById('dlg-revogar-d').textContent = app + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
    }
    fundo.hidden = false;
    fora.forEach(function (e) { e.inert = true; });
    (fundo.querySelector('[data-foco]') || focaveis(fundo)[0]).focus();
  }
  function fechar() {
    if (!fundo) return;
    var c = document.getElementById('confirma-exclusao');
    c.value = '';
    c.removeAttribute('aria-invalid');
    document.getElementById('erro-confirma').hidden = true;
    fundo.hidden = true;
    fora.forEach(function (e) { e.inert = false; });
    if (gatilho) gatilho.focus();
    fundo = null;
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir'), b); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) { b.addEventListener('click', fechar); });
  document.querySelectorAll('[data-confirmar]').forEach(function (b) {
    b.addEventListener('click', function () {
      if (fundo.id === 'fundo-excluir') {
        var c = document.getElementById('confirma-exclusao');
        if (c.value.trim().toUpperCase() !== 'EXCLUIR') {
          c.setAttribute('aria-invalid', 'true');
          document.getElementById('erro-confirma').hidden = false;
          c.focus();
          return;
        }
      }
      fechar();
    });
  });
  document.addEventListener('keydown', function (ev) {
    if (!fundo) return;
    if (ev.key === 'Escape') { fechar(); return; }
    if (ev.key !== 'Tab') return;
    var f = focaveis(fundo), primeiro = f[0], ultimo = f[f.length - 1];
    if (ev.shiftKey && document.activeElement === primeiro) { ev.preventDefault(); ultimo.focus(); }
    else if (!ev.shiftKey && document.activeElement === ultimo) { ev.preventDefault(); primeiro.focus(); }
  });

  document.querySelectorAll('td .btn').forEach(function (b) {
    var th = b.closest('tr').querySelector('th');
    if (th) b.setAttribute('aria-label', b.textContent.trim() + ': ' + th.textContent.trim());
  });

  document.querySelectorAll('.ponto[aria-label]').forEach(function (p) {
    var t = p.getAttribute('aria-label');
    p.removeAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    p.insertAdjacentText('afterend', t);
  });

  ['email', 'telefone'].forEach(function (id) {
    var c = document.getElementById(id);
    c.addEventListener('input', function () {
      if (!c.checkValidity()) return;
      c.removeAttribute('aria-invalid');
      c.closest('.campo').classList.remove('campo-erro');
      document.getElementById('erro-' + id).hidden = true;
      document.getElementById('res-' + id).hidden = true;
      if (!document.querySelector('#resumo-erros li:not([hidden])')) {
        document.getElementById('resumo-erros').hidden = true;
        document.title = document.title.replace(/^Erro: /, '');
      }
    });
  });
})();
