<script>
(function(){
  var abas=[].slice.call(document.querySelectorAll('[role=tab]'));
  function ativar(a,foco){
    abas.forEach(function(t){
      var on=t===a;
      t.setAttribute('aria-selected',on);
      t.tabIndex=on?0:-1;
      t.classList.toggle('aba-ativa',on);
      document.getElementById(t.getAttribute('aria-controls')).hidden=!on;
    });
    if(foco)a.focus();
  }
  abas.forEach(function(t,i){
    t.addEventListener('click',function(){ativar(t,false)});
    t.addEventListener('keydown',function(e){
      var n=null;
      if(e.key==='ArrowRight')n=abas[(i+1)%abas.length];
      else if(e.key==='ArrowLeft')n=abas[(i-1+abas.length)%abas.length];
      else if(e.key==='Home')n=abas[0];
      else if(e.key==='End')n=abas[abas.length-1];
      if(n){e.preventDefault();ativar(n,true)}
    });
  });
  var m=document.getElementById('mesmo'),c=document.getElementById('end-cor');
  m.addEventListener('change',function(){c.disabled=m.checked});
})();
</script>
