document.querySelectorAll('[data-abrir]').forEach(function (b) { b.addEventListener('click', function () { document.getElementById(b.getAttribute('data-abrir')).hidden = false; }); });
document.querySelectorAll('[data-fechar]').forEach(function (b) { b.addEventListener('click', function () { b.closest('[data-modal]').hidden = true; }); });
@@ DEPOIS
var ultimoFoco = null;
function fecharModal(fundo) {
  fundo.hidden = true;
  if (ultimoFoco) { ultimoFoco.focus(); }
}
document.querySelectorAll('[data-abrir]').forEach(function (b) {
  b.addEventListener('click', function () {
    var fundo = document.getElementById(b.getAttribute('data-abrir'));
    var app = b.getAttribute('data-app');
    if (app) { document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + app + '?'; }
    ultimoFoco = b;
    fundo.hidden = false;
    fundo.querySelector('[data-inicial]').focus();
  });
});
document.querySelectorAll('[data-fechar]').forEach(function (b) {
  b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
});
document.addEventListener('keydown', function (e) {
  var aberto = document.querySelector('[data-modal]:not([hidden])');
  if (!aberto) { return; }
  if (e.key === 'Escape') { fecharModal(aberto); return; }
  if (e.key === 'Tab') {
    var itens = aberto.querySelectorAll('button');
    var primeiro = itens[0], ultimo = itens[itens.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  }
});
@@ FIM

