<script>
(function(){
  var gaveta=document.getElementById('gaveta');
  var btnAjuda=document.querySelector('[aria-controls="gaveta"]');
  var ultimoFoco=null;
  var SEL_CANCELAR='.modal-acoes .btn:not(.btn-prim):not(.btn-perigo)';

  function gavetaAberta(){return gaveta.classList.contains('aberta');}
  function alternarGaveta(abrir){
    gaveta.classList.toggle('aberta',abrir);
    btnAjuda.setAttribute('aria-expanded',String(abrir));
    (abrir?gaveta.querySelector('button,a[href]'):btnAjuda).focus();
  }
  function abrirModal(m){
    ultimoFoco=document.activeElement;
    m.hidden=false;
    document.body.style.overflow='hidden';
    var alvo=m.querySelector('.btn-perigo')?m.querySelector(SEL_CANCELAR):m.querySelector('input,.modal-acoes button');
    (alvo||m.querySelector('button')).focus();
  }
  function fecharModal(m){
    m.hidden=true;
    document.body.style.overflow='';
    if(ultimoFoco)ultimoFoco.focus();
  }

  btnAjuda.addEventListener('click',function(){alternarGaveta(!gavetaAberta());});

  document.addEventListener('click',function(e){
    var t=e.target;
    var abre=t.closest('[data-abrir]');
    if(abre){e.preventDefault();abrirModal(document.getElementById(abre.getAttribute('data-abrir')));return;}
    var fecha=t.closest('.modal-x,'+SEL_CANCELAR);
    if(fecha){fecharModal(fecha.closest('.modal'));return;}
    if(t.closest('[data-fechar-gaveta]')){alternarGaveta(false);return;}
    var disp=t.closest('.banner .btn-txt');
    if(disp){document.getElementById('conteudo').focus();disp.closest('.banner').remove();}
  });

  document.addEventListener('keydown',function(e){
    var m=document.querySelector('.modal:not([hidden])');
    if(e.key==='Escape'){
      if(m){fecharModal(m);}else if(gavetaAberta()){alternarGaveta(false);}
      return;
    }
    if(e.key==='Tab'&&m){
      var f=m.querySelectorAll('button,input,a[href]');
      var primeiro=f[0],ultimo=f[f.length-1];
      if(e.shiftKey&&document.activeElement===primeiro){e.preventDefault();ultimo.focus();}
      else if(!e.shiftKey&&document.activeElement===ultimo){e.preventDefault();primeiro.focus();}
    }
  });

  var form=document.getElementById('form-conv');
  var campo=document.getElementById('conv-email');
  var erro=document.getElementById('conv-erro');
  form.addEventListener('submit',function(e){
    if(!campo.checkValidity()){
      e.preventDefault();
      erro.hidden=false;
      campo.setAttribute('aria-invalid','true');
      campo.focus();
    }
  });
  campo.addEventListener('input',function(){
    if(campo.checkValidity()){erro.hidden=true;campo.removeAttribute('aria-invalid');}
  });
})();
</script>
</body>
