  function alternaGaveta(abrir){
    gaveta.hidden=!abrir;
    btnAjuda.setAttribute('aria-expanded',String(abrir));
    if(abrir)gaveta.querySelector('a').focus();
  }
  btnAjuda.addEventListener('click',function(){alternaGaveta(gaveta.hidden);});
  function abre(m,gatilho){
    ultimo=gatilho||document.activeElement;
    m.hidden=false;
    document.body.style.overflow='hidden';
    var f=m.querySelector('input,.modal-acoes .btn:not(.btn-perigo):not(.btn-prim),.btn-prim');
    if(f)f.focus();
  }
  function fecha(m){
    m.hidden=true;
    if(!document.querySelector('.modal:not([hidden])'))document.body.style.overflow='';
    if(ultimo&&ultimo.focus)ultimo.focus();
  }
  document.addEventListener('click',function(e){
    var g=e.target.closest('[aria-haspopup="dialog"]');
    if(g){var m=document.getElementById(g.getAttribute('aria-controls'));if(m)abre(m,g);return;}
    var d=e.target.closest('.banner .btn-txt');
    if(d){d.closest('.banner').remove();document.getElementById('conteudo').focus();return;}
