<script>
(function(){
  var foc='a[href],button:not([disabled]),input:not([disabled]),[tabindex]:not([tabindex="-1"])';
  var ultimoFoco=null;
  function abrir(m,gatilho){
    ultimoFoco=gatilho||document.activeElement;
    m.hidden=false;
    document.body.style.overflow='hidden';
    var f=m.querySelector(foc);
    if(f)f.focus();
  }
  function fechar(m){
    m.hidden=true;
    document.body.style.overflow='';
    if(ultimoFoco)ultimoFoco.focus();
  }
  document.querySelectorAll('[aria-haspopup="dialog"]').forEach(function(b){
    b.addEventListener('click',function(){
      abrir(document.getElementById(b.getAttribute('aria-controls')),b);
    });
  });
  document.querySelectorAll('.modal').forEach(function(m){
    m.addEventListener('click',function(e){
      if(e.target===m||e.target.closest('[data-fechar]'))fechar(m);
    });
    m.addEventListener('keydown',function(e){
      if(e.key==='Escape'){fechar(m);return;}
      if(e.key!=='Tab')return;
      var l=m.querySelectorAll(foc);
      if(!l.length)return;
      var p=l[0],u=l[l.length-1];
      if(e.shiftKey&&document.activeElement===p){e.preventDefault();u.focus();}
      else if(!e.shiftKey&&document.activeElement===u){e.preventDefault();p.focus();}
    });
  });

  var ajuda=document.querySelector('[aria-controls="gaveta"]');
  var g=document.getElementById('gaveta');
  function alternar(mostrar){
    g.hidden=!mostrar;
    ajuda.setAttribute('aria-expanded',String(mostrar));
    if(mostrar)g.querySelector('[data-fechar]').focus();else ajuda.focus();
  }
  ajuda.addEventListener('click',function(){alternar(g.hidden);});
  g.querySelector('[data-fechar]').addEventListener('click',function(){alternar(false);});
  g.addEventListener('keydown',function(e){if(e.key==='Escape')alternar(false);});

  var banner=document.querySelector('.banner');
  if(banner){
    banner.querySelector('.btn-txt').addEventListener('click',function(){
      banner.remove();
      document.getElementById('conteudo').focus();
    });
  }

  var f=document.getElementById('form-convite');
  var i=document.getElementById('conv-email');
  var er=document.getElementById('conv-erro');
  function limpar(){er.hidden=true;i.removeAttribute('aria-invalid');i.removeAttribute('aria-describedby');}
  f.addEventListener('submit',function(e){
    if(!i.checkValidity()){
      e.preventDefault();
      er.hidden=false;
      i.setAttribute('aria-invalid','true');
      i.setAttribute('aria-describedby','conv-erro');
      i.focus();
    }
  });
  i.addEventListener('input',function(){if(!er.hidden&&i.checkValidity())limpar();});
})();
</script>
</body>
