function buscarCep(){var s=document.getElementById('cep-status');if(s){s.textContent='Endereço localizado.';}}
@@ DEPOIS
var BRL=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});
var DESC=0.10;
function $(i){return document.getElementById(i);}
function num(t){return parseFloat(t.replace(/[^\d,]/g,'').replace(',','.'))||0;}
function buscarCep(){
  var s=$('cep-status'),d=$('ent-cep').value.replace(/\D/g,'');
  if(d.length!==8){s.textContent='Digite um CEP com 8 números.';return;}
  s.textContent='Buscando endereço...';
  fetch('https://viacep.com.br/ws/'+d+'/json/').then(function(r){if(!r.ok){throw 0;}return r.json();}).then(function(j){
    if(j.erro){s.textContent='CEP não encontrado. Preencha o endereço manualmente.';return;}
    $('ent-rua').value=j.logradouro||'';
    $('ent-cidade').value=j.localidade||'';
    $('ent-uf').value=j.uf;
    $('ent-pais').value='BR';
    s.textContent='Endereço localizado. Confira e informe o número.';
    atualizar();
  }).catch(function(){s.textContent='Não foi possível buscar o CEP. Preencha o endereço manualmente.';});
}
@@ FIM

@@ ANTES
function aplicarCupom(){var i=document.getElementById('cupom');if(i){i.focus();}}
@@ DEPOIS
function aplicarCupom(){
  var i=$('cupom'),s=$('cupom-status'),v=i.value.trim();
  if(!v){s.textContent='Digite o código do cupom.';i.focus();return;}
  s.textContent='Validando cupom...';
  fetch('/api/cupom',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({codigo:v})})
    .then(function(r){return r.json().then(function(j){if(!r.ok){throw j;}return j;});})
    .then(function(){s.textContent='Cupom aplicado.';})
    .catch(function(e){s.textContent=(e&&e.mensagem)||'Não foi possível validar o cupom. Tente novamente.';});
}
@@ FIM

@@ ANTES
function reenviar(){var o=document.getElementById('otp');if(o){o.focus();}}
@@ DEPOIS
var tmrReenvio;
function iniciarEspera(msg){
  var b=$('btn-reenviar'),t=$('reenviar-info'),n=30;
  b.disabled=true;
  t.textContent=msg||'Você poderá pedir um novo código em 30 segundos.';
  clearInterval(tmrReenvio);
  tmrReenvio=setInterval(function(){n--;if(n<=0){clearInterval(tmrReenvio);b.disabled=false;t.textContent='Você já pode pedir um novo código.';}},1000);
}
function reenviar(){
  var t=$('reenviar-info');
  fetch('/api/otp/reenviar',{method:'POST'}).then(function(r){
    if(!r.ok){throw 0;}
    iniciarEspera('Novo código enviado por SMS. Você poderá pedir outro em 30 segundos.');
    $('otp').focus();
  }).catch(function(){t.textContent='Não foi possível reenviar o código. Tente novamente.';});
}
@@ FIM

