function abrirDialogo(n){var v=document.getElementById('veu');var p=document.getElementById('dlg-p');if(p){p.textContent=n+' será removido do pedido.';}if(v){v.hidden=false;}}
@@ DEPOIS
var gatilho=null,linhaAlvo=null;
function bloqueio(sim){document.querySelectorAll('.pular,.topo,main,.rodape').forEach(function(e){e.inert=sim;});}
function abrirDialogo(n){
  gatilho=document.activeElement;
  linhaAlvo=gatilho&&gatilho.closest?gatilho.closest('tr'):null;
  $('dlg-p').textContent=n+' será removido do pedido.';
  bloqueio(true);
  $('veu').hidden=false;
  $('veu').querySelector('.btn-sec').focus();
}
function confirmarRemocao(){
  var l=linhaAlvo,prox=l&&(l.nextElementSibling||l.previousElementSibling);
  if(l){l.remove();}
  linhaAlvo=null;
  if(prox&&prox.querySelector('button')){gatilho=prox.querySelector('button');}
  else{gatilho=$('t-itens');gatilho.tabIndex=-1;}
  fecharDialogo();
  atualizar();
}
@@ FIM

@@ ANTES
function fecharDialogo(){var v=document.getElementById('veu');if(v){v.hidden=true;}}
@@ DEPOIS
function fecharDialogo(){
  $('veu').hidden=true;
  bloqueio(false);
  if(gatilho&&document.contains(gatilho)){gatilho.focus();}
}
function atualizar(){
  var linhas=document.querySelectorAll('#itens tbody tr'),sub=0,un=0;
  linhas.forEach(function(l){un+=parseInt(l.cells[2].textContent,10)||0;sub+=num(l.cells[4].textContent);});
  sub=Math.round(sub*100)/100;
  var r=document.querySelector('input[name=frete]:checked'),lab=r.closest('label'),
      frete=num(lab.querySelector('.preco').textContent),
      nome=lab.querySelector('span').childNodes[0].textContent.trim(),
      prazo=lab.querySelector('small').textContent.replace(/[()]/g,''),
      desc=Math.round(sub*DESC*100)/100,
      total=Math.round((sub+frete-desc)*100)/100;
  $('res-sub-l').textContent='Subtotal ('+un+' un.)';
  $('res-sub').textContent=BRL.format(sub);
  $('res-frete-l').textContent='Frete '+nome;
  $('res-frete').textContent=BRL.format(frete);
  $('res-desc').textContent='- '+BRL.format(desc);
  $('res-total').textContent=BRL.format(total);
  $('tab-sub').textContent=BRL.format(sub);
  $('tab-cap').textContent=linhas.length+' produtos, '+un+' unidades';
  $('rev-itens').textContent=un+' unidades em '+linhas.length+' produtos';
  $('rev-frete').textContent=nome+', '+prazo+' ('+BRL.format(frete)+')';
  $('res-entrega').textContent=nome+': '+prazo+', para '+$('ent-cidade').value+'/'+$('ent-uf').value+'.';
  var sel=$('parcelas'),v=sel.value||'1';
  sel.innerHTML='';
  for(var n=1;n<=12;n++){sel.add(new Option(n+'x de '+BRL.format(total/n)+(n===1?' (à vista)':''),String(n)));}
  sel.value=v;
  var b=$('pagar');
  b.textContent='Pagar '+BRL.format(total);
  b.disabled=linhas.length===0;
}
function alternarMetodo(){
  var card=document.querySelector('input[name=metodo]:checked').value==='cartao';
  $('cartao').disabled=!card;
  $('cartao').hidden=!card;
  $('rot-otp').closest('.bloco').hidden=!card;
  $('otp').disabled=!card;
}
document.addEventListener('change',function(e){
  var t=e.target;
  if(t.name==='metodo'){alternarMetodo();}
  if(t.name==='frete'){atualizar();}
  if(t.id==='ent-cep'&&t.value.replace(/\D/g,'').length===8){buscarCep();}
  if(t.id==='ent-cidade'||t.id==='ent-uf'){atualizar();}
});
document.addEventListener('input',function(e){
  var t=e.target,v;
  if(t.id==='cc-num'){v=t.value.replace(/\D/g,'').slice(0,19);t.value=v.replace(/(.{4})/g,'$1 ').trim();}
