var ultimoGatilho = null;
function abrirModal(m, gatilho) {
  ultimoGatilho = gatilho;
  m.hidden = false;
  document.body.style.overflow = 'hidden';
  var f = m.querySelector('[data-foco]');
  if (f) f.focus();
}
function fecharModal(m) {
  m.hidden = true;
  document.body.style.overflow = '';
  if (ultimoGatilho) ultimoGatilho.focus();
}
document.querySelectorAll('[data-abrir]').forEach(function (b) {
  b.addEventListener('click', function () {
    var m = document.getElementById(b.getAttribute('data-abrir'));
    var linha = b.closest('tr');
    var alvo = document.getElementById('rev-app');
    if (linha && alvo && m.id === 'fundo-revogar') alvo.textContent = linha.querySelector('th').textContent;
    abrirModal(m, b);
  });
});
document.querySelectorAll('[data-fechar]').forEach(function (b) {
  b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
});
document.querySelectorAll('[data-modal]').forEach(function (m) {
  m.addEventListener('click', function (e) { if (e.target === m) fecharModal(m); });
});
document.addEventListener('keydown', function (e) {
  var m = document.querySelector('[data-modal]:not([hidden])');
  if (!m) return;
  if (e.key === 'Escape') { fecharModal(m); return; }
  if (e.key === 'Tab') {
    var f = m.querySelectorAll('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])');
    var a = f[0], z = f[f.length - 1];
    if (e.shiftKey && document.activeElement === a) { e.preventDefault(); z.focus(); }
    else if (!e.shiftKey && document.activeElement === z) { e.preventDefault(); a.focus(); }
  }
});
document.getElementById('btn-dispensar').addEventListener('click', function () {
  document.getElementById('banner-sucesso').hidden = true;
  var prox = document.querySelector('#form-prefs input');
  if (prox) prox.focus();
});

var formPerfil = document.getElementById('form-perfil');
var resumo = document.getElementById('resumo-erros');
var regras = [
  { id: 'email', rotulo: 'E-mail corporativo', msg: 'Informe um endereço completo, como nome@dominio.com.br.', ok: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()); } },
  { id: 'telefone', rotulo: 'Telefone celular', msg: 'Informe o DDD e o número completo, por exemplo (11) 91234-5678.', ok: function (v) { var d = v.replace(/\D/g, ''); return d.length === 10 || d.length === 11; } }
];
function validarPerfil() {
  var lista = resumo.querySelector('ul');
  lista.innerHTML = '';
  var primeiro = null;
  regras.forEach(function (r) {
    var inp = document.getElementById(r.id);
    var campo = inp.closest('.campo');
    var err = document.getElementById('erro-' + r.id);
    var ok = r.ok(inp.value);
    campo.classList.toggle('campo-erro', !ok);
    inp.setAttribute('aria-invalid', ok ? 'false' : 'true');
    err.hidden = ok;
    var marca = campo.querySelector('.marca-erro');
    if (marca) marca.hidden = ok;
    if (!ok) {
      if (!primeiro) primeiro = inp;
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + r.id;
      a.textContent = r.rotulo + ': ' + r.msg;
      li.appendChild(a);
      lista.appendChild(li);
    }
  });
  resumo.hidden = !primeiro;
  return primeiro;
}
formPerfil.addEventListener('submit', function (e) {
  if (validarPerfil()) { e.preventDefault(); resumo.focus(); }
});
regras.forEach(function (r) { document.getElementById(r.id).addEventListener('change', validarPerfil); });
@@ FIM

