(function () {
  var gatilho = null;
  function focaveis(m) {
    return Array.prototype.slice.call(m.querySelectorAll('button,[href],input,select,textarea')).filter(function (el) { return !el.disabled; });
  }
  function abrir(m, origem) {
    gatilho = origem;
    m.hidden = false;
    var seguro = m.querySelector('.btn:not(.perigo)');
    (seguro || focaveis(m)[0]).focus();
  }
  function fechar(m) {
    m.hidden = true;
    if (gatilho) { gatilho.focus(); gatilho = null; }
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    var revogar = b.getAttribute('data-abrir') === 'fundo-revogar';
    var app = revogar ? b.closest('tr').querySelector('th').textContent.trim() : '';
    if (revogar) { b.setAttribute('aria-label', 'Revogar acesso de ' + app); }
    b.addEventListener('click', function () {
      if (revogar) {
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + app + '?';
        document.getElementById('dlg-revogar-d').textContent = app + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
      }
      abrir(document.getElementById(b.getAttribute('data-abrir')), b);
    });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });
  document.querySelectorAll('[data-modal]').forEach(function (m) {
    m.addEventListener('click', function (e) { if (e.target === m) { fechar(m); } });
  });
  document.addEventListener('keydown', function (e) {
    var m = document.querySelector('[data-modal]:not([hidden])');
    if (!m) { return; }
    if (e.key === 'Escape') { fechar(m); return; }
    if (e.key === 'Tab') {
      var f = focaveis(m), p = f[0], u = f[f.length - 1];
      if (e.shiftKey && document.activeElement === p) { e.preventDefault(); u.focus(); }
      else if (!e.shiftKey && document.activeElement === u) { e.preventDefault(); p.focus(); }
    }
  });

  document.querySelectorAll('tbody .btn').forEach(function (b) {
    if (b.textContent.trim() === 'Encerrar sessão') {
      b.setAttribute('aria-label', 'Encerrar sessão de ' + b.closest('tr').querySelector('th').textContent.trim());
    }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    var h = document.getElementById('h-pref');
    h.setAttribute('tabindex', '-1');
    h.focus();
  });

  var form = document.getElementById('form-perfil');
  var resumo = document.getElementById('resumo-erros');
  var titulo = document.getElementById('resumo-titulo');
  var lista = document.getElementById('resumo-lista');
  var tituloPagina = 'Configurações da conta - Colégio Novo Saber';
  var regras = [
    { id: 'email', rotulo: 'E-mail corporativo',
      valido: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()); },
      msg: 'informe o endereço completo, com domínio, por exemplo nome@dominio.com.br.' },
    { id: 'telefone', rotulo: 'Telefone celular',
      valido: function (v) { var d = v.replace(/\D/g, ''); return d.length === 10 || d.length === 11; },
      msg: 'informe o DDD e os 9 dígitos, por exemplo (11) 91234-5678.' }
  ];
  form.addEventListener('submit', function (e) {
    var erros = [];
    regras.forEach(function (r) {
      var campo = document.getElementById(r.id);
      var ruim = !r.valido(campo.value);
      campo.setAttribute('aria-invalid', ruim ? 'true' : 'false');
      campo.closest('.campo').classList.toggle('campo-erro', ruim);
      document.getElementById('erro-' + r.id).hidden = !ruim;
      if (ruim) { erros.push(r); }
    });
    if (erros.length) {
      e.preventDefault();
      titulo.textContent = 'Corrija ' + erros.length + (erros.length === 1 ? ' campo' : ' campos') + ' para salvar o perfil';
      lista.innerHTML = '';
      erros.forEach(function (r) {
        var li = document.createElement('li');
        var a = document.createElement('a');
        a.href = '#' + r.id;
        a.textContent = r.rotulo + ': ' + r.msg;
        li.appendChild(a);
        lista.appendChild(li);
      });
      resumo.hidden = false;
      document.title = 'Erro: ' + tituloPagina;
      resumo.focus();
    } else {
      resumo.hidden = true;
      document.title = tituloPagina;
    }
  });
  lista.addEventListener('click', function (e) {
    var a = e.target.closest('a');
    if (a) { e.preventDefault(); document.getElementById(a.getAttribute('href').slice(1)).focus(); }
  });
})();
@@ FIM

@@ DECISOES
- Layout responsivo para celular: coluna única, menu lateral vira faixa rolável, grade de campos em 1 coluna e topo que quebra linha | regra: NENHUMA
- Alvos de toque de 44px no celular e fonte de 14px nas dicas e botões pequenos | regra: TD25
- Tabelas de aplicativos e sessões em região rolável com nome e acessível por teclado, para não estourar a tela | regra: NENHUMA
- Rótulo do botão da barra de notificações e dos botões de ícone (remover foto, dispensar aviso) via aria-label | regra: TD50
- Título "Início" virou link de verdade e o nome da marca deixou de ser um segundo h1 | regra: TD50
- Botões "Revogar acesso" e "Encerrar sessão" ganham nome acessível com o app ou dispositivo | regra: NE10
- "Sessão atual" deixou de ser botão sem ação e virou texto | regra: TD50
- Situação do aplicativo agora mostra texto (Ativo/Expirado) além da cor | regra: FC30
- Email com type=email e telefone com type=tel, com autocomplete válido (name, email, tel, organization, address-level2) | regra: FC25
- Mensagens de erro explicam como corrigir, com texto "Erro:" oculto para leitores de tela, e o telefone ganhou mensagem própria | regra: FC32
- Erro de e-mail e telefone deixa de depender só da cor (texto visível ligado por aria-describedby) | regra: FC33
- Resumo de erros no topo com links para os campos e role=alert em elemento interno | regra: FC17
- Resumo de erros no topo com título e links para cada campo com problema | regra: FC16
- Title da página prefixado com "Erro:" enquanto há erros | regra: FC18
- Validação roda no envio (novalidate + script) e o valor digitado é preservado | regra: FC19
- Telefone aceita parênteses, espaços e hífen e só conta os dígitos | regra: FC21
- Removido o disabled do botão "Salvar alterações" | regra: FC14
- Campo "Sobre você" marcado como (opcional) e com maxlength=200 conforme a dica | regra: FC08
- Região de status (#live) deixou de usar display:none para poder ser anunciada | regra: FC31
- Esqueleto de carregamento escondido porque conflitava com o erro de histórico exibido ao mesmo tempo | regra: TD43
- Botões dos modais renomeados de Sim/Não para ações claras (Excluir minha conta, Revogar acesso, Cancelar) | regra: NE13
- Modal de revogação cita o aplicativo escolhido no título e no texto | regra: NENHUMA
- Foco vai para o botão seguro (Cancelar) ao abrir o modal, fica preso nele e volta ao gatilho ao fechar | regra: NE15
- Modais fecham com Escape ou clique no fundo, além do botão Cancelar | regra: NE13
- Ao dispensar o banner de sucesso, o foco vai para o título da seção em vez de se perder | regra: NENHUMA
- Estilo de foco visível reforçado para uso por teclado | regra: NENHUMA
@@ FIM

