(function () {
  var live = document.getElementById('live');
  var aberto = null, origem = null, linhaApp = null;

  function anunciar(t) { live.textContent = ''; setTimeout(function () { live.textContent = t; }, 50); }

  function abrir(id, de) {
    aberto = document.getElementById(id);
    origem = de;
    aberto.hidden = false;
    var alvo = aberto.querySelector('[data-fechar]');
    if (alvo) alvo.focus();
  }

  function fechar() {
    if (!aberto) return;
    aberto.hidden = true;
    aberto = null;
    if (origem && document.contains(origem)) origem.focus();
    origem = null;
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var id = b.getAttribute('data-abrir');
      if (id === 'fundo-revogar') {
        linhaApp = b.closest('tr');
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + linhaApp.querySelector('th').textContent + '?';
      }
      abrir(id, b);
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) { b.addEventListener('click', fechar); });
  document.querySelectorAll('[data-modal]').forEach(function (m) {
    m.addEventListener('click', function (e) { if (e.target === m) fechar(); });
  });

  document.addEventListener('keydown', function (e) {
    if (!aberto) return;
    if (e.key === 'Escape') { fechar(); return; }
    if (e.key === 'Tab') {
      var f = aberto.querySelectorAll('button,input');
      var primeiro = f[0], ultimo = f[f.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    }
  });

  document.getElementById('confirmar-revogar').addEventListener('click', function () {
    var nome = linhaApp.querySelector('th').textContent;
    var corpo = linhaApp.parentNode;
    corpo.removeChild(linhaApp);
    var n = corpo.rows.length;
    var cont = document.getElementById('contagem-acessos');
    cont.textContent = n === 0 ? 'Nenhum aplicativo com acesso à sua conta' : (n === 1 ? '1 aplicativo com acesso à sua conta' : n + ' aplicativos com acesso à sua conta');
    cont.setAttribute('tabindex', '-1');
    origem = cont;
    fechar();
    anunciar('Acesso de ' + nome + ' revogado.');
  });

  document.getElementById('confirmar-exclusao').addEventListener('click', function () {
    var inp = document.getElementById('confirma-exclusao');
    var er = document.getElementById('erro-exclusao');
    if (inp.value.trim().toUpperCase() !== 'EXCLUIR') {
      er.hidden = false;
      inp.setAttribute('aria-invalid', 'true');
      inp.focus();
      return;
    }
    er.hidden = true;
    inp.removeAttribute('aria-invalid');
    inp.value = '';
    fechar();
    anunciar('Exclusão solicitada. Seus dados serão apagados em até 30 dias.');
  });

  document.querySelectorAll('#acessos tbody button').forEach(function (b) {
    b.setAttribute('aria-label', b.textContent + ': ' + b.closest('tr').querySelector('th').textContent);
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () { document.getElementById('banner-sucesso').hidden = true; });

  var regras = [
    ['nome', function (v) { return v.trim() ? '' : 'Informe seu nome completo.'; }],
    ['email', function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()) ? '' : 'O e-mail está incompleto. Informe o endereço com domínio, por exemplo nome@empresa.com.br.'; }],
    ['telefone', function (v) { var d = v.replace(/\D/g, ''); return (d.length === 10 || d.length === 11) ? '' : 'Faltam dígitos. Informe DDD e número, por exemplo (11) 91234-5678.'; }]
  ];

  function validar() {
    var lista = [];
    regras.forEach(function (r) {
      var inp = document.getElementById(r[0]);
      var er = document.getElementById('erro-' + r[0]);
      var caixa = inp.closest('.campo');
      var msg = r[1](inp.value);
      if (msg) {
        er.innerHTML = '<span class="sr-only">Erro: </span>';
        er.appendChild(document.createTextNode(msg));
        er.hidden = false;
        caixa.classList.add('campo-erro');
        inp.setAttribute('aria-invalid', 'true');
        lista.push({ id: r[0], txt: caixa.querySelector('label').textContent + ': ' + msg });
      } else {
        er.hidden = true;
        caixa.classList.remove('campo-erro');
        inp.removeAttribute('aria-invalid');
      }
    });
    var ul = document.getElementById('lista-erros');
    ul.innerHTML = '';
    lista.forEach(function (it) {
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + it.id;
      a.textContent = it.txt;
      li.appendChild(a);
      ul.appendChild(li);
    });
    document.getElementById('msg-resumo').textContent = lista.length === 1 ? '1 campo precisa de correção:' : lista.length + ' campos precisam de correção:';
    document.getElementById('resumo-erros').hidden = lista.length === 0;
    document.title = (lista.length ? 'Erro: ' : '') + 'Configurações da conta - Mercado Bom Preço';
    return lista;
  }

  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    var lista = validar();
    if (lista.length) {
      e.preventDefault();
      document.querySelector('#lista-erros a').focus();
    }
  });

  document.getElementById('lista-erros').addEventListener('click', function (e) {
    var a = e.target.closest('a');
    if (!a) return;
    e.preventDefault();
    document.getElementById(a.getAttribute('href').slice(1)).focus();
  });
})();
@@ FIM

