(function () {
  var live = document.getElementById('live');
  function anunciar(t) { live.textContent = ''; setTimeout(function () { live.textContent = t; }, 50); }

  document.querySelectorAll('svg.ico:not([aria-hidden])').forEach(function (s) {
    s.setAttribute('aria-hidden', 'true'); s.setAttribute('focusable', 'false');
  });

  // Situação: texto visível além da cor
  document.querySelectorAll('.ponto[aria-label]').forEach(function (p) {
    var t = document.createElement('span');
    t.textContent = p.getAttribute('aria-label');
    p.removeAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    p.parentNode.appendChild(t);
  });

  // Rótulos acessíveis únicos para botões repetidos nas tabelas
  document.querySelectorAll('[data-abrir="fundo-revogar"]').forEach(function (b) {
    var app = b.closest('tr').querySelector('th').textContent.trim();
    b.setAttribute('data-app', app);
    b.setAttribute('aria-label', 'Revogar acesso de ' + app);
  });
  document.querySelectorAll('tbody .btn').forEach(function (b) {
    if (b.textContent.trim() === 'Encerrar sessão') {
      b.setAttribute('aria-label', 'Encerrar sessão em ' + b.closest('tr').querySelector('th').textContent.trim());
    }
  });

  // Modais: foco, Escape, trap de Tab, retorno do foco
  var ativo = null, origem = null;
  function focaveis(m) {
    return Array.prototype.slice.call(m.querySelectorAll('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])'))
      .filter(function (e) { return !e.disabled; });
  }
  function abrir(fundo, gatilho) {
    origem = gatilho; ativo = fundo; fundo.hidden = false;
    document.body.style.overflow = 'hidden';
    (fundo.querySelector('[data-inicial]') || focaveis(fundo)[0]).focus();
  }
  function fechar() {
    if (!ativo) return;
    ativo.hidden = true; ativo = null;
    document.body.style.overflow = '';
    if (origem && document.contains(origem)) origem.focus();
  }
  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var id = b.getAttribute('data-abrir');
      if (id === 'fundo-revogar') {
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + b.getAttribute('data-app') + '?';
        document.getElementById('fundo-revogar').setAttribute('data-app', b.getAttribute('data-app'));
      }
      abrir(document.getElementById(id), b);
    });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) { b.addEventListener('click', fechar); });
  document.querySelectorAll('[data-confirmar]').forEach(function (b) {
    b.addEventListener('click', function () {
      var fundo = b.closest('[data-modal]');
      document.dispatchEvent(new CustomEvent('confirmar-acao', { detail: { acao: b.getAttribute('data-confirmar'), app: fundo.getAttribute('data-app') } }));
      fechar();
    });
  });
  document.querySelectorAll('[data-modal]').forEach(function (f) {
    f.addEventListener('click', function (e) { if (e.target === f) fechar(); });
  });
  document.addEventListener('keydown', function (e) {
    if (!ativo) return;
    if (e.key === 'Escape') { e.preventDefault(); fechar(); return; }
    if (e.key === 'Tab') {
      var f = focaveis(ativo), p = f[0], u = f[f.length - 1];
      if (e.shiftKey && document.activeElement === p) { e.preventDefault(); u.focus(); }
      else if (!e.shiftKey && document.activeElement === u) { e.preventDefault(); p.focus(); }
    }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    var h = document.getElementById('h-pref'); h.setAttribute('tabindex', '-1'); h.focus();
  });

  // Validação do perfil
  function validar(id, ok, msg) {
    var input = document.getElementById(id), campo = input.closest('.campo');
    var erro = document.getElementById('erro-' + id), valido = ok(input.value.trim());
    if (!erro) { erro = document.createElement('p'); erro.className = 'erro'; erro.id = 'erro-' + id; campo.appendChild(erro); }
    erro.textContent = valido ? '' : msg; erro.hidden = valido;
    campo.classList.toggle('campo-erro', !valido);
    if (valido) input.removeAttribute('aria-invalid'); else input.setAttribute('aria-invalid', 'true');
    var ids = (input.getAttribute('aria-describedby') || '').split(' ').filter(function (x) { return x && x !== erro.id; });
    if (!valido) ids.push(erro.id);
    input.setAttribute('aria-describedby', ids.join(' '));
    return valido;
  }
  var checks = [
    ['nome', function (v) { return v.length > 1; }, 'Informe seu nome completo.'],
    ['email', function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v); }, 'Informe um e-mail completo, como nome@empresa.com.br.'],
    ['telefone', function (v) { var d = v.replace(/\D/g, ''); return d.length === 10 || d.length === 11; }, 'Telefone incompleto. Informe DDD e número, como (11) 91234-5678.']
  ];
  checks.forEach(function (c) {
    document.getElementById(c[0]).addEventListener('blur', function () { validar(c[0], c[1], c[2]); });
  });
  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    var primeiro = null;
    checks.forEach(function (c) { if (!validar(c[0], c[1], c[2]) && !primeiro) primeiro = document.getElementById(c[0]); });
    if (primeiro) { e.preventDefault(); primeiro.focus(); anunciar('Corrija os campos destacados para salvar.'); }
  });
})();
