function atualizarContagem() {
  var n = document.querySelectorAll('[data-abrir="fundo-revogar"]:not([hidden])').length;
  document.getElementById('contagem-acessos').textContent = n + (n === 1 ? ' aplicativo com acesso' : ' aplicativos com acesso') + ' à sua conta';
