  b.setAttribute('aria-label', 'Revogar acesso de ' + app);
  b.addEventListener('click', function () {
    var cel = b.parentNode, msg = document.createElement('span'), desf = document.createElement('button');
    b.hidden = true;
    msg.textContent = 'Acesso revogado ';
    desf.type = 'button'; desf.className = 'btn pequeno'; desf.textContent = 'Desfazer';
