/* Perfil: valida só ao enviar, com resumo de erros */
(function () {
  var f = document.getElementById('form-perfil'), res = document.getElementById('resumo-erros'), lista = document.getElementById('lista-erros');
  var regras = [
    { id: 'email', erro: 'erro-email', dica: 'dica-email', ok: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()); }, msg: 'Informe um e-mail válido, como nome@escola.com.br.' },
    { id: 'telefone', erro: 'erro-telefone', dica: 'dica-telefone', ok: function (v) { var d = v.replace(/\D/g, ''); return d === '' || d.length === 10 || d.length === 11; }, msg: 'Informe o telefone com DDD, por exemplo (11) 91234-5678.' }
  ];
  function limpar(r) {
    var el = document.getElementById(r.id), p = document.getElementById(r.erro);
    el.removeAttribute('aria-invalid'); p.hidden = true; p.textContent = ''; el.setAttribute('aria-describedby', r.dica);
  }
  f.addEventListener('submit', function (e) {
    var primeiro = null;
    lista.innerHTML = '';
    regras.forEach(function (r) {
      var el = document.getElementById(r.id), p = document.getElementById(r.erro);
      limpar(r);
      if (!r.ok(el.value)) {
        el.setAttribute('aria-invalid', 'true'); p.textContent = r.msg; p.hidden = false;
        el.setAttribute('aria-describedby', r.dica + ' ' + r.erro);
        var li = document.createElement('li'), a = document.createElement('a');
        a.href = '#' + r.id;
        a.textContent = document.querySelector('label[for="' + r.id + '"]').textContent + ': ' + r.msg;
        a.addEventListener('click', function (ev) { ev.preventDefault(); el.focus(); });
        li.appendChild(a); lista.appendChild(li);
        primeiro = primeiro || el;
      }
    });
    if (primeiro) {
      e.preventDefault();
      document.getElementById('banner-sucesso').hidden = true;
      res.hidden = false; res.focus();
    } else { res.hidden = true; }
  });
  f.addEventListener('reset', function () { res.hidden = true; regras.forEach(limpar); });
})();
