<script>
(function(){
  var resumo=document.getElementById('resumo-erros');
  if(resumo){resumo.focus();}
  var tabs=[].slice.call(document.querySelectorAll('[role=tab]'));
  function selecionar(t,foco){
    tabs.forEach(function(x){
      var on=x===t;
      x.setAttribute('aria-selected',on?'true':'false');
      x.tabIndex=on?0:-1;
      x.classList.toggle('aba-ativa',on);
      document.getElementById(x.getAttribute('aria-controls')).hidden=!on;
    });
    if(foco){t.focus();}
  }
  tabs.forEach(function(t,i){
    t.addEventListener('click',function(){selecionar(t);});
    t.addEventListener('keydown',function(e){
      var n=null;
      if(e.key==='ArrowRight'){n=tabs[(i+1)%tabs.length];}
      else if(e.key==='ArrowLeft'){n=tabs[(i-1+tabs.length)%tabs.length];}
      else if(e.key==='Home'){n=tabs[0];}
      else if(e.key==='End'){n=tabs[tabs.length-1];}
      if(n){e.preventDefault();selecionar(n,true);}
    });
  });
  var mesmo=document.getElementById('mesmo');
  var campos=['cep','rua','num','comp','bairro','cidade','uf'];
  function sincronizar(){
    campos.forEach(function(k){
      var r=document.getElementById(k+'-res'),c=document.getElementById(k+'-cor');
      if(mesmo.checked){c.value=r.value;}
      c.disabled=mesmo.checked;
    });
  }
  mesmo.addEventListener('change',sincronizar);
  campos.forEach(function(k){
    document.getElementById(k+'-res').addEventListener('input',function(){if(mesmo.checked){sincronizar();}});
  });
})();
</script>
</body>
