(function () {
  var live = document.getElementById('live');
  var aberto = null, origem = null;

  function focaveis(m) {
    return Array.prototype.filter.call(
      m.querySelectorAll('a[href],button,input,select,textarea,[tabindex]:not([tabindex="-1"])'),
      function (e) { return !e.disabled; });
  }
  function abrir(fundo, gatilho) {
    aberto = fundo; origem = gatilho;
    fundo.hidden = false;
    document.body.style.overflow = 'hidden';
    (fundo.querySelector('[data-foco-inicial]') || focaveis(fundo)[0]).focus();
  }
  function fechar() {
    if (!aberto) return;
    aberto.hidden = true; aberto = null;
    document.body.style.overflow = '';
    if (origem && document.contains(origem)) origem.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    var app = '';
    var linha = b.closest('tr');
    if (linha) {
      app = linha.querySelector('th').textContent.trim();
      b.setAttribute('aria-label', 'Revogar acesso de ' + app);
    }
    b.addEventListener('click', function () {
      if (app) {
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + app + '?';
        document.getElementById('revogar-app').textContent = app;
      }
      abrir(document.getElementById(b.getAttribute('data-abrir')), b);
    });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) { b.addEventListener('click', fechar); });
  document.querySelectorAll('[data-confirmar]').forEach(function (b) {
    b.addEventListener('click', function () {
      // Ponto de integração: o back-end escuta este evento e executa a ação.
      document.dispatchEvent(new CustomEvent('confirmar-acao', { detail: { acao: b.getAttribute('data-confirmar') } }));
      fechar();
    });
  });
  document.querySelectorAll('[data-modal]').forEach(function (f) {
    f.addEventListener('click', function (e) { if (e.target === f) fechar(); });
  });
  document.addEventListener('keydown', function (e) {
    if (!aberto) return;
    if (e.key === 'Escape') { e.preventDefault(); fechar(); return; }
    if (e.key === 'Tab') {
      var f = focaveis(aberto), p = f[0], u = f[f.length - 1];
      if (e.shiftKey && document.activeElement === p) { e.preventDefault(); u.focus(); }
      else if (!e.shiftKey && document.activeElement === u) { e.preventDefault(); p.focus(); }
    }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    live.textContent = 'Mensagem dispensada.';
    var t = document.getElementById('h-pref'); t.tabIndex = -1; t.focus();
  });

  var form = document.getElementById('form-perfil');
  var resumo = document.getElementById('resumo-erros');
  var regras = [
    { id: 'email', rotulo: 'E-mail corporativo',
      ok: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()); },
      msg: 'E-mail incompleto. Inclua o domínio completo, como nome@empresa.com.br.' },
    { id: 'telefone', rotulo: 'Telefone celular',
      ok: function (v) { var n = v.replace(/\D/g, '').length; return n === 10 || n === 11; },
      msg: 'Telefone incompleto. Digite DDD e número, como (11) 91234-5678.' }
  ];
  function validar() {
    var lista = resumo.querySelector('ul'); lista.innerHTML = '';
    var n = 0;
    regras.forEach(function (r) {
      var c = document.getElementById(r.id), campo = c.closest('.campo'), e = document.getElementById('erro-' + r.id);
      var ruim = !r.ok(c.value);
      campo.classList.toggle('campo-erro', ruim);
      c.setAttribute('aria-invalid', ruim ? 'true' : 'false');
      c.setAttribute('aria-describedby', 'dica-' + r.id + (ruim ? ' erro-' + r.id : ''));
      e.textContent = r.msg; e.hidden = !ruim;
      if (ruim) {
        n++;
        var li = document.createElement('li'), a = document.createElement('a');
        a.href = '#' + r.id; a.textContent = r.rotulo + ': ' + r.msg;
        li.appendChild(a); lista.appendChild(li);
      }
    });
    resumo.hidden = n === 0;
    document.getElementById('resumo-t').textContent = n === 1 ? 'Corrija 1 campo para salvar' : 'Corrija ' + n + ' campos para salvar';
    return n;
  }
  form.addEventListener('submit', function (e) {
    if (validar()) { e.preventDefault(); resumo.focus(); }
  });
  resumo.addEventListener('click', function (e) {
    var a = e.target.closest('a');
    if (!a) return;
    e.preventDefault();
    document.getElementById(a.getAttribute('href').slice(1)).focus();
  });
})();
@@ FIM

