function ordenar(el){ el.setAttribute('aria-sort', el.getAttribute('aria-sort') === 'ascending' ? 'descending' : 'ascending'); }
@@ DEPOIS
function ordenar(th){
  var asc = th.getAttribute('aria-sort') !== 'ascending';
  th.parentElement.querySelectorAll('th[aria-sort]').forEach(function (h) {
    h.setAttribute('aria-sort', 'none');
    var s = h.querySelector('.seta'); if (s) s.textContent = '⇅';
  });
  th.setAttribute('aria-sort', asc ? 'ascending' : 'descending');
  th.querySelector('.seta').textContent = asc ? '▲' : '▼';
}
document.querySelectorAll('thead .ord').forEach(function (b) {
  b.addEventListener('click', function () { ordenar(b.parentElement); });
});
@@ FIM
