    var f = document.querySelector('[data-modal]:not([hidden])');
    if (!f) { return; }
    if (e.key === 'Escape') { fecharModal(f); return; }
    if (e.key === 'Tab') {
      var bs = f.querySelectorAll('button'), p = bs[0], u = bs[bs.length - 1];
      if (e.shiftKey && document.activeElement === p) { e.preventDefault(); u.focus(); }
      else if (!e.shiftKey && document.activeElement === u) { e.preventDefault(); p.focus(); }
    }
  });

  /* Revogar acesso com desfazer (sem confirmação) */
  var barra = $('desfazer'), textoBarra = $('desfazer-txt'), ultimaLinha = null;
