  }
  document.querySelectorAll('[data-revogar]').forEach(function (b) {
    b.addEventListener('click', function () {
      var tr = b.closest('tr'), nome = tr.querySelector('th').textContent;
      tr.hidden = true; ultimaLinha = tr; contar();
      textoBarra.textContent = 'Acesso de ' + nome + ' revogado.';
