    ultimaLinha.querySelector('[data-revogar]').focus(); ultimaLinha = null;
  });

  /* Perfil: valida só ao enviar */
  var form = $('form-perfil'), resumo = $('resumo-erros'), lista = resumo.querySelector('ul');
