      [tel, (!ds || ds.length === 10 || ds.length === 11) ? '' : 'Informe o telefone com DDD, por exemplo (11) 91234-5678.']
    ];
    lista.textContent = '';
    checks.forEach(function (c) {
      marcar(c[0], c[1]);
      if (!c[1]) { return; }
      erros++;
      var li = document.createElement('li'), a = document.createElement('a');
      a.href = '#' + c[0].id; a.textContent = c[1];
      a.addEventListener('click', function (ev) { ev.preventDefault(); c[0].focus(); });
      li.appendChild(a); lista.appendChild(li);
    });
    if (erros) { e.preventDefault(); $('banner-sucesso').hidden = true; resumo.hidden = false; resumo.focus(); }
    else { resumo.hidden = true; }
  });
