(function () {
  var focaveis = 'a[href],button:not([disabled]),input:not([disabled]),select,textarea,[tabindex]:not([tabindex="-1"])';
  var aberto = null, origem = null;
  function abrir(gatilho) {
    var fundo = document.getElementById(gatilho.getAttribute('data-abrir'));
    var app = gatilho.getAttribute('data-app');
    var nome = fundo.querySelector('[data-app-nome]');
    if (nome && app) nome.textContent = 'O aplicativo ' + app;
    origem = gatilho; aberto = fundo; fundo.hidden = false;
    document.body.style.overflow = 'hidden';
    (fundo.querySelector('[data-foco-inicial]') || fundo.querySelector(focaveis)).focus();
  }
  function fechar() {
    if (!aberto) return;
    aberto.hidden = true; aberto = null;
    document.body.style.overflow = '';
    if (origem) origem.focus();
  }
  document.querySelectorAll('[data-abrir]').forEach(function (b) { b.addEventListener('click', function () { abrir(b); }); });
  document.querySelectorAll('[data-fechar]').forEach(function (b) { b.addEventListener('click', fechar); });
  document.querySelectorAll('[data-modal]').forEach(function (f) { f.addEventListener('mousedown', function (e) { if (e.target === f) fechar(); }); });
  document.addEventListener('keydown', function (e) {
    if (!aberto) return;
    if (e.key === 'Escape') { e.preventDefault(); fechar(); return; }
    if (e.key !== 'Tab') return;
    var itens = aberto.querySelectorAll(focaveis);
    var primeiro = itens[0], ultimo = itens[itens.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });
  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    document.querySelector('#form-prefs input').focus();
  });
})();
