<script>
(function(){
  var ajuda=document.getElementById('btn-ajuda'),gav=document.getElementById('gaveta'),ultimo=null;
  function gaveta(abrir){
    gav.classList.toggle('aberta',abrir);
    ajuda.setAttribute('aria-expanded',String(abrir));
    if(abrir){gav.querySelector('button,a').focus();}else{ajuda.focus();}
  }
  ajuda.addEventListener('click',function(){gaveta(!gav.classList.contains('aberta'));});
  window.abrirModal=function(id){
    var m=document.getElementById(id);
    ultimo=document.activeElement;
    m.hidden=false;
    var f=m.querySelector('input,button');
    if(f){f.focus();}
  };
  function fechar(m){m.hidden=true;if(ultimo){ultimo.focus();}}
  document.addEventListener('click',function(e){
    var b=e.target.closest('.banner .btn-txt');
    if(b){b.closest('.banner').remove();return;}
    if(e.target.closest('[data-fechar-gaveta]')){gaveta(false);return;}
    var x=e.target.closest('.modal-x,[data-fechar]');
    if(x){fechar(x.closest('.modal'));}
  });
  document.addEventListener('keydown',function(e){
    var m=document.querySelector('.modal:not([hidden])');
    if(e.key==='Escape'){
      if(m){fechar(m);}else if(gav.classList.contains('aberta')){gaveta(false);}
      return;
    }
    if(e.key==='Tab'&&m){
      var fs=m.querySelectorAll('input,button,a[href]');
      var p=fs[0],u=fs[fs.length-1];
      if(e.shiftKey&&document.activeElement===p){e.preventDefault();u.focus();}
      else if(!e.shiftKey&&document.activeElement===u){e.preventDefault();p.focus();}
    }
  });
  var form=document.getElementById('form-convite'),inp=document.getElementById('conv-email'),erro=document.getElementById('conv-erro');
  form.addEventListener('submit',function(e){
    var ok=inp.checkValidity();
    inp.setAttribute('aria-invalid',String(!ok));
    erro.hidden=ok;
    if(ok){inp.removeAttribute('aria-describedby');}
    else{e.preventDefault();inp.setAttribute('aria-describedby','conv-erro');inp.focus();}
  });
})();
</script>
</body>
