(function () {
  var aberto = null, gatilho = null;
  var seletor = 'button:not([disabled]),[href],input,select,textarea,[tabindex]:not([tabindex="-1"])';
  function abrir(fundo, origem) {
    gatilho = origem;
    aberto = fundo;
    fundo.hidden = false;
    document.body.classList.add('modal-aberto');
    var alvo = fundo.querySelector('[data-foco-inicial]') || fundo.querySelector(seletor);
    if (alvo) alvo.focus();
  }
  function fechar() {
    if (!aberto) return;
    aberto.hidden = true;
    aberto = null;
    document.body.classList.remove('modal-aberto');
    if (gatilho) gatilho.focus();
  }
  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var fundo = document.getElementById(b.getAttribute('data-abrir'));
      var app = b.getAttribute('data-app');
      if (app) {
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + app + '?';
      }
      abrir(fundo, b);
    });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) { b.addEventListener('click', fechar); });
  document.querySelectorAll('[data-modal]').forEach(function (f) {
    f.addEventListener('mousedown', function (e) { if (e.target === f) fechar(); });
  });
  document.addEventListener('keydown', function (e) {
    if (!aberto) return;
    if (e.key === 'Escape') { e.preventDefault(); fechar(); return; }
    if (e.key === 'Tab') {
      var itens = aberto.querySelectorAll(seletor);
      if (!itens.length) return;
      var primeiro = itens[0], ultimo = itens[itens.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    }
  });
  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    var h = document.getElementById('h-pref');
    h.setAttribute('tabindex', '-1');
    h.focus();
  });
})();
