(function () {
  var gatilho = null, aberto = null;
  var contagem = document.getElementById('contagem-acessos');
  contagem.setAttribute('tabindex', '-1');

  function abrir(m, g) {
    gatilho = g; aberto = m; m.hidden = false;
    document.body.style.overflow = 'hidden';
    m.querySelector('.btn:not(.perigo)').focus();
  }
  function fechar() {
    if (!aberto) return;
    aberto.hidden = true; aberto = null;
    document.body.style.overflow = '';
    if (gatilho && document.contains(gatilho)) gatilho.focus(); else contagem.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    var linha = b.closest('tr');
    var app = '', perm = '';
    if (linha) {
      app = linha.querySelector('th').textContent.trim();
      perm = linha.querySelector('.chip').textContent.trim();
      b.setAttribute('aria-label', 'Revogar acesso de ' + app);
    }
    b.addEventListener('click', function () {
      if (app) {
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + app + '?';
        document.getElementById('dlg-revogar-d').textContent = app + ' perderá imediatamente a permissão "' + perm + '". Os dados já sincronizados continuam no aplicativo. Você poderá autorizá-lo novamente depois.';
      }
      abrir(document.getElementById(b.getAttribute('data-abrir')), b);
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) { b.addEventListener('click', fechar); });
  document.querySelectorAll('[data-modal]').forEach(function (m) {
    m.addEventListener('click', function (e) { if (e.target === m) fechar(); });
  });
  document.addEventListener('keydown', function (e) {
    if (!aberto) return;
    if (e.key === 'Escape') { fechar(); return; }
    if (e.key === 'Tab') {
      var f = aberto.querySelectorAll('button'), p = f[0], u = f[f.length - 1];
      if (e.shiftKey && document.activeElement === p) { e.preventDefault(); u.focus(); }
      else if (!e.shiftKey && document.activeElement === u) { e.preventDefault(); p.focus(); }
    }
  });

  document.querySelectorAll('[aria-label="Sessões ativas"] button').forEach(function (b) {
    var l = b.closest('tr');
    b.setAttribute('aria-label', 'Encerrar sessão de ' + l.querySelector('th').textContent.trim() + ' em ' + l.children[2].textContent.trim());
  });

  document.querySelectorAll('.estado .ponto').forEach(function (p) {
    var t = p.getAttribute('aria-label');
    p.removeAttribute('aria-label');
    p.setAttribute('aria-hidden', 'true');
    p.insertAdjacentText('afterend', t);
  });
})();
