function buscarCep(){
  var s=$('cep-status'),i=$('ent-cep'),c=i.value.replace(/\D/g,'');
  if(c.length!==8){i.setAttribute('aria-invalid','true');s.textContent='CEP inválido. Digite os 8 números.';i.focus();return;}
