  fetch('https://viacep.com.br/ws/'+c+'/json/').then(function(r){if(!r.ok){throw new Error('http');}return r.json();}).then(function(d){
    if(d.erro){s.textContent='CEP não encontrado. Preencha o endereço manualmente.';return;}
    $('ent-rua').value=d.logradouro?d.logradouro+', ':'';$('ent-cidade').value=d.localidade;$('ent-uf').value=d.uf;
    s.textContent='Endereço localizado. Informe o número.';$('ent-rua').focus();atualizarRevisao();recalcular();
