@@ DEPOIS
(function () {
  var fundoAberto = null, gatilho = null;
  var fora = document.querySelectorAll('.pular,.topo,.layout,.rodape');

  function focaveis(raiz) {
    return Array.prototype.filter.call(
      raiz.querySelectorAll('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])'),
      function (e) { return !e.disabled; }
    );
  }
  function inerte(v) { fora.forEach(function (e) { e.inert = v; }); }

  function abrir(fundo, origem) {
    gatilho = origem; fundoAberto = fundo;
    inerte(true);
    fundo.hidden = false;
    document.body.style.overflow = 'hidden';
    (fundo.querySelector('.btn:not(.perigo)') || focaveis(fundo)[0]).focus();
  }
  function fechar() {
    if (!fundoAberto) return;
    fundoAberto.hidden = true; fundoAberto = null;
    inerte(false);
    document.body.style.overflow = '';
    if (gatilho) gatilho.focus();
  }

  // Nomes acessíveis distintos para botões repetidos nas tabelas
  document.querySelectorAll('tbody tr').forEach(function (tr) {
    var th = tr.querySelector('th'), b = tr.querySelector('button');
    if (th && b) b.setAttribute('aria-label', b.textContent.trim() + ': ' + th.textContent.trim());
  });

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var tr = b.closest('tr');
      if (tr && b.getAttribute('data-abrir') === 'fundo-revogar') {
        document.getElementById('dlg-revogar-t').textContent =
          'Revogar o acesso de ' + tr.querySelector('th').textContent.trim() + '?';
      }
      abrir(document.getElementById(b.getAttribute('data-abrir')), b);
    });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) { b.addEventListener('click', fechar); });

  document.addEventListener('keydown', function (e) {
    if (!fundoAberto) return;
    if (e.key === 'Escape') { e.preventDefault(); fechar(); return; }
    if (e.key === 'Tab') {
      var f = focaveis(fundoAberto), p = f[0], u = f[f.length - 1];
      if (e.shiftKey && document.activeElement === p) { e.preventDefault(); u.focus(); }
      else if (!e.shiftKey && document.activeElement === u) { e.preventDefault(); p.focus(); }
    }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    var h = document.getElementById('h-pref');
    h.setAttribute('tabindex', '-1');
    h.focus();
  });
})();
@@ FIM

