var ultimoGatilho = null;
function abrirModal(fundo, gatilho) {
  ultimoGatilho = gatilho;
  fundo.hidden = false;
  document.body.style.overflow = 'hidden';
  var botoes = fundo.querySelectorAll('button');
  (botoes[botoes.length - 1]).focus();
}
function fecharModal(fundo) {
  fundo.hidden = true;
  document.body.style.overflow = '';
  if (ultimoGatilho) { ultimoGatilho.focus(); }
}
document.querySelectorAll('[data-abrir]').forEach(function (b) { b.addEventListener('click', function () { abrirModal(document.getElementById(b.getAttribute('data-abrir')), b); }); });
document.querySelectorAll('[data-fechar]').forEach(function (b) { b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); }); });
document.addEventListener('keydown', function (e) {
  var aberto = document.querySelector('[data-modal]:not([hidden])');
  if (!aberto) { return; }
  if (e.key === 'Escape') { fecharModal(aberto); return; }
  if (e.key === 'Tab') {
    var foco = aberto.querySelectorAll('button, [href], input, select, textarea');
    var primeiro = foco[0], ultimo = foco[foco.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  }
});
@@ FIM

