var tituloBase = 'Configurações da conta - Mercado Bom Preço';
var resumo = document.getElementById('resumo-erros');
function definirErro(id, msg) {
  var campo = document.getElementById(id);
  var p = document.getElementById('erro-' + id);
  var caixa = campo.closest('.campo');
  p.textContent = '';
  if (msg) {
    var pre = document.createElement('span');
    pre.className = 'sr-only';
    pre.textContent = 'Erro: ';
    p.appendChild(pre);
    p.appendChild(document.createTextNode(msg));
  }
  p.hidden = !msg;
  caixa.classList.toggle('campo-erro', !!msg);
  campo.setAttribute('aria-invalid', msg ? 'true' : 'false');
  var marca = caixa.querySelector('.marca-erro');
  if (marca) { marca.hidden = !msg; }
}
document.getElementById('form-perfil').addEventListener('submit', function (e) {
  var nome = document.getElementById('nome').value.trim();
  var email = document.getElementById('email').value.trim();
  var tel = document.getElementById('telefone').value;
  var digitos = tel.replace(/\D/g, '');
  var msgs = {
    nome: nome ? '' : 'Informe seu nome completo.',
    email: !email ? 'Informe seu e-mail corporativo, como nome@empresa.com.br.' : (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ? '' : 'O e-mail está incompleto. Use o formato nome@empresa.com.br.'),
    telefone: (tel.trim() && (digitos.length < 10 || digitos.length > 11)) ? 'O telefone está incompleto. Informe DDD e número, como (11) 91234-5678.' : ''
  };
  var rotulos = { nome: 'Nome completo', email: 'E-mail corporativo', telefone: 'Telefone celular' };
  var lista = document.getElementById('lista-erros');
  var n = 0;
  lista.textContent = '';
  ['nome', 'email', 'telefone'].forEach(function (id) {
    definirErro(id, msgs[id]);
    if (msgs[id]) {
      n++;
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + id;
      a.textContent = rotulos[id] + ': ' + msgs[id];
      li.appendChild(a);
      lista.appendChild(li);
    }
  });
  resumo.hidden = n === 0;
  document.title = (n ? 'Erro: ' : '') + tituloBase;
  if (n) {
    e.preventDefault();
    document.getElementById('resumo-t').textContent = 'Corrija ' + n + (n === 1 ? ' campo' : ' campos') + ' para salvar';
    resumo.focus();
  }
});
@@ FIM

