<script>
(function(){
  var ultimo=null;
  var botaoAjuda=document.querySelector('[aria-controls="gaveta"]');
  var gaveta=document.getElementById('gaveta');
  function focaveis(m){
    return Array.prototype.slice.call(m.querySelectorAll('a[href],button:not([disabled]),input,select,textarea')).filter(function(e){return e.offsetParent!==null;});
  }
  function abrir(m,origem){
    ultimo=origem||document.activeElement;
    m.hidden=false;
    document.body.style.overflow='hidden';
    var f=m.querySelector('[data-foco-inicial]')||focaveis(m)[0];
    if(f)f.focus();
  }
  function fechar(m){
    m.hidden=true;
    document.body.style.overflow='';
    if(ultimo)ultimo.focus();
  }
  function fecharGaveta(){
    gaveta.classList.remove('aberta');
    botaoAjuda.setAttribute('aria-expanded','false');
  }
  botaoAjuda.addEventListener('click',function(){
    var abrindo=!gaveta.classList.contains('aberta');
    gaveta.classList.toggle('aberta',abrindo);
    botaoAjuda.setAttribute('aria-expanded',String(abrindo));
    if(abrindo)gaveta.querySelector('h2').focus();
  });
  document.addEventListener('click',function(e){
    var a=e.target.closest('[data-abrir]');
    if(a){abrir(document.getElementById(a.getAttribute('data-abrir')),a);return;}
    var c=e.target.closest('[data-fechar]');
    if(c){fechar(c.closest('.modal'));return;}
    var d=e.target.closest('[data-dispensar]');
    if(d){d.closest('.banner').remove();document.getElementById('conteudo').focus();}
  });
  document.addEventListener('keydown',function(e){
    var m=document.querySelector('.modal:not([hidden])');
    if(e.key==='Escape'){
      if(m){fechar(m);}
      else if(gaveta.classList.contains('aberta')){fecharGaveta();botaoAjuda.focus();}
      return;
    }
    if(e.key==='Tab'&&m){
      var f=focaveis(m);
      if(!f.length)return;
      var p=f[0],u=f[f.length-1];
      if(e.shiftKey&&document.activeElement===p){e.preventDefault();u.focus();}
      else if(!e.shiftKey&&document.activeElement===u){e.preventDefault();p.focus();}
    }
  });
  var form=document.querySelector('#m0 form');
  var campo=document.getElementById('conv-email');
  var erro=document.getElementById('conv-erro');
  form.addEventListener('submit',function(e){
    if(!campo.checkValidity()){
      e.preventDefault();
      erro.hidden=false;
      campo.setAttribute('aria-invalid','true');
      campo.setAttribute('aria-describedby','conv-erro');
      campo.focus();
    }else{
      erro.hidden=true;
      campo.setAttribute('aria-invalid','false');
      campo.removeAttribute('aria-describedby');
    }
  });
})();
</script>
</body>
