  var n = 0;
  btnsRev.forEach(function (b) { if (!b.closest('tr').classList.contains('revogado')) n++; });
  cont.textContent = n + (n === 1 ? ' aplicativo com acesso à sua conta' : ' aplicativos com acesso à sua conta');
}
btnsRev.forEach(function (b) {
  var tr = b.closest('tr'), app = tr.querySelector('th').textContent.trim();
