  var ponto = tr.querySelector('.ponto'), cls = ponto.className;
  b.setAttribute('aria-label', 'Revogar acesso de ' + app);
  b.addEventListener('click', function () {
    var rev = tr.classList.toggle('revogado');
    b.textContent = rev ? 'Desfazer' : 'Revogar acesso';
    b.classList.toggle('perigo-suave', !rev);
    b.setAttribute('aria-label', (rev ? 'Desfazer revogação de ' : 'Revogar acesso de ') + app);
    txt.textContent = rev ? 'Revogado' : orig;
    ponto.className = rev ? 'ponto exp' : cls;
    contar();
    anunciar(rev ? 'Acesso de ' + app + ' revogado. Use Desfazer para restaurar.' : 'Acesso de ' + app + ' restaurado.');
  });
});

// Encerrar sessão: nome acessível único e feedback
document.querySelectorAll('#acessos tbody button:not([aria-label])').forEach(function (b) {
