<script>
(function(){
  var gatilho=null;
  function abrir(m,g){
    gatilho=g;m.hidden=false;document.body.style.overflow='hidden';
    (m.querySelector('input')||m.querySelector('button')).focus();
  }
  function fechar(m){
    m.hidden=true;document.body.style.overflow='';
    if(gatilho&&document.contains(gatilho))gatilho.focus();
  }
  document.querySelectorAll('[aria-haspopup="dialog"]').forEach(function(b){
    b.addEventListener('click',function(){abrir(document.getElementById(b.getAttribute('aria-controls')),b);});
  });
  document.querySelectorAll('.modal').forEach(function(m){
    m.querySelectorAll('[data-fechar],.modal-x').forEach(function(b){
      b.addEventListener('click',function(){fechar(m);});
    });
    m.addEventListener('keydown',function(e){
      if(e.key==='Escape'){fechar(m);return;}
      if(e.key!=='Tab')return;
      var f=m.querySelectorAll('button,input,a[href]'),p=f[0],u=f[f.length-1];
      if(e.shiftKey&&document.activeElement===p){e.preventDefault();u.focus();}
      else if(!e.shiftKey&&document.activeElement===u){e.preventDefault();p.focus();}
    });
  });
  var form=document.getElementById('form-convite'),
      campo=document.getElementById('conv-email'),
      erro=document.getElementById('conv-erro');
  form.addEventListener('submit',function(e){
    e.preventDefault();
    if(!campo.checkValidity()){
      erro.hidden=false;campo.setAttribute('aria-invalid','true');campo.focus();return;
    }
    erro.hidden=true;campo.removeAttribute('aria-invalid');
    fechar(document.getElementById('m0'));
  });
  campo.addEventListener('input',function(){
    if(campo.checkValidity()){erro.hidden=true;campo.removeAttribute('aria-invalid');}
  });
  var bt=document.querySelector('[aria-controls="gaveta"]'),g=document.getElementById('gaveta');
  bt.addEventListener('click',function(){
    bt.setAttribute('aria-expanded',String(g.classList.toggle('aberta')));
  });
  g.addEventListener('keydown',function(e){
    if(e.key==='Escape'){g.classList.remove('aberta');bt.setAttribute('aria-expanded','false');bt.focus();}
  });
  var disp=document.querySelector('.banner .btn-txt');
  disp.addEventListener('click',function(){
    disp.closest('.banner').remove();
    document.getElementById('conteudo').focus();
  });
})();
</script>
