<script>
(function(){
  var gatilho=null;
  var gaveta=document.getElementById('gaveta');
  var btnAjuda=document.querySelector('[aria-controls="gaveta"]');
  function alternarGaveta(abrir){
    gaveta.hidden=!abrir;
    btnAjuda.setAttribute('aria-expanded',String(abrir));
    if(abrir){gaveta.querySelector('a').focus()}else{btnAjuda.focus()}
  }
  btnAjuda.addEventListener('click',function(){alternarGaveta(gaveta.hidden)});
  gaveta.querySelector('[data-fechar-gaveta]').addEventListener('click',function(){alternarGaveta(false)});
  document.addEventListener('keydown',function(e){
    if(e.key==='Escape'&&!gaveta.hidden){alternarGaveta(false)}
  });
  function abrir(m,origem){
    gatilho=origem;
    m.hidden=false;
    (m.querySelector('input')||m.querySelector('[data-fechar]')||m.querySelector('button')).focus();
  }
  function fechar(m){
    m.hidden=true;
    if(gatilho){gatilho.focus()}
  }
  document.querySelectorAll('[aria-haspopup="dialog"]').forEach(function(b){
    b.addEventListener('click',function(){abrir(document.getElementById(b.getAttribute('aria-controls')),b)});
  });
  document.querySelectorAll('.modal').forEach(function(m){
    m.querySelectorAll('.modal-x,[data-fechar]').forEach(function(b){
      b.addEventListener('click',function(){fechar(m)});
    });
    m.addEventListener('keydown',function(e){
      if(e.key==='Escape'){fechar(m);return}
      if(e.key!=='Tab')return;
      var f=m.querySelectorAll('input,button,a[href]');
      var p=f[0],u=f[f.length-1];
      if(e.shiftKey&&document.activeElement===p){e.preventDefault();u.focus()}
      else if(!e.shiftKey&&document.activeElement===u){e.preventDefault();p.focus()}
    });
  });
  var form=document.getElementById('form-convite');
  form.addEventListener('submit',function(e){
    var i=form.elements.email,er=document.getElementById('conv-erro');
    if(!i.checkValidity()){
      e.preventDefault();
      i.setAttribute('aria-invalid','true');
      er.hidden=false;
      i.focus();
    }else{
      i.removeAttribute('aria-invalid');
      er.hidden=true;
    }
  });
  document.querySelectorAll('[data-dispensar]').forEach(function(b){
    b.addEventListener('click',function(){b.closest('.banner').remove()});
  });
})();
</script>
</body>
@@ FIM

