(function () {
  var live = document.getElementById('live');
  var gatilho = null;

  function abrir(b) {
    var m = document.getElementById(b.getAttribute('data-abrir'));
    var app = b.getAttribute('data-app');
    if (app) m.querySelectorAll('[data-app-nome]').forEach(function (s) { s.textContent = app; });
    gatilho = b;
    m.hidden = false;
    document.body.style.overflow = 'hidden';
    (m.querySelector('[data-foco]') || m.querySelector('button')).focus();
  }
  function fechar(m) {
    m.hidden = true;
    document.body.style.overflow = '';
    if (gatilho && document.contains(gatilho)) gatilho.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b); });
  });
  document.querySelectorAll('[data-modal]').forEach(function (m) {
    m.addEventListener('click', function (e) { if (e.target === m) fechar(m); });
    m.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { fechar(m); return; }
      if (e.key !== 'Tab') return;
      var bs = m.querySelectorAll('button');
      var primeiro = bs[0], ultimo = bs[bs.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () {
      var acao = b.getAttribute('data-confirmar');
      if (acao) document.dispatchEvent(new CustomEvent('confirmar-acao', { detail: { acao: acao, alvo: gatilho } }));
      fechar(b.closest('[data-modal]'));
    });
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });

  var baseTitulo = 'Configurações da conta - Colégio Novo Saber';
  var resumo = document.getElementById('resumo-erros');
  var lista = document.getElementById('resumo-lista');
  var regras = {
    email: {
      ok: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v); },
      resumo: 'E-mail corporativo: inclua o domínio completo, como nome@empresa.com.br'
    },
    telefone: {
      ok: function (v) { var d = v.replace(/\D/g, ''); return d.length === 10 || d.length === 11; },
      resumo: 'Telefone celular: informe DDD e número completo, como (11) 91234-5678'
    }
  };

  function validar() {
    var erros = [];
    Object.keys(regras).forEach(function (id) {
      var inp = document.getElementById(id);
      var ruim = !regras[id].ok(inp.value.trim());
      inp.closest('.campo').classList.toggle('campo-erro', ruim);
      document.getElementById('erro-' + id).hidden = !ruim;
      inp.setAttribute('aria-invalid', ruim ? 'true' : 'false');
      inp.setAttribute('aria-describedby', 'dica-' + id + (ruim ? ' erro-' + id : ''));
      if (ruim) erros.push({ id: id, msg: regras[id].resumo });
    });
    lista.innerHTML = '';
    erros.forEach(function (e) {
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + e.id;
      a.textContent = e.msg;
      li.appendChild(a);
      lista.appendChild(li);
    });
    resumo.hidden = erros.length === 0;
    document.title = (erros.length ? 'Erro: ' : '') + baseTitulo;
    return erros;
  }

  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    var erros = validar();
    if (erros.length) {
      e.preventDefault();
      resumo.focus();
      return;
    }
    var btn = this.querySelector('button[type="submit"]');
    btn.disabled = true;
    btn.textContent = 'Salvando…';
    live.textContent = 'Salvando alterações…';
  });

  document.getElementById('form-prefs').addEventListener('submit', function () {
    var btn = this.querySelector('button[type="submit"]');
    btn.disabled = true;
    btn.textContent = 'Salvando…';
    live.textContent = 'Salvando preferências…';
  });
})();
