<script>
(function(){
  var ultimo=null;
  function abrir(m){
    ultimo=document.activeElement;
    m.hidden=false;
    document.body.style.overflow='hidden';
    (m.querySelector('input')||m.querySelector('.btn-prim,.btn-perigo')||m.querySelector('button')).focus();
  }
  function fechar(m){
    m.hidden=true;
    document.body.style.overflow='';
    if(ultimo){ultimo.focus();}
  }
  function fecharGaveta(){
    var g=document.getElementById('gaveta');
    var h=document.querySelector('[aria-controls="gaveta"]');
    g.hidden=true;
    h.setAttribute('aria-expanded','false');
    h.focus();
  }
  document.addEventListener('click',function(e){
    var a=e.target.closest('[data-abrir]');
    if(a){abrir(document.getElementById(a.dataset.abrir));return;}
    var m=e.target.closest('.modal');
    if(m&&(e.target===m||e.target.closest('.modal-x')||e.target.closest('.modal-acoes .btn:not(.btn-prim):not(.btn-perigo)'))){fechar(m);return;}
    var b=e.target.closest('.banner .btn-txt');
    if(b){b.closest('.banner').remove();return;}
    var h=e.target.closest('[aria-controls="gaveta"]');
    if(h){
      var g=document.getElementById('gaveta');
      var abrindo=g.hidden;
      g.hidden=!abrindo;
      h.setAttribute('aria-expanded',String(abrindo));
    }
  });
  document.addEventListener('keydown',function(e){
    var m=document.querySelector('.modal:not([hidden])');
    if(e.key==='Escape'){
      if(m){fechar(m);return;}
      if(!document.getElementById('gaveta').hidden){fecharGaveta();}
      return;
    }
    if(e.key==='Tab'&&m){
      var f=m.querySelectorAll('button,input,a[href]');
      var p=f[0],u=f[f.length-1];
      if(e.shiftKey&&document.activeElement===p){e.preventDefault();u.focus();}
      else if(!e.shiftKey&&document.activeElement===u){e.preventDefault();p.focus();}
    }
  });
})();
</script>
</body>
