var modalAberto = null, gatilhoModal = null;
var FOCAVEIS = 'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
function abrirModal(id, gatilho) {
  modalAberto = document.getElementById(id);
  gatilhoModal = gatilho;
  modalAberto.hidden = false;
  document.body.style.overflow = 'hidden';
  modalAberto.querySelector('[data-fechar]').focus();
}
function fecharModal() {
  if (!modalAberto) return;
  modalAberto.hidden = true;
  modalAberto = null;
  document.body.style.overflow = '';
  if (gatilhoModal && document.contains(gatilhoModal)) gatilhoModal.focus();
}
document.addEventListener('keydown', function (e) {
  if (!modalAberto) return;
  if (e.key === 'Escape') { e.preventDefault(); fecharModal(); return; }
  if (e.key === 'Tab') {
    var f = modalAberto.querySelectorAll(FOCAVEIS);
    var primeiro = f[0], ultimo = f[f.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  }
});
document.querySelectorAll('[data-modal]').forEach(function (fundo) {
  fundo.addEventListener('mousedown', function (e) { if (e.target === fundo) fecharModal(); });
});
document.querySelectorAll('[data-abrir]').forEach(function (b) {
  var linha = b.closest('tr');
  var nome = linha ? linha.querySelector('th').textContent.trim() : '';
  if (nome) b.setAttribute('aria-label', 'Revogar acesso de ' + nome);
  b.addEventListener('click', function () {
    if (nome) document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + nome + '?';
    abrirModal(b.getAttribute('data-abrir'), b);
  });
});
document.querySelectorAll('#acessos tbody button:not([data-abrir])').forEach(function (b) {
  b.setAttribute('aria-label', b.textContent.trim() + ': ' + b.closest('tr').querySelector('th').textContent.trim());
});
document.querySelectorAll('.estado .ponto').forEach(function (p) {
  var t = p.getAttribute('aria-label');
  p.removeAttribute('role');
  p.removeAttribute('aria-label');
  p.setAttribute('aria-hidden', 'true');
  p.parentNode.appendChild(document.createTextNode(t));
});
document.querySelectorAll('#acessos table').forEach(function (t) {
  var w = document.createElement('div');
  w.className = 'tabela-rolagem';
  w.tabIndex = 0;
  w.setAttribute('role', 'region');
  w.setAttribute('aria-label', t.querySelector('caption').textContent);
  t.parentNode.insertBefore(w, t);
  w.appendChild(t);
});
