(function () {
  var ultimoGatilho = null;
  var live = document.getElementById('live');
  function focaveis(m) {
    return Array.prototype.slice.call(m.querySelectorAll('a[href],button:not([disabled]),input,select,textarea,[tabindex]:not([tabindex="-1"])'));
  }
  function abrir(gatilho) {
    var fundo = document.getElementById(gatilho.getAttribute('data-abrir'));
    var app = gatilho.getAttribute('data-app');
    var nome = fundo.querySelector('[data-app-nome]');
    if (nome && app) nome.textContent = app;
    ultimoGatilho = gatilho;
    fundo.hidden = false;
    document.body.style.overflow = 'hidden';
    (fundo.querySelector('[data-foco]') || fundo.querySelector('button')).focus();
  }
  function fechar(fundo) {
    fundo.hidden = true;
    document.body.style.overflow = '';
    if (ultimoGatilho) ultimoGatilho.focus();
  }
  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });
  document.querySelectorAll('[data-modal]').forEach(function (fundo) {
    fundo.addEventListener('mousedown', function (e) { if (e.target === fundo) fechar(fundo); });
  });
  document.addEventListener('keydown', function (e) {
    var aberto = document.querySelector('[data-modal]:not([hidden])');
    if (!aberto) return;
    if (e.key === 'Escape') { e.preventDefault(); fechar(aberto); return; }
    if (e.key === 'Tab') {
      var f = focaveis(aberto), p = f[0], u = f[f.length - 1];
      if (e.shiftKey && document.activeElement === p) { e.preventDefault(); u.focus(); }
      else if (!e.shiftKey && document.activeElement === u) { e.preventDefault(); p.focus(); }
    }
  });

  var form = document.getElementById('form-perfil');
  var resumo = document.getElementById('resumo-erros');
  var lista = document.getElementById('lista-erros');
  var titulo = document.getElementById('titulo-resumo');
  var rotulos = { email: 'E-mail corporativo', telefone: 'Telefone celular' };
  var regras = {
    email: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v); },
    telefone: function (v) { var d = v.replace(/\D/g, ''); return d.length === 10 || d.length === 11; }
  };
  function validar() {
    var erros = [];
    Object.keys(regras).forEach(function (id) {
      var campo = document.getElementById(id);
      var msg = document.getElementById('erro-' + id);
      var ruim = !regras[id](campo.value.trim());
      campo.setAttribute('aria-invalid', ruim ? 'true' : 'false');
      campo.setAttribute('aria-describedby', ruim ? 'dica-' + id + ' erro-' + id : 'dica-' + id);
      campo.closest('.campo').classList.toggle('campo-erro', ruim);
      msg.hidden = !ruim;
      if (ruim) erros.push(id);
    });
    lista.innerHTML = '';
    erros.forEach(function (id) {
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + id;
      a.textContent = rotulos[id] + ': ' + document.getElementById('erro-' + id).textContent;
      li.appendChild(a);
      lista.appendChild(li);
    });
    titulo.textContent = erros.length === 1 ? 'Corrija 1 campo antes de salvar' : 'Corrija ' + erros.length + ' campos antes de salvar';
    resumo.hidden = erros.length === 0;
    return erros;
  }
  lista.addEventListener('click', function (e) {
    var a = e.target.closest('a');
    if (!a) return;
    e.preventDefault();
    document.getElementById(a.getAttribute('href').slice(1)).focus();
  });
  form.addEventListener('submit', function (e) {
    var erros = validar();
    if (erros.length) {
      e.preventDefault();
      live.textContent = titulo.textContent;
      resumo.focus();
    }
  });
  form.addEventListener('input', function () { if (!resumo.hidden) validar(); });
})();
