var linhasApps = document.querySelector('#acessos table').tBodies[0].rows;
function atualizarContagem() {
  var n = 0;
  for (var i = 0; i < linhasApps.length; i++) if (!linhasApps[i].hidden) n++;
  contagem.textContent = n === 0 ? 'Nenhum aplicativo com acesso à sua conta' : n === 1 ? '1 aplicativo com acesso à sua conta' : n + ' aplicativos com acesso à sua conta';
