/* Validação do perfil: só ao enviar */
var form = document.getElementById('form-perfil');
var resumo = document.getElementById('resumo-erros');
var campos = [
  { id: 'nome', ok: function (v) { return v.trim().length > 0; }, msg: 'Informe seu nome completo.' },
  { id: 'email', ok: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()); }, msg: 'Informe um e-mail válido, como nome@empresa.com.br.' },
  { id: 'telefone', ok: function (v) { var n = v.replace(/\D/g, '').length; return n === 10 || n === 11; }, msg: 'Informe o telefone com DDD, por exemplo (11) 91234-5678.' }
];
function descrever(i, ids) {
  ids = ids.filter(function (x) { return document.getElementById(x); });
  if (ids.length) i.setAttribute('aria-describedby', ids.join(' ')); else i.removeAttribute('aria-describedby');
}
function limparErros() {
  campos.forEach(function (c) {
    var i = document.getElementById(c.id), e = document.getElementById('erro-' + c.id);
    i.removeAttribute('aria-invalid');
    i.closest('.campo').classList.remove('campo-erro');
    e.hidden = true;
    e.textContent = '';
    descrever(i, ['dica-' + c.id]);
  });
}
form.addEventListener('submit', function (ev) {
  limparErros();
  var erros = [];
  campos.forEach(function (c) {
    var i = document.getElementById(c.id);
    if (!c.ok(i.value)) erros.push({ c: c, i: i });
  });
  if (!erros.length) { resumo.hidden = true; return; }
  ev.preventDefault();
  var lista = document.getElementById('resumo-lista');
  lista.innerHTML = '';
  erros.forEach(function (x) {
    var rotulo = document.querySelector('label[for="' + x.c.id + '"]').textContent;
    x.i.setAttribute('aria-invalid', 'true');
    x.i.closest('.campo').classList.add('campo-erro');
    var e = document.getElementById('erro-' + x.c.id);
    e.textContent = x.c.msg;
    e.hidden = false;
    descrever(x.i, ['dica-' + x.c.id, 'erro-' + x.c.id]);
    var li = document.createElement('li'), a = document.createElement('a');
    a.href = '#' + x.c.id;
    a.textContent = rotulo + ': ' + x.c.msg;
    li.appendChild(a);
    lista.appendChild(li);
  });
  document.getElementById('banner-sucesso').hidden = true;
  resumo.hidden = false;
  document.getElementById('resumo-msg').textContent = erros.length === 1 ? 'Corrija 1 campo para salvar' : 'Corrija ' + erros.length + ' campos para salvar';
  resumo.scrollIntoView({ block: 'nearest' });
  erros[0].i.focus({ preventScroll: true });
});
form.addEventListener('reset', function () { limparErros(); resumo.hidden = true; });
@@ FIM

