(function () {
  var live = document.getElementById('live');
  var FOCAVEIS = 'a[href],button:not([disabled]),input:not([disabled]),select,textarea,[tabindex]:not([tabindex="-1"])';
  var atual = null, origem = null;

  function fundoInerte(valor) {
    document.querySelectorAll('body > :not([data-modal]):not(#live):not(script)').forEach(function (el) { el.inert = valor; });
  }
  function abrir(id, gatilho) {
    atual = document.getElementById(id);
    origem = gatilho;
    if (id === 'fundo-revogar') {
      var app = gatilho.getAttribute('data-app') || 'este aplicativo';
      document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + app + '?';
    }
    fundoInerte(true);
    document.body.style.overflow = 'hidden';
    atual.hidden = false;
    (atual.querySelector('[data-foco-inicial]') || atual.querySelector(FOCAVEIS)).focus();
  }
  function fechar(devolverFoco) {
    if (!atual) return;
    atual.hidden = true;
    fundoInerte(false);
    document.body.style.overflow = '';
    var alvo = origem;
    atual = null; origem = null;
    if (devolverFoco !== false && alvo && document.contains(alvo)) alvo.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir'), b); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(); });
  });
  document.querySelectorAll('[data-modal]').forEach(function (m) {
    m.addEventListener('mousedown', function (e) { if (e.target === m) fechar(); });
  });

  document.querySelectorAll('[data-confirmar]').forEach(function (b) {
    b.addEventListener('click', function () {
      var modal = b.closest('[data-modal]');
      if (modal.id === 'fundo-revogar' && origem) {
        var linha = origem.closest('tr');
        var app = origem.getAttribute('data-app');
        var corpo = linha.parentNode;
        // TODO: chamar a API de revogação antes de atualizar a interface
        linha.remove();
        var n = corpo.rows.length;
        var c = document.getElementById('contagem-acessos');
        c.textContent = n === 0 ? 'Nenhum aplicativo com acesso à sua conta'
          : n === 1 ? '1 aplicativo com acesso à sua conta'
          : n + ' aplicativos com acesso à sua conta';
        c.setAttribute('tabindex', '-1');
        fechar(false);
        c.focus();
        live.textContent = 'Acesso de ' + app + ' revogado.';
      } else {
        // TODO: integrar a exclusão de conta; o evento permite ligar o backend
        modal.dispatchEvent(new CustomEvent('confirmar', { bubbles: true }));
        fechar();
      }
    });
  });

  document.addEventListener('keydown', function (e) {
    if (!atual) return;
    if (e.key === 'Escape') { e.preventDefault(); fechar(); return; }
    if (e.key !== 'Tab') return;
    var itens = atual.querySelectorAll(FOCAVEIS);
    var primeiro = itens[0], ultimo = itens[itens.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    var h = document.getElementById('h-pref');
    h.setAttribute('tabindex', '-1');
    h.focus();
  });
})();
@@ FIM

