<script>
(function () {
  var gatilho = null;
  var FOCAVEIS = 'a[href],button:not([disabled]),input:not([disabled]),select,textarea,[tabindex]:not([tabindex="-1"])';

  function abrirModal(m, origem) {
    gatilho = origem || document.activeElement;
    m.hidden = false;
    document.body.style.overflow = 'hidden';
    var f = m.querySelector('input,.btn-prim,button');
    if (f) f.focus();
  }
  function fecharModal(m) {
    m.hidden = true;
    document.body.style.overflow = '';
    if (gatilho && gatilho.focus) gatilho.focus();
  }

  document.querySelectorAll('.modal').forEach(function (m) {
    m.addEventListener('click', function (e) {
      if (e.target === m || e.target.closest('.modal-x,[data-fechar]')) fecharModal(m);
    });
    m.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { fecharModal(m); return; }
      if (e.key !== 'Tab') return;
      var itens = m.querySelectorAll(FOCAVEIS);
      if (!itens.length) return;
      var ini = itens[0], fim = itens[itens.length - 1];
      if (e.shiftKey && document.activeElement === ini) { e.preventDefault(); fim.focus(); }
      else if (!e.shiftKey && document.activeElement === fim) { e.preventDefault(); ini.focus(); }
    });
  });

  document.querySelectorAll('[aria-haspopup="dialog"]').forEach(function (b) {
    b.addEventListener('click', function () {
      var m = document.getElementById(b.getAttribute('aria-controls'));
      if (m) abrirModal(m, b);
    });
  });

  var gaveta = document.getElementById('gaveta');
  var abrirAjuda = document.querySelector('[aria-controls="gaveta"]');
  function alternarGaveta(abrir) {
    gaveta.hidden = !abrir;
    abrirAjuda.setAttribute('aria-expanded', String(abrir));
    if (abrir) gaveta.querySelector('a,button').focus(); else abrirAjuda.focus();
  }
  abrirAjuda.addEventListener('click', function () { alternarGaveta(gaveta.hidden); });
  gaveta.querySelector('[data-fechar-gaveta]').addEventListener('click', function () { alternarGaveta(false); });
  gaveta.addEventListener('keydown', function (e) { if (e.key === 'Escape') alternarGaveta(false); });

  var email = document.getElementById('conv-email');
  var erro = document.getElementById('conv-erro');
  email.addEventListener('invalid', function () {
    erro.hidden = false;
    email.setAttribute('aria-invalid', 'true');
    email.setAttribute('aria-describedby', 'conv-erro');
  });
  email.addEventListener('input', function () {
    erro.hidden = true;
    email.removeAttribute('aria-invalid');
    email.removeAttribute('aria-describedby');
  });
})();
</script>
</body>
