<script>
(function(){
  var gav=document.getElementById('gaveta'),
      btnAjuda=document.querySelector('[aria-controls="gaveta"]'),
      ultimo=null;
  function gaveta(abrir){
    gav.classList.toggle('aberta',abrir);
    btnAjuda.setAttribute('aria-expanded',String(abrir));
    (abrir?gav.querySelector('button'):btnAjuda).focus();
  }
  function abrirModal(m){
    ultimo=document.activeElement;
    m.hidden=false;
    document.body.style.overflow='hidden';
    (m.querySelector('input')||m.querySelector('button')).focus();
  }
  function fecharModal(m){
    m.hidden=true;
    document.body.style.overflow='';
    if(ultimo)ultimo.focus();
  }
  btnAjuda.addEventListener('click',function(){gaveta(!gav.classList.contains('aberta'))});
  gav.querySelector('.gaveta-x').addEventListener('click',function(){gaveta(false)});
  document.addEventListener('click',function(e){
    var a=e.target.closest('[data-abre]');
    if(a){e.preventDefault();abrirModal(document.getElementById(a.dataset.abre));return}
    var f=e.target.closest('[data-fechar],.modal-x');
    if(f){fecharModal(f.closest('.modal'));return}
    var d=e.target.closest('.banner .btn-txt');
    if(d)d.closest('.banner').hidden=true;
  });
  document.addEventListener('keydown',function(e){
    var m=document.querySelector('.modal:not([hidden])');
    if(e.key==='Escape'){
      if(m)fecharModal(m);else if(gav.classList.contains('aberta'))gaveta(false);
      return;
    }
    if(e.key==='Tab'&&m){
      var f=m.querySelectorAll('a[href],button:not([disabled]),input:not([disabled])'),
          p=f[0],u=f[f.length-1];
      if(e.shiftKey&&document.activeElement===p){e.preventDefault();u.focus()}
      else if(!e.shiftKey&&document.activeElement===u){e.preventDefault();p.focus()}
    }
  });
  var form=document.getElementById('f-conv'),
      email=document.getElementById('conv-email'),
      erro=document.getElementById('conv-erro');
  form.addEventListener('submit',function(e){
    if(!email.checkValidity()){
      e.preventDefault();
      email.setAttribute('aria-invalid','true');
      erro.hidden=false;
      email.focus();
    }
  });
  email.addEventListener('input',function(){
    if(email.checkValidity()){email.removeAttribute('aria-invalid');erro.hidden=true}
  });
})();
</script>
</body>
