var ultimoFoco=null;
function abrirDialogo(n){
  var v=document.getElementById('veu');var p=document.getElementById('dlg-p');
  ultimoFoco=document.activeElement;
  var tr=ultimoFoco&&ultimoFoco.closest?ultimoFoco.closest('tr'):null;
  var c=tr?tr.querySelector('.col-nome'):null;
  if(c){n=c.textContent.trim();}
  if(p){p.textContent=n+' será removido do pedido.';}
  if(v){v.hidden=false;var b=v.querySelector('button');if(b){b.focus();}}
}
function fecharDialogo(){
  var v=document.getElementById('veu');
  if(v){v.hidden=true;}
  if(ultimoFoco&&ultimoFoco.focus){ultimoFoco.focus();}
}
document.addEventListener('keydown',function(e){
  var v=document.getElementById('veu');
  if(!v||v.hidden){return;}
  if(e.key==='Escape'){e.preventDefault();fecharDialogo();return;}
  if(e.key==='Tab'){
    var bs=v.querySelectorAll('button');var p=bs[0],u=bs[bs.length-1];
    if(e.shiftKey&&document.activeElement===p){e.preventDefault();u.focus();}
    else if(!e.shiftKey&&document.activeElement===u){e.preventDefault();p.focus();}
    else if(!v.contains(document.activeElement)){e.preventDefault();p.focus();}
  }
});
function definirAtivo(el,ativo){
  if(!el){return;}
  el.hidden=!ativo;
  var cs=el.querySelectorAll('input,select,textarea');
  for(var i=0;i<cs.length;i++){cs[i].disabled=!ativo;}
}
function alternarCobranca(c){definirAtivo(document.getElementById('bloco-cobranca'),!c.checked);}
function alternarMetodo(){
  var f=document.getElementById('form-checkout');
  var cartao=f.elements['metodo'].value==='cartao';
  definirAtivo(document.getElementById('cartao'),cartao);
  var o=document.getElementById('otp');
  definirAtivo(o?o.closest('.bloco'):null,cartao);
}
alternarCobranca(document.querySelector('[name=cobranca_igual]'));
alternarMetodo();
