<script>
(function(){
  var tabs=[].slice.call(document.querySelectorAll('[role=tab]'));
  function sel(t,foco){
    tabs.forEach(function(x){
      var on=x===t;
      x.setAttribute('aria-selected',on?'true':'false');
      x.tabIndex=on?0:-1;
      x.classList.toggle('aba-ativa',on);
      document.getElementById(x.getAttribute('aria-controls')).hidden=!on;
    });
    if(foco)t.focus();
  }
  tabs.forEach(function(t,i){
    t.addEventListener('click',function(){sel(t);});
    t.addEventListener('keydown',function(e){
      var n;
      if(e.key==='ArrowRight')n=tabs[(i+1)%tabs.length];
      else if(e.key==='ArrowLeft')n=tabs[(i-1+tabs.length)%tabs.length];
      else if(e.key==='Home')n=tabs[0];
      else if(e.key==='End')n=tabs[tabs.length-1];
      if(n){e.preventDefault();sel(n,true);}
    });
  });
  var chk=document.querySelector('input[name="mesmo"]');
  var fs=chk.closest('label').nextElementSibling;
  chk.addEventListener('change',function(){fs.disabled=chk.checked;});
  var resumo=document.getElementById('resumo-erros');
  if(resumo)resumo.focus();
})();
</script>
