var gatilho = null;
function abrirModal(fundo) { gatilho = document.activeElement; fundo.hidden = false; var alvo = fundo.querySelector('[data-foco]') || fundo.querySelector('button'); if (alvo) alvo.focus(); }
function fecharModal(fundo) { fundo.hidden = true; if (gatilho) gatilho.focus(); }
document.querySelectorAll('[data-abrir]').forEach(function (b) { b.addEventListener('click', function () { abrirModal(document.getElementById(b.getAttribute('data-abrir'))); }); });
document.addEventListener('keydown', function (e) {
  var aberto = document.querySelector('[data-modal]:not([hidden])');
  if (!aberto) return;
  if (e.key === 'Escape') { fecharModal(aberto); return; }
  if (e.key === 'Tab') {
    var f = aberto.querySelectorAll('button'), p = f[0], u = f[f.length - 1];
    if (e.shiftKey && document.activeElement === p) { e.preventDefault(); u.focus(); }
    else if (!e.shiftKey && document.activeElement === u) { e.preventDefault(); p.focus(); }
  }
});
@@ FIM
