<script>
(function(){
  var ultimo=null;
  var gaveta=document.getElementById('gaveta');
  var ajuda=document.querySelector('[aria-controls="gaveta"]');
  var foc='a[href],button:not([disabled]),input:not([disabled]),select,textarea,[tabindex]:not([tabindex="-1"])';
  function modalAberto(){return document.querySelector('.modal:not([hidden])');}
  function abrir(m){ultimo=document.activeElement;m.hidden=false;var f=m.querySelectorAll(foc);(f[0]||m).focus();}
  function fechar(m){m.hidden=true;if(ultimo&&ultimo.focus)ultimo.focus();}
  function gavetaToggle(abrirIt){
    gaveta.hidden=!abrirIt;
    ajuda.setAttribute('aria-expanded',String(abrirIt));
    if(abrirIt){gaveta.querySelector(foc).focus();}else{ajuda.focus();}
  }
  ajuda.addEventListener('click',function(){gavetaToggle(gaveta.hidden);});
  document.addEventListener('click',function(e){
    var t=e.target;
    var a=t.closest('[data-abrir]');
    if(a){abrir(document.getElementById(a.dataset.abrir));return;}
    if(t.closest('[data-fechar-gaveta]')){gavetaToggle(false);return;}
    var d=t.closest('[data-dispensar]');
    if(d){d.closest('.banner').hidden=true;return;}
    var c=t.closest('.modal-x,[data-fechar]');
    if(c){fechar(c.closest('.modal'));return;}
    if(t.classList.contains('modal')){fechar(t);}
  });
  document.addEventListener('keydown',function(e){
    var m=modalAberto();
    if(e.key==='Escape'){
      if(m){fechar(m);}else if(!gaveta.hidden){gavetaToggle(false);}
      return;
    }
    if(e.key==='Tab'&&m){
      var f=m.querySelectorAll(foc);
      if(!f.length)return;
      var p=f[0],u=f[f.length-1];
      if(e.shiftKey&&document.activeElement===p){e.preventDefault();u.focus();}
      else if(!e.shiftKey&&document.activeElement===u){e.preventDefault();p.focus();}
    }
  });
})();
</script>
