<script>
(function(){
  var form=document.querySelector('form');
  var resumo=document.getElementById('resumo-erros');
  var lista=document.getElementById('lista-erros');
  var titulo=document.getElementById('titulo-erros');
  var tituloBase='Etapa 3 de 5 - Documentos - Instituto Horizonte';
  var msgs={
    nome:'informe nome e sobrenome.',
    cpf:'informe o CPF com 11 dígitos, por exemplo 111.444.777-35.',
    dia:'informe o dia, de 1 a 31.',
    mes:'informe o mês, de 1 a 12.',
    ano:'informe o ano de nascimento com 4 dígitos, por exemplo 1970.',
    email:'informe um e-mail válido, por exemplo nome@exemplo.com.br.',
    tel:'informe o telefone com DDD e 9 dígitos, por exemplo (11) 91234-5678.',
    'cep-res':'informe o CEP com 8 dígitos, por exemplo 80020-000.',
    'cep-cor':'informe o CEP com 8 dígitos, por exemplo 80020-000.',
    aceite:'marque que leu e aceita os termos de uso.'
  };
  function rotulo(c){
    var l=document.querySelector('label[for="'+c.id+'"]')||c.closest('label');
    return l.textContent.replace(/\s*\*\s*$/,'').trim();
  }
  function validar(todos,focar){
    var itens=[];
    form.querySelectorAll('input,select').forEach(function(c){
      if(!c.id||c.disabled||c.type==='file')return;
      if(!todos&&!c.hasAttribute('aria-invalid'))return;
      var eid='e-'+c.id,e=document.getElementById(eid),campo=c.closest('.campo');
      var desc=(c.getAttribute('aria-describedby')||'').split(' ').filter(Boolean);
      if(!c.checkValidity()){
        var msg=msgs[c.id]||(c.validity.valueMissing?'preencha este campo.':c.validationMessage);
        var txt=rotulo(c)+': '+msg;
        if(!e){
          e=document.createElement('p');e.className='erro';e.id=eid;
          (campo||c.closest('label').parentNode).appendChild(e);
        }
        e.textContent='';
        var sr=document.createElement('span');sr.className='sr';sr.textContent='Erro: ';
        e.appendChild(sr);
        e.appendChild(document.createTextNode(msg.charAt(0).toUpperCase()+msg.slice(1)));
        c.setAttribute('aria-invalid','true');
        if(desc.indexOf(eid)<0)desc.push(eid);
        c.setAttribute('aria-describedby',desc.join(' '));
        if(campo)campo.classList.add('tem-erro');
        itens.push({id:c.id,txt:txt});
      }else{
        if(e)e.remove();
        c.removeAttribute('aria-invalid');
        desc=desc.filter(function(x){return x!==eid});
        if(desc.length)c.setAttribute('aria-describedby',desc.join(' '));else c.removeAttribute('aria-describedby');
        if(campo)campo.classList.remove('tem-erro');
      }
    });
    if(itens.length){
      lista.textContent='';
      itens.forEach(function(i){
        var li=document.createElement('li'),a=document.createElement('a');
        a.href='#'+i.id;a.textContent=i.txt;li.appendChild(a);lista.appendChild(li);
      });
      titulo.textContent='Há '+itens.length+(itens.length>1?' problemas':' problema')+' nesta etapa';
      resumo.hidden=false;
      document.title='Erro: '+tituloBase;
      if(focar)resumo.focus();
    }else{
      resumo.hidden=true;
      document.title=tituloBase;
    }
    return itens.length===0;
  }
  form.addEventListener('submit',function(e){
    if(!validar(true,true))e.preventDefault();
  });
  form.addEventListener('change',function(e){
    if(e.target.hasAttribute&&e.target.hasAttribute('aria-invalid'))validar(false,false);
  });
  if(!resumo.hidden)resumo.focus();

  var mesmo=form.elements.mesmo;
  var bloco=document.getElementById('cep-cor').closest('.bloco-end');
  mesmo.addEventListener('change',function(){
    bloco.hidden=mesmo.checked;
    bloco.querySelectorAll('input,select').forEach(function(d){d.disabled=mesmo.checked});
  });

  var abas=[].slice.call(document.querySelectorAll('[role=tab]'));
  function ativar(a,foco){
    abas.forEach(function(t){
      var s=t===a;
      t.setAttribute('aria-selected',s);
      t.tabIndex=s?0:-1;
      t.classList.toggle('aba-ativa',s);
      document.getElementById(t.getAttribute('aria-controls')).hidden=!s;
    });
    if(foco)a.focus();
  }
  abas.forEach(function(t,i){
    t.addEventListener('click',function(){ativar(t,false)});
    t.addEventListener('keydown',function(e){
      var n=e.key==='ArrowRight'?i+1:e.key==='ArrowLeft'?i-1:e.key==='Home'?0:e.key==='End'?abas.length-1:null;
      if(n===null)return;
      e.preventDefault();
      ativar(abas[(n+abas.length)%abas.length],true);
    });
  });
  document.querySelectorAll('[data-aba]').forEach(function(b){
    b.addEventListener('click',function(){ativar(document.getElementById(b.getAttribute('data-aba')),true)});
  });
})();
</script>
