<script>
(function(){
  var gaveta=document.getElementById('gaveta');
  var btnAjuda=document.querySelector('[aria-controls="gaveta"]');
  var origem=null;
  function setGaveta(abrir){
    gaveta.classList.toggle('aberta',abrir);
    btnAjuda.setAttribute('aria-expanded',String(abrir));
    if(abrir){gaveta.querySelector('button,a').focus();}else{btnAjuda.focus();}
  }
  function abrirModal(m,de){
    origem=de;m.hidden=false;document.body.style.overflow='hidden';
    m.querySelector('input,button').focus();
  }
  function fecharModal(m){
    m.hidden=true;document.body.style.overflow='';
    if(origem){origem.focus();}
  }
  document.addEventListener('click',function(e){
    var t=e.target,a=t.closest('[data-abre]');
    if(a){e.preventDefault();abrirModal(document.getElementById(a.dataset.abre),a);return;}
    var f=t.closest('.modal-x,[data-fechar]');
    if(f){fecharModal(f.closest('.modal'));return;}
    if(t.classList.contains('modal')){fecharModal(t);return;}
    if(t.closest('[aria-controls="gaveta"]')){setGaveta(!gaveta.classList.contains('aberta'));return;}
    if(t.closest('[data-fechar-gaveta]')){setGaveta(false);return;}
    var d=t.closest('.banner .btn-txt');
    if(d){d.closest('.banner').remove();document.getElementById('conteudo').focus();}
  });
  document.addEventListener('keydown',function(e){
    var m=document.querySelector('.modal:not([hidden])');
    if(e.key==='Escape'){
      if(m){fecharModal(m);}
      else if(gaveta.classList.contains('aberta')){setGaveta(false);}
      return;
    }
    if(e.key==='Tab'&&m){
      var els=m.querySelectorAll('a[href],button,input'),
          p=els[0],u=els[els.length-1];
      if(e.shiftKey&&document.activeElement===p){e.preventDefault();u.focus();}
      else if(!e.shiftKey&&document.activeElement===u){e.preventDefault();p.focus();}
    }
  });
})();
</script>
</body>
