<script>
(function(){
  var gatilho=null;
  function abrir(m,g){
    gatilho=g||document.activeElement;
    m.hidden=false;
    var f=m.querySelector('input')||m.querySelector('.modal-acoes .btn')||m.querySelector('.modal-x');
    if(f)f.focus();
  }
  function fechar(m){
    m.hidden=true;
    if(gatilho&&gatilho.focus)gatilho.focus();
  }
  document.querySelectorAll('[data-abre]').forEach(function(b){
    b.addEventListener('click',function(e){
      e.preventDefault();
      abrir(document.getElementById(b.getAttribute('data-abre')),b);
    });
  });
  document.querySelectorAll('.modal').forEach(function(m){
    m.querySelectorAll('.modal-x,.modal-acoes .btn:not(.btn-prim):not(.btn-perigo)').forEach(function(b){
      b.addEventListener('click',function(){fechar(m);});
    });
    m.addEventListener('click',function(e){if(e.target===m)fechar(m);});
    m.addEventListener('keydown',function(e){
      if(e.key==='Escape'){fechar(m);return;}
      if(e.key!=='Tab')return;
      var fs=m.querySelectorAll('a[href],button:not([disabled]),input:not([disabled])');
      if(!fs.length)return;
      var a=fs[0],z=fs[fs.length-1];
      if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus();}
      else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus();}
    });
  });
  var form=document.getElementById('conv-form');
  if(form){
    var inp=document.getElementById('conv-email'),erro=document.getElementById('conv-erro');
    form.addEventListener('submit',function(e){
      e.preventDefault();
      if(!inp.checkValidity()){
        erro.hidden=false;
        inp.setAttribute('aria-invalid','true');
        inp.focus();
      }else{
        erro.hidden=true;
        inp.removeAttribute('aria-invalid');
        fechar(document.getElementById('m0'));
      }
    });
    inp.addEventListener('input',function(){
      if(inp.checkValidity()){erro.hidden=true;inp.removeAttribute('aria-invalid');}
    });
  }
  var ajuda=document.querySelector('[aria-controls="gaveta"]'),gav=document.getElementById('gaveta');
  function alternar(abrirGav){
    gav.hidden=!abrirGav;
    ajuda.setAttribute('aria-expanded',String(abrirGav));
  }
  ajuda.addEventListener('click',function(){alternar(gav.hidden);});
  gav.addEventListener('keydown',function(e){if(e.key==='Escape'){alternar(false);ajuda.focus();}});
  document.querySelectorAll('.banner .btn-txt').forEach(function(b){
    b.addEventListener('click',function(){b.closest('.banner').remove();});
  });
})();
</script>
</body>
