document.querySelectorAll('[data-fechar]').forEach(function (b) { b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); }); });
document.addEventListener('keydown', function (e) {
  var m = document.querySelector('[data-modal]:not([hidden])');
  if (!m) return;
  if (e.key === 'Escape') { fecharModal(m); return; }
  if (e.key === 'Tab') {
    var f = m.querySelectorAll('button');
    var p = f[0], u = f[f.length - 1];
    if (e.shiftKey && document.activeElement === p) { e.preventDefault(); u.focus(); }
    else if (!e.shiftKey && document.activeElement === u) { e.preventDefault(); p.focus(); }
  }
});
