<script>
(function(){
  var d=document,gav=d.getElementById('gaveta'),bAj=d.querySelector('[aria-controls="gaveta"]'),ult=null;
  function gaveta(a){gav.classList.toggle('aberta',a);bAj.setAttribute('aria-expanded',a?'true':'false');}
  bAj.addEventListener('click',function(){gaveta(!gav.classList.contains('aberta'));});
  gav.querySelector('[data-fechar-gaveta]').addEventListener('click',function(){gaveta(false);bAj.focus();});
  d.addEventListener('click',function(e){
    if(gav.classList.contains('aberta')&&!gav.contains(e.target)&&!bAj.contains(e.target))gaveta(false);
  });
  function focaveis(m){
    return [].slice.call(m.querySelectorAll('a[href],button,input,select,textarea')).filter(function(x){return !x.disabled;});
  }
  function abrir(m,gatilho){
    ult=gatilho;m.hidden=false;d.body.style.overflow='hidden';
    (m.querySelector('input')||focaveis(m)[0]).focus();
  }
  function fechar(m){
    m.hidden=true;d.body.style.overflow='';
    if(ult&&ult.focus)ult.focus();
  }
  d.querySelectorAll('[data-abrir]').forEach(function(a){
    a.addEventListener('click',function(e){e.preventDefault();abrir(d.getElementById(a.getAttribute('data-abrir')),a);});
  });
  d.querySelectorAll('.modal').forEach(function(m){
    m.addEventListener('click',function(e){
      if(e.target===m||e.target.closest('.modal-x,[data-fechar]'))fechar(m);
    });
  });
  d.addEventListener('keydown',function(e){
    var m=d.querySelector('.modal:not([hidden])');
    if(e.key==='Escape'){
      if(m)fechar(m);
      else if(gav.classList.contains('aberta')){gaveta(false);bAj.focus();}
      return;
    }
    if(e.key==='Tab'&&m){
      var f=focaveis(m),p=f[0],u=f[f.length-1];
      if(e.shiftKey&&d.activeElement===p){e.preventDefault();u.focus();}
      else if(!e.shiftKey&&d.activeElement===u){e.preventDefault();p.focus();}
    }
  });
  var form=d.querySelector('#m0 form'),inp=d.getElementById('conv-email'),erro=d.getElementById('conv-erro');
  form.addEventListener('submit',function(e){
    var ok=inp.checkValidity();
    inp.setAttribute('aria-invalid',ok?'false':'true');
    erro.hidden=ok;
    if(!ok){e.preventDefault();inp.focus();}
  });
  inp.addEventListener('input',function(){
    if(inp.getAttribute('aria-invalid')==='true'&&inp.checkValidity()){
      inp.setAttribute('aria-invalid','false');erro.hidden=true;
    }
  });
  d.querySelectorAll('.banner .btn-txt').forEach(function(b){
    b.addEventListener('click',function(){
      b.closest('.banner').remove();
      d.getElementById('conteudo').focus();
    });
  });
})();
</script>
</body>
