var _abriu=null,_linha=null,_t=null;
function $(i){return document.getElementById(i)}
function brl(n){return n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}
function num(t){return parseFloat(t.replace(/[^\d,]/g,'').replace(',','.'))||0}
var FRETE={eco:[20.9,'Econômica','6 a 8 dias úteis'],pad:[34.4,'Padrão','3 a 5 dias úteis'],exp:[61.9,'Expressa','1 a 2 dias úteis']};
function buscarCep(){
  var s=$('cep-status'),c=$('ent-cep'),p=$('prazo-status'),d=c.value.replace(/\D/g,'');
  if(d.length!==8){s.textContent='Informe um CEP com 8 dígitos.';c.focus();return;}
  s.textContent='Buscando endereço…';p.hidden=false;
  fetch('https://viacep.com.br/ws/'+d+'/json/').then(function(r){if(!r.ok)throw 0;return r.json()}).then(function(j){
    if(j.erro){s.textContent='CEP não encontrado. Preencha o endereço manualmente.';return;}
    $('ent-rua').value=j.logradouro?j.logradouro+', ':'';
    $('ent-cidade').value=j.localidade||'';
    if(j.uf)$('ent-uf').value=j.uf;
    s.textContent='Endereço localizado. Complete com o número.';
    $('ent-rua').focus();
  }).catch(function(){s.textContent='Não foi possível buscar o CEP agora. Preencha o endereço manualmente.'}).then(function(){p.hidden=true});
}
@@ FIM

