(function () {
  var foc = 'button:not([disabled]),[href],input,select,textarea,[tabindex]:not([tabindex="-1"])';
  var aberto = null, retorno = null;

  document.querySelectorAll('#acessos tbody .btn').forEach(function (b) {
    var th = b.closest('tr').querySelector('th');
    if (th) b.setAttribute('aria-label', b.textContent.trim() + ': ' + th.textContent.trim());
  });

  function abrir(fundo, gatilho) {
    retorno = gatilho; aberto = fundo; fundo.hidden = false;
    document.body.style.overflow = 'hidden';
    (fundo.querySelector('[data-inicial]') || fundo.querySelector('.btn')).focus();
  }
  function fechar() {
    if (!aberto) return;
    aberto.hidden = true; aberto = null;
    document.body.style.overflow = '';
    if (retorno) retorno.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var fundo = document.getElementById(b.getAttribute('data-abrir'));
      var tr = b.closest('tr'), th = tr && tr.querySelector('th');
      if (th && fundo.id === 'fundo-revogar') {
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + th.textContent.trim() + '?';
      }
      abrir(fundo, b);
    });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) { b.addEventListener('click', fechar); });
  document.querySelectorAll('[data-modal]').forEach(function (f) {
    f.addEventListener('mousedown', function (e) { if (e.target === f) fechar(); });
  });
  document.addEventListener('keydown', function (e) {
    if (!aberto) return;
    if (e.key === 'Escape') { fechar(); return; }
    if (e.key !== 'Tab') return;
    var l = aberto.querySelectorAll(foc), p = l[0], u = l[l.length - 1];
    if (e.shiftKey && document.activeElement === p) { e.preventDefault(); u.focus(); }
    else if (!e.shiftKey && document.activeElement === u) { e.preventDefault(); p.focus(); }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    var h = document.getElementById('h-pref');
    document.getElementById('banner-sucesso').hidden = true;
    h.setAttribute('tabindex', '-1');
    h.focus();
  });

  var resumo = document.getElementById('resumo-erros');
  ['email', 'telefone'].forEach(function (id) {
    var c = document.getElementById(id);
