      var n = resumo.querySelectorAll('li:not([hidden])').length;
      resumo.hidden = n === 0;
      document.getElementById('resumo-t').textContent = 'Corrija ' + n + (n === 1 ? ' campo' : ' campos') + ' para salvar o perfil';
