  function ativar(aba,foco){
    abas.forEach(function(a){
      var sel=a===aba;
      a.setAttribute('aria-selected',sel);
      a.tabIndex=sel?0:-1;
      document.getElementById(a.getAttribute('aria-controls')).hidden=!sel;
    });
    if(foco)aba.focus();
  }
  abas.forEach(function(a,i){
    a.addEventListener('click',function(){ativar(a,false)});
    a.addEventListener('keydown',function(e){
      var n=null;
      if(e.key==='ArrowRight')n=abas[(i+1)%abas.length];
      else if(e.key==='ArrowLeft')n=abas[(i-1+abas.length)%abas.length];
      else if(e.key==='Home')n=abas[0];
      else if(e.key==='End')n=abas[abas.length-1];
      if(n){e.preventDefault();ativar(n,true)}
    });
  });
})();
</script>
