  modal.querySelectorAll('input').forEach(function (i) { i.value = ''; i.removeAttribute('aria-invalid'); });
  modal.querySelectorAll('.erro').forEach(function (e) { e.hidden = true; });
  modal.hidden = false;
  document.body.style.overflow = 'hidden';
  (modal.querySelector('[data-foco-inicial]') || modal.querySelector('button')).focus();
}
function fecharModal(modal) {
  modal.hidden = true;
  document.body.style.overflow = '';
  if (ultimoGatilho) { ultimoGatilho.focus(); }
}
document.querySelectorAll('[data-abrir]').forEach(function (b) {
  var alvo = b.getAttribute('data-abrir');
  var linha = b.closest('tr');
  if (alvo === 'fundo-revogar' && linha) {
    b.setAttribute('aria-label', 'Revogar acesso de ' + linha.querySelector('th').textContent.trim());
  }
  b.addEventListener('click', function () {
    if (alvo === 'fundo-revogar' && linha) {
      var nome = linha.querySelector('th').textContent.trim();
      document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + nome + '?';
      document.getElementById('revogar-app').textContent = nome;
    }
    abrirModal(document.getElementById(alvo), b);
  });
});
document.querySelectorAll('#acessos tbody button:not([data-abrir])').forEach(function (b) {
