  document.dispatchEvent(new CustomEvent('conta:excluir'));
  fecharModal(document.getElementById('fundo-excluir'));
});
var tituloBase = 'Configurações da conta - Colégio Novo Saber';
var regrasPerfil = {
  email: function (v) { return /^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/.test(v.trim()); },
  telefone: function (v) { var n = v.replace(/\D/g, '').length; return n === 10 || n === 11; }
};
function validarPerfil() {
  var invalidos = [];
  Object.keys(regrasPerfil).forEach(function (id) {
    var campo = document.getElementById(id);
    var erro = document.getElementById('erro-' + id);
    var ok = regrasPerfil[id](campo.value);
    erro.hidden = ok;
    campo.closest('.campo').classList.toggle('campo-erro', !ok);
    if (ok) { campo.removeAttribute('aria-invalid'); campo.setAttribute('aria-describedby', 'dica-' + id); }
    else { campo.setAttribute('aria-invalid', 'true'); campo.setAttribute('aria-describedby', 'dica-' + id + ' erro-' + id); invalidos.push(id); }
  });
  document.getElementById('resumo-erros').hidden = invalidos.length === 0;
  document.querySelectorAll('#resumo-lista li').forEach(function (li) { li.hidden = invalidos.indexOf(li.getAttribute('data-campo')) === -1; });
  document.getElementById('resumo-titulo').textContent = 'Corrija ' + invalidos.length + (invalidos.length === 1 ? ' campo' : ' campos') + ' para salvar';
  document.title = (invalidos.length ? 'Erro: ' : '') + tituloBase;
  return invalidos;
}
document.getElementById('form-perfil').addEventListener('submit', function (e) {
  if (validarPerfil().length) { e.preventDefault(); document.getElementById('resumo-titulo').focus(); }
});
