<script>
(function(){
  var gaveta=document.getElementById('gaveta');
  var gatilho=document.querySelector('[aria-controls="gaveta"]');
  function gav(abrir){
    gaveta.hidden=!abrir;
    gatilho.setAttribute('aria-expanded',String(abrir));
    if(abrir){gaveta.querySelector('a,button').focus();}else{gatilho.focus();}
  }
  gatilho.addEventListener('click',function(){gav(gaveta.hidden);});
  document.querySelectorAll('[data-fechar-gaveta]').forEach(function(b){
    b.addEventListener('click',function(){gav(false);});
  });
  document.querySelectorAll('[data-dispensar]').forEach(function(b){
    b.addEventListener('click',function(){
      b.closest('.banner').remove();
      document.getElementById('conteudo').focus();
    });
  });
  var anterior=null;
  window.abrirModal=function(id){
    var m=document.getElementById(id);
    anterior=document.activeElement;
    m.hidden=false;
    (m.querySelector('input')||m.querySelector('[data-fechar]')||m.querySelector('button')).focus();
  };
  function fechar(m){m.hidden=true;if(anterior){anterior.focus();}}
  document.querySelectorAll('.modal').forEach(function(m){
    m.querySelectorAll('.modal-x,[data-fechar]').forEach(function(b){
      b.addEventListener('click',function(){fechar(m);});
    });
  });
  document.addEventListener('keydown',function(e){
    var m=document.querySelector('.modal:not([hidden])');
    if(e.key==='Escape'){
      if(m){fechar(m);}else if(!gaveta.hidden){gav(false);}
      return;
    }
    if(e.key==='Tab'&&m){
      var f=m.querySelectorAll('a[href],button,input,select,textarea');
      if(!f.length){return;}
      var a=f[0],z=f[f.length-1];
      if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus();}
      else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus();}
    }
  });
  var em=document.getElementById('conv-email'),er=document.getElementById('conv-erro');
  function erro(mostrar){
    er.hidden=!mostrar;
    if(mostrar){em.setAttribute('aria-invalid','true');em.setAttribute('aria-describedby','conv-erro');}
    else{em.removeAttribute('aria-invalid');em.removeAttribute('aria-describedby');}
  }
  em.addEventListener('blur',function(){erro(em.value!==''&&!em.validity.valid);});
  em.addEventListener('invalid',function(){erro(true);});
  em.addEventListener('input',function(){if(em.validity.valid){erro(false);}});
})();
</script>
</body>
