  var tituloBase='Titular e contato - Banco Aurora';
  var msgs={
    cpf:'Informe o CPF com 11 dígitos, sem pontos ou traço.',
    email:'Informe um e-mail completo, como nome@exemplo.com.br.',
    tel:'Informe o telefone com DDD e 9 dígitos, como (11) 91234-5678.',
    'cep-res':'Informe o CEP com 8 dígitos, como 80020-290.',
    'cep-cor':'Informe o CEP com 8 dígitos, como 80020-290.',
    dia:'Informe o dia de nascimento, de 1 a 31.',
    mes:'Informe o mês de nascimento, de 1 a 12.',
    ano:'Informe o ano de nascimento com 4 dígitos, como 1988.',
    aceite:'Marque que leu e aceita os termos para continuar.'
  };
  function rotulo(c){
    if(c.dataset.nome)return c.dataset.nome;
    var l=document.querySelector('label[for="'+c.id+'"]')||c.closest('label');
    return l?l.textContent.replace('*','').replace(/\s+/g,' ').trim():c.name;
  }
  function marcar(c,msg){
    var campo=c.closest('.campo')||c.closest('.check');
    var e=document.getElementById('e-'+c.id);
    var ids=(c.getAttribute('aria-describedby')||'').split(' ').filter(Boolean);
    if(msg){
      c.setAttribute('aria-invalid','true');
      if(campo.classList.contains('campo'))campo.classList.add('tem-erro');
      if(!e){
        e=document.createElement('p');e.className='erro';e.id='e-'+c.id;
        if(campo.classList.contains('check'))campo.insertAdjacentElement('afterend',e);else campo.appendChild(e);
      }
      e.innerHTML='<span class="sr">Erro:</span> ';
      e.appendChild(document.createTextNode(msg));
      if(ids.indexOf(e.id)<0)ids.push(e.id);
      c.setAttribute('aria-describedby',ids.join(' '));
    }else{
      c.removeAttribute('aria-invalid');
      if(campo)campo.classList.remove('tem-erro');
      if(e)e.remove();
      ids=ids.filter(function(i){return i!=='e-'+c.id;});
      if(ids.length)c.setAttribute('aria-describedby',ids.join(' '));else c.removeAttribute('aria-describedby');
    }
  }
  form.noValidate=true;
  form.addEventListener('submit',function(ev){
    var erros=[];
    [].forEach.call(form.elements,function(c){
      if(!c.id||!c.willValidate)return;
      var msg='';
      if(!c.checkValidity())msg=msgs[c.id]||(c.validity.valueMissing?'Preencha este campo.':'Confira o valor informado neste campo.');
      marcar(c,msg);
      if(msg)erros.push({c:c,msg:msg});
    });
    if(erros.length){
      ev.preventDefault();
      lista.innerHTML='';
      erros.forEach(function(x){
        var li=document.createElement('li'),a=document.createElement('a');
        a.href='#'+x.c.id;a.textContent=rotulo(x.c)+': '+x.msg;
        li.appendChild(a);lista.appendChild(li);
      });
      titulo.textContent=erros.length===1?'Há 1 problema nesta etapa':'Há '+erros.length+' problemas nesta etapa';
      resumo.hidden=false;
      document.title='Erro: '+tituloBase;
      resumo.focus();
    }else{
      resumo.hidden=true;
      document.title=tituloBase;
    }
  });
  lista.addEventListener('click',function(ev){
    var a=ev.target.closest('a');if(!a)return;
    ev.preventDefault();
    var alvo=document.getElementById(a.getAttribute('href').slice(1));
    if(alvo)alvo.focus();
  });
  form.addEventListener('input',function(ev){
    var c=ev.target;
    if(c.getAttribute&&c.getAttribute('aria-invalid')==='true'&&c.checkValidity())marcar(c,'');
  });
  var tel=document.getElementById('tel');
  tel.addEventListener('input',function(){
    var d=tel.value.replace(/\D/g,'').slice(0,11),s=d;
    if(d.length>10)s='('+d.slice(0,2)+') '+d.slice(2,7)+'-'+d.slice(7);
    else if(d.length>6)s='('+d.slice(0,2)+') '+d.slice(2,6)+'-'+d.slice(6);
    else if(d.length>2)s='('+d.slice(0,2)+') '+d.slice(2);
    else if(d.length>0)s='('+d;
    tel.value=s;
  });
  var mesmo=document.getElementById('mesmo'),bloco=document.getElementById('bloco-cor');
  function alternar(){
    bloco.hidden=mesmo.checked;
    [].forEach.call(bloco.querySelectorAll('input,select'),function(c){c.disabled=mesmo.checked;});
  }
  mesmo.addEventListener('change',alternar);alternar();
  var abas=[].slice.call(document.querySelectorAll('[role=tab]'));
  function selecionar(t,foco){
    abas.forEach(function(a){
      var on=a===t;
      a.setAttribute('aria-selected',on?'true':'false');
      a.tabIndex=on?0:-1;
      a.classList.toggle('aba-ativa',on);
      document.getElementById(a.getAttribute('aria-controls')).hidden=!on;
    });
    if(foco)t.focus();
  }
  abas.forEach(function(a,i){
    a.addEventListener('click',function(){selecionar(a);});
    a.addEventListener('keydown',function(ev){
      var n=ev.key==='ArrowRight'?i+1:ev.key==='ArrowLeft'?i-1:ev.key==='Home'?0:ev.key==='End'?abas.length-1:null;
      if(n===null)return;
      ev.preventDefault();
      selecionar(abas[(n+abas.length)%abas.length],true);
    });
  });
  if(!resumo.hidden)resumo.focus();
})();
</script>
