<script>
(function(){
  var gatilho=null;
  var focaveis='a[href],button:not([disabled]),input:not([disabled]),select,textarea,[tabindex]:not([tabindex="-1"])';
  var g=document.getElementById('gaveta');
  var bt=document.getElementById('abrir-ajuda');

  function visiveis(raiz){
    return [].filter.call(raiz.querySelectorAll(focaveis),function(x){return x.getClientRects().length>0;});
  }
  function abrirModal(m,origem){
    gatilho=origem||document.activeElement;
    m.hidden=false;
    document.body.style.overflow='hidden';
    var l=visiveis(m);
    if(l.length)l[0].focus();
  }
  function fecharModal(m){
    m.hidden=true;
    document.body.style.overflow='';
    if(gatilho&&gatilho.focus)gatilho.focus();
  }
  function fecharGaveta(devolverFoco){
    if(!g.classList.contains('aberta'))return;
    g.classList.remove('aberta');
    bt.setAttribute('aria-expanded','false');
    if(devolverFoco)bt.focus();
  }

  bt.addEventListener('click',function(){
    var aberta=g.classList.toggle('aberta');
    bt.setAttribute('aria-expanded',String(aberta));
    if(aberta)visiveis(g)[0].focus();
  });

  document.addEventListener('click',function(e){
    var a=e.target.closest('[data-abrir]');
    if(a){e.preventDefault();abrirModal(document.getElementById(a.getAttribute('data-abrir')),a);return;}
    if(e.target.closest('[data-fechar-gaveta]')){fecharGaveta(true);return;}
    var f=e.target.closest('[data-fechar],.modal-x');
    if(f){var m=f.closest('.modal');if(m)fecharModal(m);return;}
    if(e.target.classList.contains('modal')){fecharModal(e.target);return;}
    var d=e.target.closest('[data-dispensar]');
    if(d){var b=d.closest('.banner');if(b)b.remove();}
  });

  document.addEventListener('keydown',function(e){
    var m=document.querySelector('.modal:not([hidden])');
    if(e.key==='Escape'){
      if(m)fecharModal(m);else fecharGaveta(true);
      return;
    }
    if(e.key==='Tab'&&m){
      var l=visiveis(m);
      if(!l.length)return;
      var p=l[0],u=l[l.length-1];
      if(e.shiftKey&&document.activeElement===p){e.preventDefault();u.focus();}
      else if(!e.shiftKey&&document.activeElement===u){e.preventDefault();p.focus();}
    }
  });

  var form=document.querySelector('#m0 form');
  var campo=document.getElementById('conv-email');
  var erro=document.getElementById('conv-erro');
  form.addEventListener('submit',function(e){
    e.preventDefault();
    var ok=campo.checkValidity();
    campo.setAttribute('aria-invalid',String(!ok));
    erro.hidden=ok;
    if(ok)campo.removeAttribute('aria-describedby');else campo.setAttribute('aria-describedby','conv-erro');
    if(!ok){campo.focus();return;}
    /* TODO: enviar o convite ao backend */
    form.reset();
    fecharModal(document.getElementById('m0'));
  });
})();
</script>
</body>
