(function () {
  var abertoPor = null;
  var FOCAVEIS = 'button:not([disabled]),a[href],input:not([disabled]),select,textarea';

  function modalAberto() { return document.querySelector('[data-modal]:not([hidden])'); }
  function abrir(fundo, origem) {
    abertoPor = origem;
    fundo.hidden = false;
    var alvo = fundo.querySelector('[data-foco-inicial]') || fundo.querySelector(FOCAVEIS);
    if (alvo) alvo.focus();
  }
  function fechar(fundo) {
    fundo.hidden = true;
    if (abertoPor && document.contains(abertoPor)) abertoPor.focus();
    abertoPor = null;
  }

  // Nome acessível único para botões repetidos nas tabelas
  document.querySelectorAll('tbody tr').forEach(function (tr) {
    var cab = tr.querySelector('th[scope="row"]');
    if (!cab) return;
    tr.querySelectorAll('button').forEach(function (b) {
      b.setAttribute('aria-label', b.textContent.trim() + ': ' + cab.textContent.trim());
    });
  });

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var fundo = document.getElementById(b.getAttribute('data-abrir'));
      var tr = b.closest('tr');
      var cab = tr && tr.querySelector('th[scope="row"]');
      if (fundo.id === 'fundo-revogar' && cab) {
        document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + cab.textContent.trim() + '?';
      }
      if (fundo.id === 'fundo-excluir') {
        document.getElementById('confirma-exclusao').value = '';
        document.getElementById('erro-confirma').hidden = true;
      }
      abrir(fundo, b);
    });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });

  document.getElementById('btn-confirmar-exclusao').addEventListener('click', function () {
    var campo = document.getElementById('confirma-exclusao');
    if (campo.value.trim() !== 'EXCLUIR') {
      document.getElementById('erro-confirma').hidden = false;
      campo.setAttribute('aria-invalid', 'true');
      campo.focus();
      return;
    }
    campo.removeAttribute('aria-invalid');
    fechar(document.getElementById('fundo-excluir'));
  });

  document.addEventListener('keydown', function (e) {
    var fundo = modalAberto();
    if (!fundo) return;
    if (e.key === 'Escape') { fechar(fundo); return; }
    if (e.key !== 'Tab') return;
    var itens = fundo.querySelectorAll(FOCAVEIS);
    var primeiro = itens[0], ultimo = itens[itens.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    var proximo = document.querySelector('#form-prefs input');
