function buscarCep(){
  var s=document.getElementById('cep-status'),c=document.getElementById('ent-cep').value.replace(/\D/g,'');
  if(c.length!==8){s.textContent='Informe um CEP com 8 dígitos.';return;}
  s.textContent='Buscando endereço...';
  fetch('https://viacep.com.br/ws/'+c+'/json/').then(function(r){return r.json();}).then(function(d){
    if(d.erro){s.textContent='CEP não encontrado. Preencha o endereço manualmente.';return;}
    if(d.logradouro){document.getElementById('ent-rua').value=d.logradouro;}
    document.getElementById('ent-cidade').value=d.localidade;
    document.getElementById('ent-uf').value=d.uf;
    s.textContent='Endereço localizado. Informe o número.';
    recalcular();
  }).catch(function(){s.textContent='Não foi possível buscar o CEP. Preencha o endereço manualmente.';});
}
@@ FIM

