@@ DEPOIS
function fecharDialogo(){
  document.getElementById('veu').hidden=true;
  if(ultimoFoco&&document.contains(ultimoFoco)){ultimoFoco.focus();}
}
function confirmarRemocao(){
  var tr=ultimoFoco&&ultimoFoco.closest('tr'),alvo=null;
  if(tr){
    var o=tr.nextElementSibling||tr.previousElementSibling;
    alvo=o&&o.querySelector('button');
    tr.remove();
    recalcular();
  }
  document.getElementById('veu').hidden=true;
  if(!alvo){alvo=document.getElementById('t-itens');alvo.setAttribute('tabindex','-1');}
  alvo.focus();
}
document.addEventListener('keydown',function(e){
  var v=document.getElementById('veu');
  if(v.hidden){return;}
  if(e.key==='Escape'){fecharDialogo();return;}
  if(e.key==='Tab'){
    var b=v.querySelectorAll('button'),p=b[0],u=b[b.length-1];
    if(e.shiftKey&&document.activeElement===p){e.preventDefault();u.focus();}
    else if(!e.shiftKey&&document.activeElement===u){e.preventDefault();p.focus();}
  }
});
@@ FIM

