@@ DEPOIS
function alternarCobranca(c){
  var b=document.getElementById('bloco-cobranca');
  b.hidden=c.checked;
  b.querySelector('fieldset').disabled=c.checked;
}
function alternarMetodo(){
  var cartao=document.querySelector('input[name=metodo]:checked').value==='cartao';
  ['cartao','bloco-otp'].forEach(function(id){
    var e=document.getElementById(id);
    e.hidden=!cartao;
    e.querySelectorAll('input,select,button').forEach(function(i){i.disabled=!cartao;});
  });
}
var BRL=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});
function num(t){return parseFloat(String(t).replace(/[^\d,]/g,'').replace(',','.'))||0;}
function val(id){return document.getElementById(id).value;}
function recalcular(){
  var linhas=document.querySelectorAll('#itens tbody tr'),un=0,sub=0;
  linhas.forEach(function(l){un+=num(l.children[2].textContent);sub+=num(l.children[4].textContent);});
  var r=document.querySelector('input[name=frete]:checked'),fr=0,nome='',prazo='';
  if(r){
    var lb=r.closest('label');
    fr=num(lb.querySelector('.preco').textContent);
    nome=lb.querySelector('span').firstChild.textContent.trim();
    prazo=lb.querySelector('small').textContent.replace(/[()]/g,'');
  }
  var rs=document.querySelectorAll('dl.resumo > div'),desc=num(rs[2].querySelector('dd').textContent),tot=Math.max(0,sub+fr-desc);
  document.querySelector('#itens caption').textContent=linhas.length+' produtos, '+un+' unidades';
  document.querySelector('#itens tfoot td.col-num').textContent=BRL.format(sub);
  rs[0].querySelector('dt').textContent='Subtotal ('+un+' un.)';
  rs[0].querySelector('dd').textContent=BRL.format(sub);
  rs[1].querySelector('dt').textContent='Frete '+nome;
  rs[1].querySelector('dd').textContent=BRL.format(fr);
  rs[3].querySelector('dd').textContent=BRL.format(tot);
  var pg=document.querySelector('.btn-pagar');
  pg.textContent='Pagar '+BRL.format(tot);
  pg.disabled=!linhas.length;
  var rv=document.querySelectorAll('dl.revisao > div');
  var de=rv[0].querySelector('dd');
  de.textContent='';
  de.append(val('ent-nome'),document.createElement('br'),val('ent-rua')+' - '+val('ent-cidade')+'/'+val('ent-uf')+' - CEP '+val('ent-cep'));
  rv[1].querySelector('dd').textContent=nome+', '+prazo+' ('+BRL.format(fr)+')';
  rv[3].querySelector('dd').textContent=un+' unidades em '+linhas.length+' produtos';
  document.querySelector('.lateral > .card > p').textContent=nome+': '+prazo+', para '+val('ent-cidade')+'/'+val('ent-uf')+'.';
  var sel=document.getElementById('parcelas'),at=sel.value||'1';
  sel.innerHTML='';
  for(var i=1;i<=6;i++){sel.add(new Option(i+'x de '+BRL.format(tot/i)+(i===1?' sem juros':''),i));}
  sel.value=at;
}
(function(){
  var ufs='AC AL AP AM BA CE DF ES GO MA MT MS MG PA PB PR PE PI RJ RN RS RO RR SC SP SE TO'.split(' ');
  ['ent-uf','cob-uf'].forEach(function(id){
    var s=document.getElementById(id),a=s.value;
    s.innerHTML='';
    ufs.forEach(function(u){s.add(new Option(u,u));});
    s.value=a;
  });
  document.querySelectorAll('input[name=metodo]').forEach(function(r){r.addEventListener('change',alternarMetodo);});
  document.getElementById('form-checkout').addEventListener('change',recalcular);
  alternarCobranca(document.getElementById('cob-igual'));
  alternarMetodo();
  recalcular();
})();
@@ FIM

