<script>
(function(){
  var ultimo=null;
  var foco='input,button,a[href]';
  function fechar(el){
    el.hidden=true;
    if(ultimo){ultimo.setAttribute('aria-expanded','false');ultimo.focus();ultimo=null;}
  }
  document.querySelectorAll('button[aria-controls]').forEach(function(b){
    b.addEventListener('click',function(){
      var alvo=document.getElementById(b.getAttribute('aria-controls'));
      if(!alvo)return;
      if(alvo.hidden){
        ultimo=b;alvo.hidden=false;b.setAttribute('aria-expanded','true');
        var f=alvo.querySelector(foco);if(f)f.focus();
      }else{fechar(alvo);}
    });
  });
  document.querySelectorAll('.modal').forEach(function(m){
    m.querySelectorAll('.modal-x,.modal-acoes button:not(.btn-prim):not(.btn-perigo),[data-fechar]').forEach(function(b){
      b.addEventListener('click',function(){fechar(m);});
    });
    m.addEventListener('keydown',function(e){
      if(e.key!=='Tab')return;
      var itens=m.querySelectorAll(foco);
      var a=itens[0],z=itens[itens.length-1];
      if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus();}
      else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus();}
    });
  });
  document.addEventListener('keydown',function(e){
    if(e.key!=='Escape')return;
    var aberto=document.querySelector('.modal:not([hidden]),.gaveta:not([hidden])');
    if(aberto)fechar(aberto);
  });
})();
</script>
</body>
