function buscarCep(){
  var s=document.getElementById('cep-status'),i=document.getElementById('ent-cep'),cep=i.value.replace(/\D/g,'');
  if(cep.length!==8){s.textContent='CEP inválido. Digite 8 números.';i.focus();return;}
  s.textContent='Buscando endereço...';
  fetch('https://viacep.com.br/ws/'+cep+'/json/').then(function(r){if(!r.ok){throw new Error('http');}return r.json();}).then(function(d){
    if(d.erro){s.textContent='CEP não encontrado. Preencha o endereço manualmente.';return;}
    var rua=document.getElementById('ent-rua');
    rua.value=d.logradouro?d.logradouro+', ':'';
    document.getElementById('ent-cidade').value=d.localidade||'';
    document.getElementById('ent-uf').value=d.uf||'';
    s.textContent='Endereço localizado. Informe o número.';
    atualizar();rua.focus();
  }).catch(function(){s.textContent='Não foi possível buscar o CEP agora. Preencha o endereço manualmente.';});
}
@@ FIM

