    if (!e) { e = document.createElement('p'); e.className = 'erro'; e.id = 'erro-' + r.id; c.appendChild(e); }
    e.textContent = 'Erro: ' + r.msg;
    e.hidden = false;
    c.classList.add('campo-erro');
    inp.setAttribute('aria-invalid', 'true');
    inp.setAttribute('aria-describedby', (base + ' erro-' + r.id).trim());
  }
  function validar() {
    var erros = [], ul = resumo.querySelector('ul');
    ul.textContent = '';
    regras.forEach(function (r) {
      var falhou = !r.ok(document.getElementById(r.id).value);
      marcar(r, falhou);
      if (falhou) {
        erros.push(r);
        var li = document.createElement('li'), a = document.createElement('a');
        a.href = '#' + r.id;
        a.textContent = r.msg;
        a.addEventListener('click', function (ev) { ev.preventDefault(); document.getElementById(r.id).focus(); });
        li.appendChild(a);
        ul.appendChild(li);
      }
    });
    resumo.querySelector('h2').textContent = erros.length === 1 ? 'Corrija 1 campo para salvar' : 'Corrija ' + erros.length + ' campos para salvar';
    resumo.hidden = erros.length === 0;
    return erros;
  }
  form.addEventListener('submit', function (e) {
    var erros = validar();
    if (erros.length) {
      e.preventDefault();
      document.getElementById('banner-sucesso').hidden = true;
      resumo.focus();
    }
  });
  form.addEventListener('input', function () { if (!resumo.hidden) validar(); });
  form.addEventListener('reset', function () { regras.forEach(function (r) { marcar(r, false); }); resumo.hidden = true; });
})();
