(function () {
  var live = document.getElementById('live');
  var fora = document.querySelectorAll('.pular,.topo,.layout,.rodape');
  var aberto = null, gatilho = null;

  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }
  function abrir(fundo, origem) {
    aberto = fundo; gatilho = origem;
    fundo.hidden = false;
    fora.forEach(function (e) { e.inert = true; });
    document.body.style.overflow = 'hidden';
    var seguro = fundo.querySelector('.btn:not(.perigo)');
    if (seguro) seguro.focus();
  }
  function fechar(devolverFoco) {
    if (!aberto) return;
    aberto.hidden = true;
    fora.forEach(function (e) { e.inert = false; });
    document.body.style.overflow = '';
    var volta = gatilho;
    aberto = null; gatilho = null;
    if (devolverFoco !== false && volta && document.contains(volta)) volta.focus();
  }

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () {
      if (b.hasAttribute('data-app')) {
        document.getElementById('revogar-app').textContent = b.getAttribute('data-app');
      }
      abrir(document.getElementById(b.getAttribute('data-abrir')), b);
    });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(); });
  });
  document.querySelectorAll('[data-modal]').forEach(function (f) {
    f.addEventListener('click', function (e) { if (e.target === f) fechar(); });
  });
  document.addEventListener('keydown', function (e) {
