    else if (/Encerrar/.test(b.textContent)) { b.setAttribute('aria-label', 'Encerrar sessão de ' + nome); }
  });

  var aberto = null, origem = null;
  var FOCAVEIS = 'a[href],button:not([disabled]),input,select,textarea,[tabindex]:not([tabindex="-1"])';
  function abrir(m, b) {
    origem = b; aberto = m;
    if (b.getAttribute('data-alvo')) m.querySelector('h2').textContent = 'Revogar o acesso de ' + b.getAttribute('data-alvo') + '?';
    m.hidden = false;
    (m.querySelector('[data-inicial]') || m.querySelector('button')).focus();
  }
  function fechar() {
    if (!aberto) return;
    aberto.hidden = true; aberto = null;
    if (origem) origem.focus();
  }
  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(document.getElementById(b.getAttribute('data-abrir')), b); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) { b.addEventListener('click', fechar); });
  document.querySelectorAll('[data-modal]').forEach(function (m) {
    m.addEventListener('click', function (e) { if (e.target === m) fechar(); });
  });
  document.addEventListener('keydown', function (e) {
    if (!aberto) return;
    if (e.key === 'Escape') { e.preventDefault(); fechar(); return; }
    if (e.key !== 'Tab') return;
    var f = aberto.querySelectorAll(FOCAVEIS);
    if (!f.length) return;
    var primeiro = f[0], ultimo = f[f.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });

  var form = document.getElementById('form-perfil');
  var resumo = document.getElementById('resumo-erros');
  var tituloResumo = document.getElementById('resumo-erros-t');
  var base = document.title.replace(/^Erro: /, '');
  var regras = [
    { id: 'email', ok: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()); } },
    { id: 'telefone', ok: function (v) { var d = v.replace(/\D/g, ''); return d.length === 10 || d.length === 11; } }
  ];
  function validar() {
    var erros = 0;
    regras.forEach(function (r) {
