      document.getElementById('erro-' + r.id).hidden = ok;
      document.getElementById('li-' + r.id).hidden = ok;
      campo.classList.toggle('campo-erro', !ok);
      var marca = campo.querySelector('.marca-erro');
      if (marca) marca.hidden = ok;
      if (!ok) erros++;
    });
    resumo.hidden = erros === 0;
    tituloResumo.textContent = erros === 1 ? 'Corrija 1 campo para salvar' : 'Corrija ' + erros + ' campos para salvar';
    document.title = (erros ? 'Erro: ' : '') + base;
    return erros;
  }
  form.addEventListener('submit', function (e) {
    if (validar()) { e.preventDefault(); resumo.focus(); }
  });
})();
