  var titulo = document.getElementById('resumo-t');
  var regras = {
    email: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v); },
    telefone: function (v) { return v.replace(/\D/g, '').length === 11; }
  };
  function checar(id) {
    var inp = document.getElementById(id);
    var campo = inp.closest('.campo');
    var ok = regras[id](inp.value.trim());
    var marca = campo.querySelector('.marca-erro');
    inp.setAttribute('aria-invalid', ok ? 'false' : 'true');
    campo.classList.toggle('campo-erro', !ok);
    document.getElementById('erro-' + id).hidden = ok;
    if (marca) marca.hidden = ok;
    return ok;
  }
  function atualizar() {
    var invalidos = Object.keys(regras).filter(function (id) {
      return document.getElementById(id).getAttribute('aria-invalid') === 'true';
    });
    lista.textContent = '';
    invalidos.forEach(function (id) {
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + id;
      a.textContent = document.querySelector('label[for="' + id + '"]').textContent + ': ' + document.getElementById('erro-' + id).textContent;
      a.addEventListener('click', function (e) { e.preventDefault(); document.getElementById(id).focus(); });
      li.appendChild(a);
      lista.appendChild(li);
    });
    titulo.textContent = invalidos.length === 1 ? 'Corrija 1 campo para salvar' : 'Corrija ' + invalidos.length + ' campos para salvar';
    resumo.hidden = invalidos.length === 0;
    return invalidos;
  }
  Object.keys(regras).forEach(function (id) {
    document.getElementById(id).addEventListener('change', function () { checar(id); atualizar(); });
  });
  form.addEventListener('submit', function (e) {
    Object.keys(regras).forEach(checar);
    if (atualizar().length) { e.preventDefault(); resumo.focus(); }
  });
  atualizar();
})();
