<script>
(function(){
  var gav=document.getElementById('gaveta');
  var btnAjuda=document.querySelector('[aria-controls="gaveta"]');
  var origem=null, aberto=null;

  function ajuda(abrir){
    gav.classList.toggle('aberta',abrir);
    gav.inert=!abrir;
    btnAjuda.setAttribute('aria-expanded',String(abrir));
    if(abrir){gav.querySelector('button,a').focus();}else{btnAjuda.focus();}
  }
  btnAjuda.addEventListener('click',function(){ajuda(!gav.classList.contains('aberta'));});
  gav.querySelector('[data-fechar-gaveta]').addEventListener('click',function(){ajuda(false);});

  function abrirModal(m,o){
    origem=o;aberto=m;m.hidden=false;
    var c=m.querySelector('.modal-caixa');c.setAttribute('tabindex','-1');c.focus();
  }
  function fecharModal(m){
    m.hidden=true;aberto=null;
    if(origem&&origem.focus){origem.focus();}
  }
